/// The qualified campaign route runs the source single-pass schedule. Speed
/// selection is not yet a discoverable descriptor, so the adapter pins the
/// qualified value instead of exposing an unvalidated source knob.
const CAMPAIGN_SPEED_INDEX: u8 = 0;

/// Typed failure surface for the campaign adapter and backend.
#[derive(Debug)]
pub enum CampaignBackendError {
    /// Campaign package/descriptor preflight or materialization failed.
    Open(CampaignOpenError),
    /// Neutral definition validation failed.
    Definition(DefinitionError),
    /// The definition carries a semantic value with no campaign consumption
    /// binding; accepting it would claim an unimplemented mutation.
    UnappliedSemanticValue { id: SemanticId },
    /// Session reset cannot substitute a package or artifact graph.
    PackageSubstitution,
    /// The requested event cursor is beyond the current effect head.
    CursorBeyondHead { head: u64, requested: u64 },
    /// The requested event cursor predates the retained journal.
    CursorExpired {
        first_available: u64,
        requested: u64,
    },
    /// The campaign adapter retains no positional audio sidecar.
    NoAudioSidecar { event_sequence: u64 },
    /// The source schedule rejected the step; the session is unchanged.
    StepRejected { message: String },
    /// Internal journal/cursor invariant failure.
    JournalDesync,
}

impl fmt::Display for CampaignBackendError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Open(error) => write!(formatter, "campaign open failed: {error}"),
            Self::Definition(error) => error.fmt(formatter),
            Self::UnappliedSemanticValue { id } => write!(
                formatter,
                "UNAPPLIED_SEMANTIC_VALUE: {} has no campaign consumption binding; \
                 only catalog default values are accepted",
                id.as_str()
            ),
            Self::PackageSubstitution => formatter.write_str(
                "session reset cannot substitute a package or artifact graph; reopen resources first",
            ),
            Self::CursorBeyondHead { head, requested } => write!(
                formatter,
                "event cursor {requested} is beyond current event head {head}"
            ),
            Self::CursorExpired {
                first_available,
                requested,
            } => write!(
                formatter,
                "event cursor {requested} predates the retained journal; first available cursor is {first_available}"
            ),
            Self::NoAudioSidecar { event_sequence } => write!(
                formatter,
                "event sequence {event_sequence} has no positional audio sidecar on the campaign route"
            ),
            Self::StepRejected { message } => {
                write!(formatter, "campaign schedule rejected the step: {message}")
            }
            Self::JournalDesync => {
                formatter.write_str("campaign journal cursor invariant failure")
            }
        }
    }
}

impl Error for CampaignBackendError {}

/// Validate the campaign descriptor package and adapt it into one neutral
/// immutable definition. Descriptor selectors terminate here; the resulting
/// definition exposes only semantic IDs and content identities.
///
/// Admitted ordinary missions beyond the opening sequence can be opened as
/// direct `GameSession`s. Their definitions carry no campaign flow until that
/// flow is implemented; the outer campaign resolver still requires one.
///
/// # Errors
///
/// Returns a typed error if descriptor preflight, package enumeration,
/// capability resolution, or definition materialization fails. No definition
/// is created on error.
pub fn load_mc2_campaign(
    package_root: impl AsRef<Path>,
    catalog: &SemanticCatalog,
) -> crate::game_definition::Result<GameDefinition> {
    load_mc2_campaign_internal(package_root.as_ref(), None, catalog)
        .map(|(definition, ..)| definition)
}

/// Load a campaign definition with a package-bound material cache or exact
/// owner-cache audio artifacts. Only retained audio enables semantic authoring.
pub fn load_mc2_campaign_with_owner_cache(
    package_root: impl AsRef<Path>,
    owner_cache: impl AsRef<Path>,
    catalog: &SemanticCatalog,
) -> crate::game_definition::Result<GameDefinition> {
    load_mc2_campaign_internal(package_root.as_ref(), Some(owner_cache.as_ref()), catalog)
        .map(|(definition, ..)| definition)
}

fn load_mc2_campaign_internal(
    package_root: &Path,
    owner_cache: Option<&Path>,
    catalog: &SemanticCatalog,
) -> crate::game_definition::Result<(GameDefinition, CampaignSelection, String, String)> {
    let selection = CampaignDescriptor::declared_selection(package_root).map_err(|error| {
        definition_error(
            DefinitionErrorCode::InvalidSchema,
            "mc2_campaign.package",
            format!("cannot read campaign selection: {error}"),
        )
    })?;
    let descriptor =
        CampaignDescriptor::preflight(package_root, selection, &CAMPAIGN_BEHAVIOR_REGISTRY)
            .map_err(|error| {
                definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    "mc2_campaign.package",
                    format!("campaign descriptor preflight failed: {error}"),
                )
            })?;
    let export_sha256 = descriptor.owner_export_package_sha256().map_err(|error| {
        definition_error(
            DefinitionErrorCode::HashMismatch,
            "mc2_campaign.owner_export",
            format!("cannot reconstruct wrapped owner export identity: {error}"),
        )
    })?;
    let (package_bytes, envelope_bytes) = campaign_package_bytes(package_root)?;
    let mut artifacts = vec![artifact_node(
        "campaign.owner_export",
        ArtifactKind::World,
        "campaign/owner-export",
        &export_sha256,
        package_bytes - envelope_bytes,
        &[],
    )?];
    let mut artifact_payloads = BTreeMap::new();
    let mut package_dependencies = vec!["campaign.owner_export".to_owned()];
    let mut bindings = Vec::new();
    for asset in descriptor.presentation_assets() {
        let payload = descriptor
            .read_member(&asset.member.member)
            .map_err(|error| {
                definition_error(
                    DefinitionErrorCode::HashMismatch,
                    &asset.member.member,
                    format!("cannot retain validated presentation payload: {error}"),
                )
            })?;
        artifacts.push(artifact_node(
            &asset.artifact_id,
            ArtifactKind::Asset,
            &format!("campaign/presentation/{}", asset.member.member),
            &asset.member.sha256,
            payload.len() as u64,
            &[],
        )?);
        package_dependencies.push(asset.artifact_id.clone());
        artifact_payloads.insert(asset.artifact_id.clone(), payload);
    }
    let environment_cache = owner_cache
        .map(|root| validate_campaign_environment_cache(root, &descriptor, &export_sha256))
        .transpose()?
        .unwrap_or(false);
    let mut has_owner_audio = false;
    if !environment_cache
        && selection == CampaignSelection::LEVEL1
        && let Some(owner_cache) = owner_cache
    {
        crate::native_world::qualified_campaign_owner_cache(
            owner_cache,
            &descriptor.package_sha256,
            &export_sha256,
            &descriptor.campaign_spec.reset_sources.runtime.sha256,
        )
        .map_err(|error| {
            definition_error(
                DefinitionErrorCode::HashMismatch,
                "mc2_campaign.owner_cache.bindings",
                error.to_string(),
            )
        })?;
        let audio_artifacts = crate::native_world::qualified_fireball_sound_artifacts(owner_cache)
            .map_err(|error| {
                definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    "mc2_campaign.owner_cache.fireball_audio",
                    error.to_string(),
                )
            })?;
        for artifact in &audio_artifacts {
            artifacts.push(artifact_node(
                artifact.artifact_id,
                ArtifactKind::Asset,
                artifact.logical_path,
                &artifact.content_hash,
                artifact.payload.len() as u64,
                &[],
            )?);
            package_dependencies.push(artifact.artifact_id.to_owned());
            artifact_payloads.insert(artifact.artifact_id.to_owned(), artifact.payload.clone());
        }
        let base_audio = audio_artifacts
            .first()
            .expect("qualified Fireball audio set is non-empty");
        has_owner_audio = true;
        bindings.push((
            SemanticId::parse(sim_definition::FIREBALL_LAUNCH_SOUND_ASSET_SLOT_ID)?,
            sim_definition::SemanticValue::Reference(format!("sha256:{}", base_audio.content_hash)),
        ));
    }
    let package_dependency_refs = package_dependencies
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    artifacts.push(artifact_node(
        "campaign.package",
        ArtifactKind::Definition,
        "campaign/package",
        &descriptor.package_sha256,
        package_bytes,
        &package_dependency_refs,
    )?);
    if let Some(base_asset) = descriptor.presentation_assets().first() {
        bindings.push((
            SemanticId::parse(&base_asset.slot_id)?,
            sim_definition::SemanticValue::Reference(format!(
                "sha256:{}",
                base_asset.member.sha256
            )),
        ));
    }
    bindings.push((
        SemanticId::parse(ENEMY_DEFAULT_POLICY_ID)?,
        sim_definition::SemanticValue::Enum("classic_goat_v1".to_owned()),
    ));
    let mut requirement_ids = vec![
        crate::game_definition::CREATURE_POLICY_CAPABILITY_ID,
        "engine.flight.fixed_point",
        "engine.spell.projectile",
    ];
    if descriptor
        .level_definition()
        .objectives()
        .iter()
        .any(|objective| {
            matches!(
                objective.condition(),
                sim_definition::level_definition::ObjectiveCondition::DefeatRivalWizard(_)
            )
        })
    {
        requirement_ids.push("engine.objective.defeat_rival_wizard");
    }
    if descriptor
        .level_definition()
        .objectives()
        .iter()
        .any(|objective| {
            matches!(
                objective.condition(),
                sim_definition::level_definition::ObjectiveCondition::CastleManaPercent(_)
            )
        })
    {
        requirement_ids.push("engine.objective.castle_mana_percent");
    }
    if descriptor
        .level_definition()
        .objectives()
        .iter()
        .any(|objective| {
            matches!(
                objective.condition(),
                sim_definition::level_definition::ObjectiveCondition::NoLivingCreatures(_)
            )
        })
    {
        requirement_ids.push("engine.objective.no_living_creatures");
    }
    if descriptor
        .level_definition()
        .objectives()
        .iter()
        .any(|objective| {
            matches!(
                objective.condition(),
                sim_definition::level_definition::ObjectiveCondition::NoStandingBuildings
            )
        })
    {
        requirement_ids.push("engine.objective.no_standing_buildings");
    }
    if descriptor.local_player_fireball_mana_cost().is_some() {
        requirement_ids.push(FIREBALL_MANA_COST_CAPABILITY_ID);
    }
    if descriptor
        .level_definition()
        .entities()
        .iter()
        .any(|entity| entity.experience_scroll().is_some())
    {
        requirement_ids.push(EXPERIENCE_SCROLL_AWARD_CAPABILITY_ID);
    }
    if descriptor
        .level_definition()
        .entities()
        .iter()
        .any(|entity| entity.house_construction().is_some())
    {
        requirement_ids.push(HOUSE_LIFE_MANA_SCALAR_CAPABILITY_ID);
        requirement_ids.push(HOUSE_CONSTRUCTION_VISITS_CAPABILITY_ID);
    }
    if descriptor
        .level_definition()
        .entities()
        .iter()
        .any(|entity| {
            entity.switch_overlap().is_some()
                && entity.kind()
                    == sim_definition::level_definition::LevelEntityKind::Switch(
                        sim_definition::level_definition::SwitchKind::AreaEntryTrigger,
                    )
        })
    {
        requirement_ids.push(AREA_ENTRY_OVERLAP_EXTENT_CAPABILITY_ID);
    }
    if descriptor
        .level_definition()
        .entities()
        .iter()
        .any(|entity| {
            entity.switch_overlap().is_some()
                && entity.kind()
                    == sim_definition::level_definition::LevelEntityKind::Switch(
                        sim_definition::level_definition::SwitchKind::AreaExitTrigger,
                    )
        })
    {
        requirement_ids.push(AREA_EXIT_OVERLAP_EXTENT_CAPABILITY_ID);
    }
    if descriptor
        .level_definition()
        .entities()
        .iter()
        .any(|entity| {
            entity.switch_overlap().is_some()
                && entity.kind()
                    == sim_definition::level_definition::LevelEntityKind::Switch(
                        sim_definition::level_definition::SwitchKind::ExitSequenceTrigger,
                    )
        })
    {
        requirement_ids.push(EXIT_SEQUENCE_OVERLAP_EXTENT_CAPABILITY_ID);
    }
    for entity in descriptor
        .level_definition()
        .entities()
        .iter()
        .filter(|entity| entity.creature_health().is_some())
    {
        let sim_definition::level_definition::LevelEntityKind::Creature(kind) = entity.kind()
        else {
            continue;
        };
        if let Some(capability_id) = creature_max_life_capability_id(kind)
            && !requirement_ids.contains(&capability_id)
        {
            requirement_ids.push(capability_id);
        }
    }
    if !descriptor.presentation_assets().is_empty() {
        requirement_ids.push("engine.presentation.indexed_asset");
    }
    if has_owner_audio {
        requirement_ids.push("engine.audio.semantic_asset");
    }
    let requirements = requirement_ids
        .into_iter()
        .map(|id| {
            Ok(RequiredCapability {
                id: SemanticId::parse(id)?,
                exact_version: 1,
            })
        })
        .collect::<crate::game_definition::Result<Vec<_>>>()?;
    let package = game_package_with_payloads(
        "mc2.campaign",
        1,
        requirements,
        artifacts,
        bindings,
        owner_provenance(&descriptor.package_sha256)?,
        artifact_payloads,
    )?;
    let definition = GameDefinition::from_package(package, &engine_capabilities()?, catalog)?;
    let definition = match selection {
        CampaignSelection::LEVEL1 | CampaignSelection::LEVEL2 | CampaignSelection::LEVEL3 => {
            with_level_and_runtime_flow(
                definition,
                descriptor.level_definition().clone(),
                mc2_runtime_flow(selection, descriptor.level_definition(), false)?,
            )
        }
        _ if selection == CampaignSelection::ordinary(4).expect("ordinary Cave mission") => {
            with_level_and_runtime_flow(
                definition,
                descriptor.level_definition().clone(),
                mc2_runtime_flow(selection, descriptor.level_definition(), true)?,
            )
        }
        _ if CampaignSelection::ordinary(selection.external_level) == Some(selection)
            || CampaignSelection::secret_destination(selection.internal_level)
                == Some(selection) =>
        {
            with_level_and_runtime_flow(
                definition,
                descriptor.level_definition().clone(),
                mc2_runtime_flow(selection, descriptor.level_definition(), true)?,
            )
        }
        _ => {
            return Err(definition_error(
                DefinitionErrorCode::InvalidSchema,
                "mc2_campaign.runtime_flow",
                "campaign selection has no qualified direct-mission binding",
            ));
        }
    };
    Ok((
        definition,
        descriptor.identity,
        descriptor.package_sha256,
        descriptor.campaign_spec.reset_sources.runtime.sha256,
    ))
}

fn validate_campaign_environment_cache(
    root: &Path,
    descriptor: &CampaignDescriptor,
    export_sha256: &str,
) -> crate::game_definition::Result<bool> {
    use crate::presentation::environment_materials::{CACHE_SCHEMA, EnvironmentResources};
    let invalid = |message: String| {
        definition_error(
            DefinitionErrorCode::HashMismatch,
            "mc2_campaign.owner_cache.bindings",
            message,
        )
    };
    let manifest: serde_json::Value = serde_json::from_slice(
        &fs::read(root.join("manifest.json")).map_err(|error| invalid(error.to_string()))?,
    )
    .map_err(|error| invalid(error.to_string()))?;
    if manifest.get("schema").and_then(serde_json::Value::as_str) != Some(CACHE_SCHEMA) {
        return Ok(false);
    }
    let resources = EnvironmentResources::load(root).map_err(|error| invalid(error.to_string()))?;
    let profile = resources
        .profile
        .ok_or_else(|| invalid("environment profile missing".to_owned()))?;
    let selection = descriptor.identity;
    if profile.external_level != selection.external_level
        || profile.internal_level != selection.internal_level
        || profile.map_type.id != selection.map_type_id
        || profile.campaign_package_sha256 != descriptor.package_sha256
        || profile.owner_export_package_sha256 != export_sha256
    {
        return Err(invalid(
            "environment cache does not match the opened campaign package".to_owned(),
        ));
    }
    Ok(true)
}

fn mc2_runtime_flow(
    selection: CampaignSelection,
    level: &sim_definition::level_definition::LevelDefinition,
    include_cave: bool,
) -> crate::game_definition::Result<RuntimeFlowDefinition> {
    let witnesses: &[&str] = match selection {
        CampaignSelection::LEVEL1 => &[
            "objective.reach.foot_of_spire",
            "objective.clear.spire_archers",
        ],
        CampaignSelection::LEVEL2 => &[
            "objective.defeat.nyphur",
            "objective.reach.payahandra_ruins",
        ],
        CampaignSelection::LEVEL3 => &[
            "objective.clear.guardian_dragons",
            "objective.charge.reveal_entrance",
        ],
        _ if include_cave && selection == CampaignSelection::ordinary(4).unwrap() => {
            &["objective.campaign.task_1", "objective.campaign.task_2"]
        }
        _ => &[],
    };
    for witness in witnesses {
        let objective = sim_definition::adapter::stable_objective_id(witness)?;
        if level.objective(&objective).is_none() {
            return Err(definition_error(
                DefinitionErrorCode::InvalidSchema,
                "mc2_campaign.runtime_flow",
                format!("semantic level binding is missing package witness {witness}"),
            ));
        }
    }

    let (ordinary_count, secrets) = if CampaignSelection::ordinary(selection.external_level)
        == Some(selection)
    {
        (
            selection
                .external_level
                .max(if include_cave { 4 } else { 3 }),
            Vec::new(),
        )
    } else {
        let origin = (1..=25)
            .filter_map(CampaignSelection::ordinary)
            .find(|origin| {
                super::mc2_secret_flow::association_for(*origin, selection.internal_level).is_some()
            })
            .ok_or_else(|| {
                definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    "mc2_campaign.runtime_flow",
                    "secret package has no source portal association",
                )
            })?;
        (origin.external_level, vec![selection.internal_level])
    };
    runtime_catalog::compose(selection, ordinary_count, &secrets)
}

fn campaign_package_bytes(root: &Path) -> crate::game_definition::Result<(u64, u64)> {
    let mut total = 0_u64;
    let mut envelope = 0_u64;
    for entry in fs::read_dir(root).map_err(|error| {
        definition_error(
            DefinitionErrorCode::Io,
            "mc2_campaign.package",
            format!("cannot enumerate campaign package: {error}"),
        )
    })? {
        let entry = entry.map_err(|error| {
            definition_error(
                DefinitionErrorCode::Io,
                "mc2_campaign.package",
                format!("cannot inspect campaign package: {error}"),
            )
        })?;
        let metadata = entry.metadata().map_err(|error| {
            definition_error(
                DefinitionErrorCode::Io,
                "mc2_campaign.package",
                format!("cannot inspect campaign package member: {error}"),
            )
        })?;
        let file_type = entry.file_type().map_err(|error| {
            definition_error(
                DefinitionErrorCode::Io,
                "mc2_campaign.package",
                error.to_string(),
            )
        })?;
        if !metadata.is_file() || file_type.is_symlink() {
            return Err(definition_error(
                DefinitionErrorCode::PathEscape,
                entry.path().display().to_string(),
                "campaign package contains a non-regular or symlink member",
            ));
        }
        total = total.checked_add(metadata.len()).ok_or_else(|| {
            definition_error(
                DefinitionErrorCode::OutOfRange,
                "mc2_campaign.package",
                "campaign package byte total overflows u64",
            )
        })?;
        let name = entry.file_name();
        if name == "manifest.json" || name == "campaign-definition.json" {
            envelope += metadata.len();
        }
    }
    Ok((total, envelope))
}

/// Adapter that opens the private MC2 campaign route behind the neutral
/// session contract.
pub struct Mc2CampaignAdapter;

/// Owner-local campaign package inputs. Owner bytes stay outside the neutral
/// definition and the distributable client tree.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Mc2CampaignInputs {
    pub package_root: PathBuf,
    pub owner_cache: Option<PathBuf>,
    pub dynamic_lighting_enabled: bool,
}

impl Mc2CampaignInputs {
    #[must_use]
    pub fn new(package_root: impl Into<PathBuf>) -> Self {
        Self {
            package_root: package_root.into(),
            owner_cache: None,
            dynamic_lighting_enabled: true,
        }
    }

    #[must_use]
    pub fn with_owner_cache(
        package_root: impl Into<PathBuf>,
        owner_cache: impl Into<PathBuf>,
    ) -> Self {
        Self {
            package_root: package_root.into(),
            owner_cache: Some(owner_cache.into()),
            dynamic_lighting_enabled: true,
        }
    }

    /// Bind the source-global option before constructors allocate light slots.
    #[must_use]
    pub fn with_dynamic_lighting(mut self, enabled: bool) -> Self {
        self.dynamic_lighting_enabled = enabled;
        self
    }
}

fn load_mc2_campaign_inputs(
    input: &Mc2CampaignInputs,
    catalog: &SemanticCatalog,
) -> crate::game_definition::Result<GameDefinition> {
    match &input.owner_cache {
        Some(owner_cache) => {
            load_mc2_campaign_with_owner_cache(&input.package_root, owner_cache, catalog)
        }
        None => load_mc2_campaign(&input.package_root, catalog),
    }
}

pub const MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT: &str = "carpet-flight-mc2-campaign-replay-save/v6";
const LEGACY_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT: &str = "carpet-flight-mc2-campaign-replay-save/v5";
pub const MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES: usize = 16 * 1024 * 1024;
pub const MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS: usize = 1_000_000;

const fn default_dynamic_lighting() -> bool {
    true
}

const fn dynamic_lighting_is_default(enabled: &bool) -> bool {
    *enabled
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2DynamicLightingChange {
    before_operation: usize,
    enabled: bool,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2CampaignReplaySave {
    save_contract: String,
    paused: bool,
    definition: GameDefinition,
    semantic_spell_carry: Mc2SemanticSpellCarry,
    #[serde(default, skip_serializing_if = "GlobalSpecialState::is_default")]
    initial_global_context: GlobalSpecialState,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    global_context_changes: Vec<Mc2GlobalContextChange>,
    #[serde(
        default = "default_dynamic_lighting",
        skip_serializing_if = "dynamic_lighting_is_default"
    )]
    initial_dynamic_lighting: bool,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    dynamic_lighting_changes: Vec<Mc2DynamicLightingChange>,
    // v5 did not retain the campaign frontier. Omission must remain omission
    // when checking its original receipt; it cannot imply earned completions.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    completed_levels: Option<Vec<SemanticLevelId>>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    level_statistics: Vec<crate::game_runtime::CompletedLevelStatistics>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    secret_flow: Option<crate::game_runtime::secret_flow::SecretFlowState>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    retained_campaign: Option<crate::game_runtime::CampaignSaveState>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    initial_secret_continuation: Option<sim_definition::runtime_flow::RuntimeFlowSecretEntry>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    initial_mission_rewards: Option<super::rewards::MissionRewards>,
    operations: Vec<crate::game_runtime::ReplayOperation<GameCommand>>,
    expected_tick: u64,
    expected_state_hash: u64,
    expected_terrain_hash: u64,
    expected_effect_head: u64,
    expected_effect_journal_sha256: String,
    receipt_sha256: String,
}

#[derive(Serialize)]
struct Mc2CampaignReplaySavePayload<'a> {
    save_contract: &'a str,
    paused: bool,
    definition: &'a GameDefinition,
    semantic_spell_carry: &'a Mc2SemanticSpellCarry,
    #[serde(skip_serializing_if = "GlobalSpecialState::is_default")]
    initial_global_context: &'a GlobalSpecialState,
    #[serde(skip_serializing_if = "<[Mc2GlobalContextChange]>::is_empty")]
    global_context_changes: &'a [Mc2GlobalContextChange],
    #[serde(skip_serializing_if = "dynamic_lighting_is_default")]
    initial_dynamic_lighting: bool,
    #[serde(skip_serializing_if = "<[Mc2DynamicLightingChange]>::is_empty")]
    dynamic_lighting_changes: &'a [Mc2DynamicLightingChange],
    #[serde(skip_serializing_if = "Option::is_none")]
    completed_levels: Option<&'a [SemanticLevelId]>,
    #[serde(skip_serializing_if = "<[crate::game_runtime::CompletedLevelStatistics]>::is_empty")]
    level_statistics: &'a [crate::game_runtime::CompletedLevelStatistics],
    #[serde(skip_serializing_if = "Option::is_none")]
    secret_flow: Option<&'a crate::game_runtime::secret_flow::SecretFlowState>,
    #[serde(skip_serializing_if = "Option::is_none")]
    retained_campaign: Option<&'a crate::game_runtime::CampaignSaveState>,
    #[serde(skip_serializing_if = "Option::is_none")]
    initial_secret_continuation: Option<&'a sim_definition::runtime_flow::RuntimeFlowSecretEntry>,
    #[serde(skip_serializing_if = "Option::is_none")]
    initial_mission_rewards: Option<super::rewards::MissionRewards>,
    operations: &'a [crate::game_runtime::ReplayOperation<GameCommand>],
    expected_tick: u64,
    expected_state_hash: u64,
    expected_terrain_hash: u64,
    expected_effect_head: u64,
    expected_effect_journal_sha256: &'a str,
}

impl Mc2CampaignReplaySave {
    fn new(
        paused: bool,
        definition: GameDefinition,
        semantic_spell_carry: Mc2SemanticSpellCarry,
        completed_levels: Vec<SemanticLevelId>,
        operations: Vec<crate::game_runtime::ReplayOperation<GameCommand>>,
        snapshot: &CampaignSnapshot,
    ) -> Self {
        let mut save = Self {
            save_contract: MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT.to_owned(),
            paused,
            definition,
            semantic_spell_carry,
            initial_global_context: GlobalSpecialState::default(),
            global_context_changes: Vec::new(),
            initial_dynamic_lighting: true,
            dynamic_lighting_changes: Vec::new(),
            completed_levels: Some(completed_levels),
            level_statistics: Vec::new(),
            secret_flow: None,
            retained_campaign: None,
            initial_secret_continuation: None,
            initial_mission_rewards: None,
            operations,
            expected_tick: snapshot.tick,
            expected_state_hash: snapshot.state_hash,
            expected_terrain_hash: snapshot.terrain_hash,
            expected_effect_head: snapshot.effect_head,
            expected_effect_journal_sha256: snapshot.effect_journal_sha256.clone(),
            receipt_sha256: String::new(),
        };
        save.receipt_sha256 = save.compute_receipt_sha256();
        save
    }

    fn compute_receipt_sha256(&self) -> String {
        let payload = Mc2CampaignReplaySavePayload {
            save_contract: &self.save_contract,
            paused: self.paused,
            definition: &self.definition,
            semantic_spell_carry: &self.semantic_spell_carry,
            initial_global_context: &self.initial_global_context,
            global_context_changes: &self.global_context_changes,
            initial_dynamic_lighting: self.initial_dynamic_lighting,
            dynamic_lighting_changes: &self.dynamic_lighting_changes,
            completed_levels: self.completed_levels.as_deref(),
            level_statistics: &self.level_statistics,
            secret_flow: self.secret_flow.as_ref(),
            retained_campaign: self.retained_campaign.as_ref(),
            initial_secret_continuation: self.initial_secret_continuation.as_ref(),
            initial_mission_rewards: self.initial_mission_rewards,
            operations: &self.operations,
            expected_tick: self.expected_tick,
            expected_state_hash: self.expected_state_hash,
            expected_terrain_hash: self.expected_terrain_hash,
            expected_effect_head: self.expected_effect_head,
            expected_effect_journal_sha256: &self.expected_effect_journal_sha256,
        };
        let bytes =
            serde_json::to_vec(&payload).expect("MC2 replay-save receipt payload is serializable");
        hex_digest(Sha256::digest(bytes).into())
    }

    fn verify(&self) -> bool {
        ((self.save_contract == MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT
            && self.completed_levels.is_some())
            || (self.save_contract == LEGACY_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT
                && self.completed_levels.is_none()))
            && self.receipt_sha256 == self.compute_receipt_sha256()
    }
}

#[derive(Debug)]
pub enum Mc2CampaignReplaySaveError {
    InvalidMode,
    InvalidSave { message: String },
    Definition(DefinitionError),
    Runtime(crate::game_runtime::RuntimeTransitionError),
    Restore(crate::game_runtime::RestorePlayingError<CampaignBackendError>),
}

impl fmt::Display for Mc2CampaignReplaySaveError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidMode => formatter.write_str(
                "MC2 campaign replay saves require a Playing or quiescent Paused runtime",
            ),
            Self::InvalidSave { message } => {
                write!(formatter, "invalid MC2 replay save: {message}")
            }
            Self::Definition(error) => error.fmt(formatter),
            Self::Runtime(error) => error.fmt(formatter),
            Self::Restore(error) => error.fmt(formatter),
        }
    }
}

impl Error for Mc2CampaignReplaySaveError {}

const MC2_CAMPAIGN_MAP_SAVE_CONTRACT: &str = "carpet-flight-mc2-campaign-map-save/v1";

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2CampaignMapSave {
    save_contract: String,
    state: crate::game_runtime::CampaignSaveState,
    semantic_spell_carry: Option<Mc2SemanticSpellCarry>,
    carry_destination_level: Option<SemanticLevelId>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    secret_flow: Option<crate::game_runtime::secret_flow::SecretFlowState>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    source_context: Option<GlobalSpecialState>,
    receipt_sha256: String,
}

impl Mc2CampaignMapSave {
    fn compute_receipt_sha256(&self) -> String {
        let bytes = serde_json::to_vec(&(
            &self.save_contract,
            &self.state,
            &self.semantic_spell_carry,
            &self.carry_destination_level,
        ))
        .expect("campaign map save payload is serializable");
        let bytes = if let Some(secret_flow) = &self.secret_flow {
            serde_json::to_vec(&(bytes, secret_flow))
                .expect("secret campaign map payload is serializable")
        } else {
            bytes
        };
        let bytes = if let Some(context) = self.source_context {
            serde_json::to_vec(&(bytes, "source-global-context-v1", context))
                .expect("campaign map source context is serializable")
        } else {
            bytes
        };
        hex_digest(Sha256::digest(bytes).into())
    }
}

/// One definition-validated MC2 resource binding, keyed only by the semantic
/// level identity derived from its immutable definition. Owner-cache and
/// backend materialization validation remain retryable work at open time.
#[derive(Clone, Debug)]
struct ResolvedMc2RuntimePackage {
    definition: Arc<GameDefinition>,
    inputs: Mc2CampaignInputs,
    selection: CampaignSelection,
    source_package_sha256: String,
    runtime_capture_sha256: String,
}

/// Presentation inputs retained from the exact validated installed destination.
/// Reading this value never opens a gameplay session or reselects a mission.
#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct Mc2LoadingPresentation {
    pub schema: &'static str,
    pub level_id: SemanticLevelId,
    pub source_selection: CampaignSelection,
    pub cue_id: SemanticPresentationCueId,
    pub package_graph_hash: String,
    pub definition_hash: String,
    #[serde(serialize_with = "serialize_loading_revision")]
    pub definition_revision: u64,
    pub source_package_sha256: String,
    pub runtime_capture_sha256: String,
    pub owner_export_package_sha256: String,
    pub environment: &'static str,
    pub artwork_profile: &'static str,
}

fn serialize_loading_revision<S: serde::Serializer>(
    value: &u64,
    serializer: S,
) -> Result<S::Ok, S::Error> {
    serializer.serialize_str(&value.to_string())
}

fn loading_artwork_profile(selection: CampaignSelection) -> &'static str {
    // sub_46830_main_loop passes the zero-based levelnumber_43w predicate
    // to sub_47FC0_load_screen; ordinary source24 is NOT secret artwork.
    if selection.internal_level > 24 && selection.internal_level < 50 {
        "secret"
    } else {
        "ordinary"
    }
}

/// Immutable installed-package resolver for one closed semantic MC2 flow.
///
/// Callers supply only unordered resource locations. The resolver loads and
/// verifies every definition, derives each key from `bound_level_id`, and
/// rejects mixed, duplicate, or incomplete package sets before a runtime can
/// enter Loading. It never accepts a caller-provided next-level identity.
#[derive(Clone, Debug)]
pub struct Mc2RuntimePackageResolver {
    flow: RuntimeFlowDefinition,
    by_level: BTreeMap<SemanticLevelId, ResolvedMc2RuntimePackage>,
    pending_spell_carries: Arc<Mutex<BTreeMap<u64, Mc2PendingSpellCarry>>>,
    /// Occupied only while this runtime has no attached gameplay authority.
    detached_source_contexts: Arc<Mutex<BTreeMap<u64, GlobalSpecialState>>>,
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2GlobalContextChange {
    before_operation: usize,
    context: GlobalSpecialState,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2SemanticSpellCarry {
    acquired: Vec<SpellKind>,
    selected: Option<SpellKind>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    progression: Vec<Mc2SemanticSpellProgress>,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
struct Mc2SemanticSpellProgress {
    spell: SpellKind,
    persistent_experience: i32,
    runtime_experience: i32,
    unlocked_tier: i8,
    selected_tier: i8,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct Mc2PendingSpellCarry {
    session_generation: u64,
    destination_level: SemanticLevelId,
    carry: Mc2SemanticSpellCarry,
}

impl Mc2RuntimePackageResolver {
    /// The attached campaign is authoritative. Only detached runtimes consult
    /// the retained process context; resolver clones never share live globals.
    pub fn source_global_context(
        &self,
        runtime: &crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
    ) -> Result<GlobalSpecialState, crate::game_runtime::RuntimeTransitionError> {
        if let Some(session) = runtime.session() {
            return Ok(session.backend().campaign.source_global_context());
        }
        let contexts = self.detached_source_contexts.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        Ok(contexts
            .get(&runtime.identity().runtime_id)
            .copied()
            .unwrap_or_default())
    }

    // Retained saves keep their exact closed catalog and receipt identities.
    // Reconstruct that canonical prefix from current package inputs rather
    // than rewriting a save to adopt an installed ordinary or secret suffix.
    fn retained_catalog_definition(
        &self,
        package: &ResolvedMc2RuntimePackage,
        requested: &RuntimeFlowDefinition,
    ) -> crate::game_definition::Result<Option<GameDefinition>> {
        if !self.flow.continues_catalog(requested) {
            return Ok(None);
        }
        let (ordinary_count, secrets) = runtime_catalog::dimensions(requested)?;
        let canonical = runtime_catalog::compose(package.selection, ordinary_count, &secrets)?;
        if &canonical != requested {
            return Ok(None);
        }
        let level = package
            .definition
            .level_definition()
            .expect("campaign has a level")
            .clone();
        Ok(Some(with_level_and_runtime_flow(
            (*package.definition).clone(),
            level,
            canonical,
        )))
    }

    fn exact_package_for_definition(
        &self,
        definition: &GameDefinition,
    ) -> Result<&ResolvedMc2RuntimePackage, crate::game_runtime::RuntimeTransitionError> {
        let level_id = definition
            .runtime_flow()
            .map(RuntimeFlowDefinition::bound_level_id)
            .ok_or_else(
                || crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "resolver-bound definition has no semantic runtime flow".to_owned(),
                },
            )?;
        let package = self.package(level_id).ok_or_else(|| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: format!(
                    "installed package resolver has no binding for {}",
                    level_id.as_str()
                ),
            }
        })?;
        if definition.package_graph_hash() != package.definition.package_graph_hash()
            || definition.definition_hash() != package.definition.definition_hash()
            || definition.revision() != package.definition.revision()
        {
            let retained = self
                .retained_catalog_definition(
                    package,
                    definition.runtime_flow().expect("bound definition flow"),
                )
                .map_err(|error| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: error.to_string(),
                    }
                })?;
            if retained.as_ref().is_some_and(|base| {
                definition.package_graph_hash() == base.package_graph_hash()
                    && definition.definition_hash() == base.definition_hash()
                    && definition.revision() == base.revision()
            }) {
                return Ok(package);
            }
            return Err(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: format!(
                        "definition {} is not the resolver's exact installed binding",
                        level_id.as_str()
                    ),
                },
            );
        }
        Ok(package)
    }

    /// Replace one installed definition only for a resolver-binding negative.
    /// The returned exact binding must be restored before the positive route.
    #[cfg(test)]
    pub(crate) fn replace_exact_definition_for_test(
        &mut self,
        definition: Arc<GameDefinition>,
    ) -> Result<Arc<GameDefinition>, crate::game_runtime::RuntimeTransitionError> {
        let level_id = definition
            .runtime_flow()
            .map(|flow| flow.bound_level_id().clone())
            .ok_or_else(
                || crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "test replacement definition has no semantic runtime flow".to_owned(),
                },
            )?;
        let package = self.by_level.get_mut(&level_id).ok_or_else(|| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: format!(
                    "installed package resolver has no binding for {}",
                    level_id.as_str()
                ),
            }
        })?;
        Ok(std::mem::replace(&mut package.definition, definition))
    }

    /// Load and close one unordered installed package set over its declared
    /// semantic runtime flow.
    ///
    /// # Errors
    ///
    /// Returns a typed definition error when a package is invalid, a derived
    /// level identity is duplicated, flow identities disagree, or any
    /// declared playable level is absent.
    pub fn load(
        inputs: impl IntoIterator<Item = Mc2CampaignInputs>,
    ) -> crate::game_definition::Result<Self> {
        let catalog = default_catalog()?;
        let mut flow: Option<RuntimeFlowDefinition> = None;
        let mut by_level = BTreeMap::new();
        let mut loaded = Vec::new();
        for input in inputs {
            let (definition, selection, source_package_sha256, runtime_capture_sha256) =
                load_mc2_campaign_internal(
                    &input.package_root,
                    input.owner_cache.as_deref(),
                    &catalog,
                )?;
            loaded.push((
                input,
                definition,
                selection,
                source_package_sha256,
                runtime_capture_sha256,
            ));
        }
        let selections = loaded
            .iter()
            .map(|(_, _, selection, _, _)| *selection)
            .collect::<Vec<_>>();
        let (ordinary_count, secret_indices) = runtime_catalog::installed(&selections)?;
        for (input, mut definition, selection, source_package_sha256, runtime_capture_sha256) in
            loaded
        {
            let level = definition
                .level_definition()
                .expect("validated campaign has a level")
                .clone();
            let installed_flow =
                runtime_catalog::compose(selection, ordinary_count, &secret_indices)?;
            definition = with_level_and_runtime_flow(definition, level, installed_flow);
            let definition = Arc::new(definition);
            definition.verify_identity()?;
            let candidate = definition.runtime_flow().cloned().ok_or_else(|| {
                definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    "runtime_package_resolver.flow",
                    "installed campaign definition has no semantic runtime flow",
                )
            })?;
            if let Some(expected) = &flow {
                if candidate.game_id() != expected.game_id()
                    || candidate.entry_level_id() != expected.entry_level_id()
                    || candidate.entries() != expected.entries()
                    || candidate.secret_entries() != expected.secret_entries()
                {
                    return Err(definition_error(
                        DefinitionErrorCode::DependencyFailed,
                        "runtime_package_resolver.flow",
                        "installed campaign definitions do not share one ordered semantic flow",
                    ));
                }
            } else {
                flow = Some(candidate.clone());
            }
            let level_id = candidate.bound_level_id().clone();
            if by_level
                .insert(
                    level_id.clone(),
                    ResolvedMc2RuntimePackage {
                        definition,
                        inputs: input,
                        selection,
                        source_package_sha256,
                        runtime_capture_sha256,
                    },
                )
                .is_some()
            {
                return Err(definition_error(
                    DefinitionErrorCode::DuplicateBinding,
                    level_id.as_str(),
                    "installed campaign package set duplicates a semantic level binding",
                ));
            }
        }
        let observed_flow = flow.ok_or_else(|| {
            definition_error(
                DefinitionErrorCode::InvalidSchema,
                "runtime_package_resolver.packages",
                "installed campaign package set is empty",
            )
        })?;
        for entry in observed_flow.entries() {
            if !by_level.contains_key(entry.level_id()) {
                return Err(definition_error(
                    DefinitionErrorCode::DependencyFailed,
                    entry.level_id().as_str(),
                    "installed campaign package set is missing a declared playable level",
                ));
            }
        }
        for entry in observed_flow.secret_entries() {
            let origin = by_level
                .get(entry.origin_level_id())
                .expect("secret origin belongs to closed ordinary flow");
            let destination = by_level.get(entry.secret_level_id()).ok_or_else(|| {
                definition_error(
                    DefinitionErrorCode::DependencyFailed,
                    entry.secret_level_id().as_str(),
                    "installed campaign package set is missing a declared secret mission",
                )
            })?;
            if super::mc2_secret_flow::entry_for(
                origin.selection,
                destination.selection.internal_level,
                origin
                    .definition
                    .runtime_flow()
                    .expect("validated ordinary flow"),
                destination
                    .definition
                    .runtime_flow()
                    .expect("validated secret flow"),
            )
            .as_ref()
                != Some(entry)
            {
                return Err(definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    entry.secret_level_id().as_str(),
                    "installed secret package disagrees with the source portal association",
                ));
            }
        }
        if by_level.len() != observed_flow.entries().len() + observed_flow.secret_entries().len() {
            return Err(definition_error(
                DefinitionErrorCode::InvalidSchema,
                "runtime_package_resolver.packages",
                "installed campaign package set contains a level outside its closed flow",
            ));
        }
        let flow = by_level
            .get(observed_flow.entry_level_id())
            .and_then(|package| package.definition.runtime_flow())
            .cloned()
            .expect("closed package set contains its validated entry definition");
        Ok(Self {
            flow,
            by_level,
            pending_spell_carries: Arc::new(Mutex::new(BTreeMap::new())),
            detached_source_contexts: Arc::new(Mutex::new(BTreeMap::new())),
        })
    }

    #[must_use]
    pub const fn flow(&self) -> &RuntimeFlowDefinition {
        &self.flow
    }

    /// Owner export and campaign package identities for audio-bank preflight.
    #[must_use]
    pub fn installed_audio_identity(&self, selection: CampaignSelection) -> Option<(&str, &str)> {
        let package = self
            .by_level
            .values()
            .find(|package| package.selection == selection)?;
        let owner = package
            .definition
            .artifacts()
            .iter()
            .find(|artifact| artifact.id == "campaign.owner_export")?;
        Some((
            owner.sha256.as_str(),
            package.source_package_sha256.as_str(),
        ))
    }

    fn package(&self, level_id: &SemanticLevelId) -> Option<&ResolvedMc2RuntimePackage> {
        self.by_level.get(level_id)
    }

    /// Bind the resolver-derived entry package at the runtime's guarded
    /// new-game boundary.
    pub fn new_game(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
    ) -> Result<crate::game_runtime::RuntimeIdentity, crate::game_runtime::RuntimeTransitionError>
    {
        let package = self
            .package(self.flow.entry_level_id())
            .expect("closed installed package set contains its entry level");
        runtime.new_game(guard, Arc::clone(&package.definition))
    }

    /// NewGameDialog reopens the retained frontier; only the map's explicit
    /// reset command clears progress and learned spell carry.
    pub fn show_new_game_map(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
    ) -> Result<crate::game_runtime::RuntimeIdentity, crate::game_runtime::RuntimeTransitionError>
    {
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let identity = runtime.show_new_game_map_resolved(guard, |level_id| {
            self.package(level_id)
                .map(|package| Arc::clone(&package.definition))
                .ok_or_else(
                    || crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "retained campaign frontier is not installed".to_owned(),
                    },
                )
        })?;
        if let Some(carry) = pending.get_mut(&guard.runtime_id) {
            if let Some(selected) = identity
                .campaign_menu
                .as_ref()
                .and_then(|map| map.selected_level_id.as_ref())
            {
                carry.destination_level.clone_from(selected);
            }
            carry.session_generation = runtime
                .campaign_session_generation()
                .expect("map owns its generation");
        }
        Ok(identity)
    }

    /// Observe the current Loading destination without opening or mutating it.
    pub fn loading_presentation(
        &self,
        runtime: &crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
    ) -> Result<Mc2LoadingPresentation, crate::game_runtime::RuntimeTransitionError> {
        use crate::game_runtime::{RuntimeMode, RuntimeTransitionError};
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::Guard)?;
        let identity = runtime.identity();
        if identity.mode != RuntimeMode::Loading {
            return Err(RuntimeTransitionError::InvalidMode {
                expected: RuntimeMode::Loading,
                actual: identity.mode,
            });
        }
        let invalid = |message: &str| RuntimeTransitionError::InvalidRuntimeFlow {
            message: message.to_owned(),
        };
        let pending = identity
            .pending_definition
            .as_ref()
            .ok_or_else(|| invalid("Loading has no pending definition"))?;
        self.definition_presentation(pending, identity.presentation.cue_id)
    }

    /// Observe the exact installed presentation binding after a direct secret
    /// entry. This reads the live session; it does not fabricate a Loading mode.
    pub fn active_entry_presentation(
        &self,
        runtime: &crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
    ) -> Result<Mc2LoadingPresentation, crate::game_runtime::RuntimeTransitionError> {
        use crate::game_runtime::{RuntimeDefinitionIdentity, RuntimeMode, RuntimeTransitionError};
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::Guard)?;
        let identity = runtime.identity();
        if identity.mode != RuntimeMode::Playing {
            return Err(RuntimeTransitionError::InvalidMode {
                expected: RuntimeMode::Playing,
                actual: identity.mode,
            });
        }
        let session =
            runtime
                .session()
                .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "Playing has no active session".to_owned(),
                })?;
        let definition = session.definition();
        self.definition_presentation(
            &RuntimeDefinitionIdentity {
                package_graph_hash: definition.package_graph_hash().to_owned(),
                definition_hash: definition.definition_hash().to_owned(),
                definition_revision: definition.revision(),
                runtime_flow: definition.runtime_flow().cloned(),
            },
            identity.presentation.cue_id,
        )
    }

    fn definition_presentation(
        &self,
        pending: &crate::game_runtime::RuntimeDefinitionIdentity,
        cue_id: crate::game_definition::SemanticPresentationCueId,
    ) -> Result<Mc2LoadingPresentation, crate::game_runtime::RuntimeTransitionError> {
        let invalid =
            |message: &str| crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: message.to_owned(),
            };
        let flow = pending
            .runtime_flow
            .as_ref()
            .ok_or_else(|| invalid("pending definition has no runtime flow"))?;
        let package = self
            .package(flow.bound_level_id())
            .ok_or_else(|| invalid("pending level is not installed"))?;
        if pending.package_graph_hash != package.definition.package_graph_hash()
            || pending.definition_hash != package.definition.definition_hash()
            || pending.definition_revision != package.definition.revision()
            || package.definition.runtime_flow() != Some(flow)
        {
            return Err(invalid(
                "pending definition is not the exact installed loading binding",
            ));
        }
        let environment = match package.selection.map_type_id {
            0 => "day",
            1 => "night",
            2 => "cave",
            _ => {
                return Err(invalid(
                    "installed loading binding has an invalid environment",
                ));
            }
        };
        let owner_export = package
            .definition
            .artifacts()
            .iter()
            .find(|artifact| artifact.id == "campaign.owner_export")
            .ok_or_else(|| invalid("installed loading binding has no owner-export artifact"))?;
        Ok(Mc2LoadingPresentation {
            schema: "mc2-loading-presentation/v1",
            level_id: flow.bound_level_id().clone(),
            source_selection: package.selection,
            cue_id,
            package_graph_hash: pending.package_graph_hash.clone(),
            definition_hash: pending.definition_hash.clone(),
            definition_revision: pending.definition_revision,
            source_package_sha256: package.source_package_sha256.clone(),
            runtime_capture_sha256: package.runtime_capture_sha256.clone(),
            owner_export_package_sha256: owner_export.sha256.clone(),
            environment,
            artwork_profile: loading_artwork_profile(package.selection),
        })
    }

    /// PresentLevelDescription's source segment belongs to the selected map
    /// briefing, not the loading screen or an inferred ordinal in the client.
    #[must_use]
    pub fn campaign_briefing_speech(
        &self,
        runtime: &crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
    ) -> Option<super::objective_speech::SpeechSegment> {
        let identity = runtime.identity();
        let menu = identity.campaign_menu?;
        if menu.phase != crate::game_runtime::CampaignMenuPhase::MissionSelect {
            return None;
        }
        let package = self.package(menu.briefing_level_id.as_ref()?)?;
        super::objective_speech::ordinary_speech_segment(
            u8::try_from(package.selection.internal_level).ok()?,
            0,
        )
    }

    /// Restore the generic Loading origin atomically with resolver carry state.
    pub fn cancel_loading(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
    ) -> Result<crate::game_runtime::RuntimeIdentity, crate::game_runtime::RuntimeTransitionError>
    {
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(crate::game_runtime::RuntimeTransitionError::Guard)?;
        let _pending = self.pending_spell_carries.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let identity = runtime.cancel_loading(guard)?;
        Ok(identity)
    }

    /// Abandon returns to the retained campaign with entry spells/experience.
    /// Only the successful-completion path promotes new jars and runtime XP.
    pub fn close_to_title(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_guard: crate::game_session::SessionGuard,
    ) -> Result<crate::game_runtime::RuntimeIdentity, crate::game_runtime::RuntimeTransitionError>
    {
        use crate::game_runtime::RuntimeTransitionError;
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::Guard)?;
        let session = runtime
            .session()
            .ok_or_else(|| RuntimeTransitionError::InvalidMode {
                expected: crate::game_runtime::RuntimeMode::Playing,
                actual: runtime.identity().mode,
            })?;
        session
            .completion_status(session_guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::SessionGuard)?;
        self.exact_package_for_definition(session.definition())?;
        let carry = session.backend().initial_semantic_spell_carry()?;
        let source_context = session.backend().campaign.source_global_context();
        let destination_level = session
            .definition()
            .runtime_flow()
            .expect("campaign owns a flow")
            .bound_level_id()
            .clone();
        let session_generation = session
            .identity()
            .generation
            .checked_add(1)
            .ok_or(RuntimeTransitionError::GenerationExhausted)?;
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        let identity = runtime.close(guard, session_guard)?;
        contexts.insert(guard.runtime_id, source_context);
        pending.insert(
            guard.runtime_id,
            Mc2PendingSpellCarry {
                session_generation,
                destination_level,
                carry,
            },
        );
        Ok(identity)
    }

    fn unfinished_parent_continuation(
        &self,
        definition: &GameDefinition,
        progress: &crate::game_runtime::secret_flow::SecretFlowState,
    ) -> Result<
        Option<sim_definition::runtime_flow::RuntimeFlowSecretEntry>,
        crate::game_runtime::RuntimeTransitionError,
    > {
        let parent_flow = definition.runtime_flow().ok_or_else(|| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "ordinary parent has no runtime flow".to_owned(),
            }
        })?;
        let source = self.package(parent_flow.bound_level_id()).ok_or_else(|| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "ordinary parent package is not installed".to_owned(),
            }
        })?;
        let Some(association) = super::mc2_secret_flow::association_for_origin(source.selection)
        else {
            return Ok(None);
        };
        let retained = if definition.runtime_flow() != source.definition.runtime_flow() {
            self.retained_catalog_definition(source, parent_flow)
                .map_err(|error| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: error.to_string(),
                    }
                })?
        } else {
            None
        };
        let catalog = default_catalog().map_err(|error| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: error.to_string(),
            }
        })?;
        definition
            .verify_semantic_variant_of(retained.as_ref().unwrap_or(&source.definition), &catalog)
            .map_err(
                |error| crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: error.to_string(),
                },
            )?;
        progress.validate_for_flow(parent_flow)?;
        let Some(destination) = self.by_level.values().find(|package| {
            package.selection.internal_level == association.destination_level_index()
        }) else {
            return Ok(None);
        };
        let destination_flow = destination.definition.runtime_flow().ok_or_else(|| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "secret destination has no runtime flow".to_owned(),
            }
        })?;
        Ok(super::mc2_secret_flow::unfinished_parent_continuation(
            source.selection,
            parent_flow,
            destination_flow,
            progress,
        ))
    }

    /// Open the currently pending resolver-owned package through the ordinary
    /// MC2 gameplay adapter.
    pub fn open_pending(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
    ) -> Result<
        crate::game_runtime::RuntimeIdentity,
        crate::game_runtime::OpenLevelError<CampaignBackendError>,
    > {
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            crate::game_runtime::OpenLevelError::Transition(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "resolver spell-carry state is unavailable".to_owned(),
                },
            )
        })?;
        let carry = pending.get(&guard.runtime_id).cloned();
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            crate::game_runtime::OpenLevelError::Transition(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "source context owner is unavailable".to_owned(),
                },
            )
        })?;
        let source_context = contexts.get(&guard.runtime_id).copied();
        let secret_progress = runtime.secret_flow_state().clone();
        let completed_levels = runtime.completed_levels().to_vec();
        let dynamic_lighting_enabled = runtime
            .identity()
            .player_preferences
            .preferences
            .dynamic_lighting;
        let opened = runtime.open_level_resolved_with_candidate(
            guard,
            &Mc2CampaignAdapter,
            session_id,
            |definition| {
                self.exact_package_for_definition(definition)
                    .map(|package| {
                        package
                            .inputs
                            .clone()
                            .with_dynamic_lighting(dynamic_lighting_enabled)
                    })
            },
            |candidate| {
                let continuation =
                    self.unfinished_parent_continuation(candidate.definition(), &secret_progress)?;
                if let Some(pending) = &carry {
                    let destination = candidate
                        .definition()
                        .runtime_flow()
                        .map(RuntimeFlowDefinition::bound_level_id);
                    if pending.session_generation != candidate.identity().generation
                        || destination != Some(&pending.destination_level)
                    {
                        return Err(
                        crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                            message:
                                "pending spell carry does not bind this exact Loading transition"
                                    .to_owned(),
                        },
                    );
                    }
                    candidate
                        .backend_mut()
                        .apply_semantic_spell_carry(&pending.carry)?;
                }
                if let Some(context) = source_context {
                    candidate
                        .backend_mut()
                        .install_initial_source_context(context)?;
                }
                // Spell-carry installation can rebuild the unpublished
                // simulation. Bind the route only after that replacement.
                candidate
                    .backend_mut()
                    .install_initial_secret_continuation(continuation.as_ref())?;
                let level = candidate
                    .definition()
                    .runtime_flow()
                    .ok_or_else(|| {
                        crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                            message: "selected mission has no runtime flow".to_owned(),
                        }
                    })?
                    .bound_level_id();
                let policy = if completed_levels.contains(level)
                    || secret_progress.completed_secret_levels().contains(level)
                {
                    super::rewards::MissionRewards::Suppressed
                } else {
                    super::rewards::MissionRewards::Enabled
                };
                candidate
                    .backend_mut()
                    .install_initial_mission_rewards(policy)?;
                Ok(())
            },
        );
        if opened.is_ok() && carry.is_some() {
            pending.remove(&guard.runtime_id);
        }
        if opened.is_ok() {
            contexts.remove(&guard.runtime_id);
        }
        opened
    }

    /// Serialize one Playing or quiescent Paused runtime as a definition-bound
    /// semantic command replay plus exact authoritative-state receipts.
    pub fn save_replay(
        &self,
        runtime: &crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
    ) -> Result<Vec<u8>, Mc2CampaignReplaySaveError> {
        let mode = runtime.identity().mode;
        if matches!(
            mode,
            crate::game_runtime::RuntimeMode::Campaign | crate::game_runtime::RuntimeMode::Title
        ) {
            let state = if mode == crate::game_runtime::RuntimeMode::Title {
                // SaveGameDialog on Title writes the retained campaign, not
                // a fabricated gameplay session. Loading it opens the map.
                crate::game_runtime::CampaignSaveState {
                    definition: self
                        .package(self.flow.entry_level_id())
                        .expect("closed installed entry")
                        .definition
                        .as_ref()
                        .clone(),
                    phase: crate::game_runtime::CampaignMenuPhase::MissionSelect,
                    completed_level_id: None,
                    selected_level_id: self
                        .flow
                        .entries()
                        .iter()
                        .find(|entry| !runtime.completed_levels().contains(entry.level_id()))
                        .map(|entry| entry.level_id().clone()),
                    completed_levels: runtime.completed_levels().to_vec(),
                    level_statistics: runtime.completed_level_statistics().to_vec(),
                }
            } else {
                runtime
                    .campaign_save_state()
                    .ok_or(Mc2CampaignReplaySaveError::InvalidMode)?
            };
            self.exact_package_for_definition(&state.definition)
                .map_err(Mc2CampaignReplaySaveError::Runtime)?;
            let pending = self.pending_spell_carries.lock().map_err(|_| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: "resolver spell-carry state is unavailable".to_owned(),
                }
            })?;
            let contexts = self.detached_source_contexts.lock().map_err(|_| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: "source context owner is unavailable".to_owned(),
                }
            })?;
            let mut save = Mc2CampaignMapSave {
                save_contract: MC2_CAMPAIGN_MAP_SAVE_CONTRACT.to_owned(),
                state,
                semantic_spell_carry: pending
                    .get(&runtime.identity().runtime_id)
                    .map(|pending| pending.carry.clone()),
                carry_destination_level: pending
                    .get(&runtime.identity().runtime_id)
                    .map(|pending| pending.destination_level.clone()),
                secret_flow: (!runtime
                    .secret_flow_state()
                    .discovered_secret_levels()
                    .is_empty())
                .then(|| runtime.secret_flow_state().clone()),
                source_context: contexts.get(&runtime.identity().runtime_id).copied(),
                receipt_sha256: String::new(),
            };
            if mode == crate::game_runtime::RuntimeMode::Title
                && save.semantic_spell_carry.is_some()
            {
                save.carry_destination_level = save
                    .state
                    .selected_level_id
                    .clone()
                    .or_else(|| save.state.completed_levels.last().cloned());
            }
            save.receipt_sha256 = save.compute_receipt_sha256();
            let bytes = serde_json::to_vec(&save).map_err(|error| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: error.to_string(),
                }
            })?;
            if bytes.len() > MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES {
                return Err(Mc2CampaignReplaySaveError::InvalidSave {
                    message: "campaign map save exceeds size bound".to_owned(),
                });
            }
            return Ok(bytes);
        }
        if !matches!(
            mode,
            crate::game_runtime::RuntimeMode::Playing | crate::game_runtime::RuntimeMode::Paused
        ) {
            return Err(Mc2CampaignReplaySaveError::InvalidMode);
        }
        let session = runtime
            .session()
            .ok_or(Mc2CampaignReplaySaveError::InvalidMode)?;
        let flow = session.definition().runtime_flow().ok_or_else(|| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: "active definition has no semantic runtime flow".to_owned(),
            }
        })?;
        let package = self.package(flow.bound_level_id()).ok_or_else(|| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "installed resolver has no package for {}",
                    flow.bound_level_id().as_str()
                ),
            }
        })?;
        let catalog = default_catalog().map_err(Mc2CampaignReplaySaveError::Definition)?;
        let retained = if session.definition().runtime_flow() != package.definition.runtime_flow() {
            self.retained_catalog_definition(package, flow)
                .map_err(Mc2CampaignReplaySaveError::Definition)?
        } else {
            None
        };
        session
            .definition()
            .verify_semantic_variant_of(retained.as_ref().unwrap_or(&package.definition), &catalog)
            .map_err(Mc2CampaignReplaySaveError::Definition)?;
        let snapshot = session.backend().snapshot();
        if session.backend().replay_operations.len() > MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "session has {} replay operations, exceeding the {MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS}-operation bound",
                    session.backend().replay_operations.len()
                ),
            });
        }
        let semantic_spell_carry = session
            .backend()
            .initial_semantic_spell_carry()
            .map_err(Mc2CampaignReplaySaveError::Runtime)?;
        let mut save = Mc2CampaignReplaySave::new(
            mode == crate::game_runtime::RuntimeMode::Paused,
            session.definition().as_ref().clone(),
            semantic_spell_carry,
            runtime.completed_levels().to_vec(),
            session.backend().replay_operations.clone(),
            &snapshot,
        );
        save.level_statistics = runtime.completed_level_statistics().to_vec();
        save.secret_flow = (!runtime
            .secret_flow_state()
            .discovered_secret_levels()
            .is_empty())
        .then(|| runtime.secret_flow_state().clone());
        save.retained_campaign = runtime.retained_campaign().cloned();
        let initial_rewards = session
            .backend()
            .package_campaign
            .simulation()
            .mission_rewards();
        if initial_rewards == super::rewards::MissionRewards::Suppressed {
            save.initial_mission_rewards = Some(initial_rewards);
        }
        if session
            .backend()
            .package_campaign
            .simulation()
            .level_exit_sequence()
            .ordinary_exit_route
            == crate::level_exit::OrdinaryExitRoute::UnfinishedSecretContinuation
        {
            save.initial_secret_continuation = Some(
                self.unfinished_parent_continuation(
                    session.definition(),
                    runtime.secret_flow_state(),
                )
                .map_err(Mc2CampaignReplaySaveError::Runtime)?
                .ok_or_else(|| Mc2CampaignReplaySaveError::InvalidSave {
                    message: "initial secret continuation no longer matches campaign progress"
                        .to_owned(),
                })?,
            );
        }
        save.initial_global_context = session.backend().package_campaign.source_global_context();
        save.global_context_changes = session.backend().global_context_changes.clone();
        save.initial_dynamic_lighting = session
            .backend()
            .package_campaign
            .simulation()
            .source_arena()
            .dynamic_lighting_enabled;
        save.dynamic_lighting_changes = session.backend().dynamic_lighting_changes.clone();
        save.receipt_sha256 = save.compute_receipt_sha256();
        let bytes =
            serde_json::to_vec(&save).map_err(|error| Mc2CampaignReplaySaveError::InvalidSave {
                message: format!("cannot serialize replay save: {error}"),
            })?;
        if bytes.len() > MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "save has {} bytes, exceeding the {MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES}-byte bound",
                    bytes.len()
                ),
            });
        }
        Ok(bytes)
    }

    /// Restore one replay save directly from Title into Playing or quiescent
    /// Paused. The candidate is published only when every retained receipt
    /// matches exactly.
    pub fn load_replay(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
    ) -> Result<crate::game_runtime::RuntimeIdentity, Mc2CampaignReplaySaveError> {
        self.load_replay_observed(runtime, guard, session_id, bytes, |_| {})
    }

    /// SLEV-style warm load: verify the saved replay under its own context,
    /// then retain the receiving game's current nonserialized source global.
    pub fn load_replay_with_source_context(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
        context: GlobalSpecialState,
    ) -> Result<crate::game_runtime::RuntimeIdentity, Mc2CampaignReplaySaveError> {
        self.load_replay_observed_with_context(
            runtime,
            guard,
            session_id,
            bytes,
            Some(context),
            |_| {},
        )
    }

    fn load_replay_observed(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
        observe: impl FnMut(&crate::game_session::GameSession<Mc2CampaignBackend>),
    ) -> Result<crate::game_runtime::RuntimeIdentity, Mc2CampaignReplaySaveError> {
        let context = self
            .detached_source_contexts
            .lock()
            .map_err(|_| Mc2CampaignReplaySaveError::InvalidSave {
                message: "source context owner is unavailable".to_owned(),
            })?
            .get(&guard.runtime_id)
            .copied();
        self.load_replay_observed_with_context(runtime, guard, session_id, bytes, context, observe)
    }

    fn load_replay_observed_with_context(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
        warm_context: Option<GlobalSpecialState>,
        observe: impl FnMut(&crate::game_session::GameSession<Mc2CampaignBackend>),
    ) -> Result<crate::game_runtime::RuntimeIdentity, Mc2CampaignReplaySaveError> {
        runtime
            .preflight_title_transition(guard)
            .map_err(Mc2CampaignReplaySaveError::Runtime)?;
        if bytes.len() > MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "save has {} bytes, exceeding the {MAX_MC2_CAMPAIGN_REPLAY_SAVE_BYTES}-byte bound",
                    bytes.len()
                ),
            });
        }
        let envelope: serde_json::Value = serde_json::from_slice(bytes).map_err(|error| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: error.to_string(),
            }
        })?;
        if envelope
            .get("save_contract")
            .and_then(serde_json::Value::as_str)
            == Some(MC2_CAMPAIGN_MAP_SAVE_CONTRACT)
        {
            let save: Mc2CampaignMapSave = serde_json::from_value(envelope).map_err(|error| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: error.to_string(),
                }
            })?;
            if save.receipt_sha256 != save.compute_receipt_sha256() {
                return Err(Mc2CampaignReplaySaveError::InvalidSave {
                    message: "campaign map receipt does not verify".to_owned(),
                });
            }
            self.exact_package_for_definition(&save.state.definition)
                .map_err(Mc2CampaignReplaySaveError::Runtime)?;
            let secret_flow = save.secret_flow.unwrap_or_default();
            crate::game_runtime::GameRuntime::<Mc2CampaignBackend>::validate_secret_restore_fields(
                &save.state.definition,
                &secret_flow,
                None,
                &save.state.completed_levels,
                &save.state.level_statistics,
            )
            .map_err(Mc2CampaignReplaySaveError::Runtime)?;
            let destination = save.carry_destination_level;
            if save.semantic_spell_carry.is_some() != destination.is_some() {
                return Err(Mc2CampaignReplaySaveError::InvalidSave {
                    message: "campaign carry has no retained destination".to_owned(),
                });
            }
            if let Some(destination) = destination.as_ref() {
                let expected_destination = save
                    .state
                    .selected_level_id
                    .as_ref()
                    .or(save.state.completed_level_id.as_ref())
                    .or_else(|| save.state.completed_levels.last());
                if self.package(destination).is_none() || expected_destination != Some(destination)
                {
                    return Err(Mc2CampaignReplaySaveError::InvalidSave {
                        message:
                            "campaign carry destination is not the retained installed selection"
                                .to_owned(),
                    });
                }
            }
            let mut pending = self.pending_spell_carries.lock().map_err(|_| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: "resolver spell-carry state is unavailable".to_owned(),
                }
            })?;
            let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
                Mc2CampaignReplaySaveError::InvalidSave {
                    message: "source context owner is unavailable".to_owned(),
                }
            })?;
            runtime
                .restore_campaign_resolved(
                    guard,
                    save.state,
                    secret_flow,
                    |definition, selected| {
                        self.exact_package_for_definition(definition)?;
                        self.package(selected)
                            .map(|package| Arc::clone(&package.definition))
                            .ok_or_else(|| {
                                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                                    message: "saved campaign selection is not installed".to_owned(),
                                }
                            })
                    },
                )
                .map_err(Mc2CampaignReplaySaveError::Runtime)?;
            if let Some(carry) = save.semantic_spell_carry {
                pending.insert(
                    guard.runtime_id,
                    Mc2PendingSpellCarry {
                        session_generation: runtime
                            .campaign_session_generation()
                            .expect("restored Campaign owns generation"),
                        destination_level: destination.expect("validated carry destination"),
                        carry,
                    },
                );
            } else {
                pending.remove(&guard.runtime_id);
            }
            if let Some(context) = warm_context.or(save.source_context) {
                contexts.insert(guard.runtime_id, context);
            } else {
                contexts.remove(&guard.runtime_id);
            }
            return Ok(runtime.identity());
        }
        let save: Mc2CampaignReplaySave = serde_json::from_slice(bytes).map_err(|error| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: format!("save JSON is invalid: {error}"),
            }
        })?;
        if !save.verify() {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: "save contract or receipt digest does not verify".to_owned(),
            });
        }
        if save.operations.len() > MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "save has {} replay operations, exceeding the {MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS}-operation bound",
                    save.operations.len()
                ),
            });
        }
        if save.global_context_changes.len() > MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS + 1
            || save
                .global_context_changes
                .iter()
                .any(|change| change.before_operation > save.operations.len())
            || save
                .global_context_changes
                .windows(2)
                .any(|pair| pair[0].before_operation >= pair[1].before_operation)
        {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: "source context changes have an invalid replay boundary".to_owned(),
            });
        }
        if save.dynamic_lighting_changes.len() > MAX_MC2_CAMPAIGN_REPLAY_OPERATIONS + 1
            || save
                .dynamic_lighting_changes
                .iter()
                .any(|change| change.before_operation > save.operations.len())
            || save
                .dynamic_lighting_changes
                .windows(2)
                .any(|pair| pair[0].before_operation > pair[1].before_operation)
        {
            return Err(Mc2CampaignReplaySaveError::InvalidSave {
                message: "dynamic-light changes have an invalid replay boundary".to_owned(),
            });
        }
        save.definition
            .verify_identity()
            .map_err(Mc2CampaignReplaySaveError::Definition)?;
        let flow = save.definition.runtime_flow().ok_or_else(|| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: "saved definition has no semantic runtime flow".to_owned(),
            }
        })?;
        let package = self.package(flow.bound_level_id()).ok_or_else(|| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: format!(
                    "installed resolver has no package for {}",
                    flow.bound_level_id().as_str()
                ),
            }
        })?;
        let catalog = default_catalog().map_err(Mc2CampaignReplaySaveError::Definition)?;
        let retained = if save.definition.runtime_flow() != package.definition.runtime_flow() {
            self.retained_catalog_definition(package, flow)
                .map_err(Mc2CampaignReplaySaveError::Definition)?
        } else {
            None
        };
        save.definition
            .verify_semantic_variant_of(retained.as_ref().unwrap_or(&package.definition), &catalog)
            .map_err(Mc2CampaignReplaySaveError::Definition)?;
        let secret_flow = save.secret_flow.unwrap_or_default();
        let retained_campaign = save.retained_campaign;
        crate::game_runtime::GameRuntime::<Mc2CampaignBackend>::validate_secret_restore_fields(
            &save.definition,
            &secret_flow,
            retained_campaign.as_ref(),
            save.completed_levels.as_deref().unwrap_or_default(),
            &save.level_statistics,
        )
        .map_err(Mc2CampaignReplaySaveError::Runtime)?;
        if let Some(parent) = retained_campaign.as_ref() {
            self.exact_package_for_definition(&parent.definition)
                .map_err(Mc2CampaignReplaySaveError::Runtime)?;
        }
        let initial_rewards = save.initial_mission_rewards.unwrap_or_default();
        if let Some(recorded) = save.initial_mission_rewards {
            let level = flow.bound_level_id();
            let completed = save
                .completed_levels
                .as_deref()
                .unwrap_or_default()
                .contains(level)
                || secret_flow.completed_secret_levels().contains(level);
            let inherited = secret_flow.return_frame().is_some_and(|frame| {
                frame.secret_level_id() == level
                    && frame.parent_campaign().selected_level_id.as_ref()
                        == Some(frame.origin_level_id())
                    && frame
                        .parent_campaign()
                        .completed_levels
                        .contains(frame.origin_level_id())
                    && secret_flow.discovered_secret_levels().contains(level)
                    && !secret_flow.completed_secret_levels().contains(level)
            });
            if recorded != super::rewards::MissionRewards::Suppressed || !(completed || inherited) {
                return Err(Mc2CampaignReplaySaveError::InvalidSave {
                    message: "saved mission reward policy does not match completed portal context"
                        .to_owned(),
                });
            }
        }
        let initial_secret_continuation = save.initial_secret_continuation;
        if let Some(recorded) = &initial_secret_continuation {
            let expected = self
                .unfinished_parent_continuation(&save.definition, &secret_flow)
                .map_err(Mc2CampaignReplaySaveError::Runtime)?;
            if expected.as_ref() != Some(recorded) {
                return Err(Mc2CampaignReplaySaveError::InvalidSave {
                    message: "saved secret continuation does not match the retained campaign"
                        .to_owned(),
                });
            }
        }
        let definition = Arc::new(save.definition);
        let semantic_spell_carry = save.semantic_spell_carry;
        let initial_global_context = save.initial_global_context;
        let mut global_context_changes = save.global_context_changes.into_iter().peekable();
        let initial_dynamic_lighting = save.initial_dynamic_lighting;
        let mut dynamic_lighting_changes = save.dynamic_lighting_changes.into_iter().peekable();
        let completed_levels = save.completed_levels.unwrap_or_default();
        let level_statistics = save.level_statistics;
        let operations = save.operations;
        let expected_tick = save.expected_tick;
        let expected_state_hash = save.expected_state_hash;
        let expected_terrain_hash = save.expected_terrain_hash;
        let expected_effect_head = save.expected_effect_head;
        let expected_effect_journal_sha256 = save.expected_effect_journal_sha256;
        let paused = save.paused;
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            Mc2CampaignReplaySaveError::InvalidSave {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        runtime
            .restore_playing_resolved(
                guard,
                definition,
                &Mc2CampaignAdapter,
                session_id,
                operations,
                paused,
                completed_levels,
                level_statistics,
                |_| {
                    Ok(package
                        .inputs
                        .clone()
                        .with_dynamic_lighting(initial_dynamic_lighting))
                },
                move |candidate| {
                    candidate
                        .backend_mut()
                        .apply_semantic_spell_carry(&semantic_spell_carry)?;
                    candidate
                        .backend_mut()
                        .install_initial_source_context(initial_global_context)?;
                    candidate
                        .backend_mut()
                        .install_initial_secret_continuation(
                            initial_secret_continuation.as_ref(),
                        )?;
                    candidate
                        .backend_mut()
                        .install_initial_mission_rewards(initial_rewards)
                },
                move |candidate, operation_index| {
                    while dynamic_lighting_changes
                        .peek()
                        .is_some_and(|change| change.before_operation == operation_index)
                    {
                        let change = dynamic_lighting_changes
                            .next()
                            .expect("matched replay lighting boundary");
                        candidate
                            .backend_mut()
                            .set_dynamic_lighting_enabled(change.enabled);
                    }
                    if global_context_changes
                        .peek()
                        .is_some_and(|change| change.before_operation == operation_index)
                    {
                        let change = global_context_changes
                            .next()
                            .expect("matched replay context boundary");
                        candidate
                            .backend_mut()
                            .apply_source_context_change(change.context);
                    }
                    Ok(())
                },
                move |candidate| {
                    let actual = candidate.backend().snapshot();
                    if actual.tick != expected_tick
                        || actual.state_hash != expected_state_hash
                        || actual.terrain_hash != expected_terrain_hash
                        || actual.effect_head != expected_effect_head
                        || actual.effect_journal_sha256 != expected_effect_journal_sha256
                    {
                        return Err(crate::game_runtime::RuntimeTransitionError::InvalidReplay {
                            message: "replayed campaign state does not match the saved receipts"
                                .to_owned(),
                        });
                    }
                    // SLEV retains the receiver's nonserialized globals only
                    // after the saved receipts verify. Apply them to the
                    // private candidate before publishing either Playing or
                    // Paused; the public mutable session gate remains closed
                    // while paused.
                    if let Some(context) = warm_context {
                        candidate.backend_mut().apply_source_context_change(context);
                    }
                    Ok(())
                },
                |candidate, enabled, show_foreign_text| {
                    candidate
                        .backend_mut()
                        .set_objective_presentation_preferences(enabled, show_foreign_text)
                },
                observe,
            )
            .map_err(Mc2CampaignReplaySaveError::Restore)?;
        runtime
            .restore_secret_flow_state(secret_flow, retained_campaign)
            .map_err(Mc2CampaignReplaySaveError::Runtime)?;
        pending.remove(&guard.runtime_id);
        contexts.remove(&guard.runtime_id);
        Ok(runtime.identity())
    }

    /// Test-route history is returned only after the authoritative loader has
    /// verified every final receipt and atomically published the candidate.
    #[cfg(test)]
    pub(crate) fn load_replay_observing_guardians_for_test(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
    ) -> Result<
        (
            crate::game_runtime::RuntimeIdentity,
            tests::VerifiedGuardianReplayHistoryForTest,
        ),
        Mc2CampaignReplaySaveError,
    > {
        let mut observations = tests::GuardianReplayObservationsForTest::default();
        let identity =
            self.load_replay_observed(runtime, guard, session_id, bytes, |candidate| {
                observations.observe(candidate)
            })?;
        let history = tests::VerifiedGuardianReplayHistoryForTest {
            frontier: runtime
                .session()
                .expect("verified replay publishes a session")
                .backend()
                .snapshot(),
            observations,
        };
        Ok((identity, history))
    }

    /// Retain actual Bee source receipts during the same normal replay execution.
    /// Historical observations escape only after every saved receipt verifies.
    #[cfg(test)]
    pub(crate) fn load_replay_observing_level_two_bees_for_test(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_id: u64,
        bytes: &[u8],
    ) -> Result<
        (
            crate::game_runtime::RuntimeIdentity,
            tests::VerifiedLevelTwoBeeReplayHistoryForTest,
        ),
        Mc2CampaignReplaySaveError,
    > {
        let mut observations = tests::LevelTwoBeeReplayObservationsForTest::default();
        let identity =
            self.load_replay_observed(runtime, guard, session_id, bytes, |candidate| {
                observations.observe(candidate)
            })?;
        Ok((
            identity,
            tests::VerifiedLevelTwoBeeReplayHistoryForTest {
                frontier: runtime
                    .session()
                    .expect("verified replay publishes a session")
                    .backend()
                    .snapshot(),
                observations,
            },
        ))
    }

    /// Reseal a save with one deliberately wrong expected state for the
    /// replay-verification negative. Gameplay commands and definitions remain
    /// untouched, so only a loader that actually replays can reject it.
    #[cfg(test)]
    pub(crate) fn corrupt_save_expected_state_for_test(bytes: &[u8]) -> Vec<u8> {
        let mut save: Mc2CampaignReplaySave = serde_json::from_slice(bytes).unwrap();
        save.expected_state_hash ^= 1;
        save.receipt_sha256 = save.compute_receipt_sha256();
        serde_json::to_vec(&save).unwrap()
    }

    /// Construct receipt-valid progress negatives and an old-schema save for
    /// focused loader checks, never for a retained route capture.
    #[cfg(test)]
    pub(crate) fn save_with_progress_for_test(
        bytes: &[u8],
        completed_levels: Option<Vec<SemanticLevelId>>,
    ) -> Vec<u8> {
        let mut save: Mc2CampaignReplaySave = serde_json::from_slice(bytes).unwrap();
        save.save_contract = if completed_levels.is_some() {
            MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT
        } else {
            LEGACY_MC2_CAMPAIGN_REPLAY_SAVE_CONTRACT
        }
        .to_owned();
        save.completed_levels = completed_levels;
        save.receipt_sha256 = save.compute_receipt_sha256();
        serde_json::to_vec(&save).unwrap()
    }

    /// Consume an authoritative secret entry or secret completion before the
    /// ordinary completion edge. Package resolution and candidate construction
    /// precede publication, so an unavailable secret leaves the parent live.
    pub fn advance_secret_if_ready(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_guard: crate::game_session::SessionGuard,
    ) -> Result<
        Option<crate::game_runtime::SecretTransitionReceipt>,
        crate::game_runtime::RuntimeTransitionError,
    > {
        use crate::game_runtime::{RuntimeTransitionError, secret_flow::SecretMissionOutcome};
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::Guard)?;
        let Some(session) = runtime.session() else {
            return Ok(None);
        };
        let status = session
            .completion_status(session_guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::SessionGuard)?
            .value;
        let source = self.exact_package_for_definition(session.definition())?;
        if runtime.secret_flow_state().return_frame().is_some()
            && session
                .backend()
                .campaign
                .simulation()
                .secret_banishment_result()
        {
            return self.abandon_secret_if_active(runtime, guard, session_guard);
        }
        if session.backend().campaign.simulation().secret_entry_ready() {
            let association = super::mc2_secret_flow::association_for_origin(source.selection)
                .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "secret trigger has no source campaign association".to_owned(),
                })?;
            let destination = self
                .by_level
                .values()
                .find(|package| {
                    package.selection.internal_level == association.destination_level_index()
                })
                .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "source secret destination package is not installed".to_owned(),
                })?;
            let source_flow = session.definition().runtime_flow().ok_or_else(|| {
                RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "secret source has no runtime flow".to_owned(),
                }
            })?;
            let destination_flow = destination.definition.runtime_flow().ok_or_else(|| {
                RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "secret destination has no runtime flow".to_owned(),
                }
            })?;
            let entry = super::mc2_secret_flow::entry_for(
                source.selection,
                association.destination_level_index(),
                source_flow,
                destination_flow,
            )
            .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                message: "installed secret definition does not match the source association"
                    .to_owned(),
            })?;
            if session
                .backend()
                .campaign
                .simulation()
                .level_exit_sequence()
                .ordinary_exit_route
                == crate::level_exit::OrdinaryExitRoute::UnfinishedSecretContinuation
                && self.unfinished_parent_continuation(
                    session.definition(),
                    runtime.secret_flow_state(),
                )? != Some(entry.clone())
            {
                return Err(RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "secret continuation no longer matches the retained campaign"
                        .to_owned(),
                });
            }
            let secret_id = entry.secret_level_id().clone();
            let carry = session.backend().transition_spell_carry()?;
            let context = session.backend().campaign.source_global_context();
            let rewards = session.backend().campaign.simulation().mission_rewards();
            let receipt =
                runtime.enter_secret_resolved(guard, session_guard, |source_session| {
                    let generation = source_session
                        .identity()
                        .generation
                        .checked_add(1)
                        .and_then(std::num::NonZeroU64::new)
                        .ok_or(RuntimeTransitionError::GenerationExhausted)?;
                    let mut candidate = crate::game_session::GameSession::open_with_generation(
                        &Mc2CampaignAdapter,
                        Arc::clone(&destination.definition),
                        source_session.identity().session_id,
                        generation,
                        destination.inputs.clone().with_dynamic_lighting(
                            source_session.backend().dynamic_lighting_enabled(),
                        ),
                    )
                    .map_err(|error| {
                        RuntimeTransitionError::InvalidNextDefinition {
                            message: error.to_string(),
                        }
                    })?;
                    candidate.backend_mut().apply_semantic_spell_carry(&carry)?;
                    candidate
                        .backend_mut()
                        .install_initial_source_context(context)?;
                    candidate
                        .backend_mut()
                        .install_initial_mission_rewards(rewards)?;
                    Ok((secret_id, candidate))
                })?;
            return Ok(Some(receipt));
        }
        if runtime.secret_flow_state().return_frame().is_none()
            || !matches!(status, GameCompletionStatus::Completed { .. })
        {
            return Ok(None);
        }
        let carry = session.backend().transition_spell_carry()?;
        let context = session.backend().campaign.source_global_context();
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        let receipt = runtime.return_from_secret_resolved(
            guard,
            session_guard,
            SecretMissionOutcome::Completed,
            |parent| {
                self.exact_package_for_definition(&parent.definition)?;
                super::mc2_secret_flow::activate_parent_after_secret_return(
                    source.selection,
                    parent,
                )?;
                parent
                    .selected_level_id
                    .as_ref()
                    .and_then(|id| self.package(id))
                    .map(|package| Arc::clone(&package.definition))
                    .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "retained secret origin is not installed".to_owned(),
                    })
            },
        )?;
        let destination_level = receipt
            .after
            .campaign_menu
            .as_ref()
            .and_then(|menu| menu.selected_level_id.clone())
            .expect("validated secret parent retains its selected origin");
        pending.insert(
            guard.runtime_id,
            Mc2PendingSpellCarry {
                session_generation: runtime
                    .campaign_session_generation()
                    .expect("secret return owns map lifetime"),
                destination_level,
                carry,
            },
        );
        contexts.insert(guard.runtime_id, context);
        Ok(Some(receipt))
    }

    /// Return an abandoned MC2 secret mission to its retained campaign.
    /// Abandonment keeps the entry spell carry and never promotes mission XP.
    pub fn abandon_secret_if_active(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_guard: crate::game_session::SessionGuard,
    ) -> Result<
        Option<crate::game_runtime::SecretTransitionReceipt>,
        crate::game_runtime::RuntimeTransitionError,
    > {
        use crate::game_runtime::{RuntimeTransitionError, secret_flow::SecretMissionOutcome};

        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::Guard)?;
        let session = runtime
            .session()
            .ok_or_else(|| RuntimeTransitionError::InvalidMode {
                expected: crate::game_runtime::RuntimeMode::Playing,
                actual: runtime.identity().mode,
            })?;
        session
            .completion_status(session_guard)
            .map_err(Box::new)
            .map_err(RuntimeTransitionError::SessionGuard)?;
        let source = self.exact_package_for_definition(session.definition())?;
        if runtime.secret_flow_state().return_frame().is_none() {
            return Ok(None);
        }

        let carry = session.backend().initial_semantic_spell_carry()?;
        let context = session.backend().campaign.source_global_context();
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            RuntimeTransitionError::InvalidRuntimeFlow {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        let receipt = runtime.return_from_secret_resolved(
            guard,
            session_guard,
            SecretMissionOutcome::Abandoned,
            |parent| {
                self.exact_package_for_definition(&parent.definition)?;
                super::mc2_secret_flow::activate_parent_after_secret_return(
                    source.selection,
                    parent,
                )?;
                parent
                    .selected_level_id
                    .as_ref()
                    .and_then(|id| self.package(id))
                    .map(|package| Arc::clone(&package.definition))
                    .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "retained secret origin is not installed".to_owned(),
                    })
            },
        )?;
        let destination_level = receipt
            .after
            .campaign_menu
            .as_ref()
            .and_then(|menu| menu.selected_level_id.clone())
            .expect("validated secret parent retains its selected origin");
        pending.insert(
            guard.runtime_id,
            Mc2PendingSpellCarry {
                session_generation: runtime
                    .campaign_session_generation()
                    .expect("abandoned secret return owns map lifetime"),
                destination_level,
                carry,
            },
        );
        contexts.insert(guard.runtime_id, context);
        Ok(Some(receipt))
    }

    /// Resolve the active semantic completion edge and accept it without a
    /// caller-provided level identity, definition, or package path.
    pub fn accept_transition(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        session_guard: crate::game_session::SessionGuard,
    ) -> Result<
        crate::game_runtime::CompletionTransitionReceipt,
        crate::game_runtime::RuntimeTransitionError,
    > {
        // Reject stale outer identities before consulting resolver-owned state.
        // A successful completion leaves a pending carry for the same runtime,
        // so that carry must not mask a duplicate's generation mismatch.
        runtime
            .validate_guard(guard)
            .map_err(Box::new)
            .map_err(crate::game_runtime::RuntimeTransitionError::Guard)?;
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        if pending.contains_key(&guard.runtime_id) {
            return Err(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "resolver already owns a pending spell carry for this runtime"
                        .to_owned(),
                },
            );
        }
        let mut contexts = self.detached_source_contexts.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "source context owner is unavailable".to_owned(),
            }
        })?;
        let (receipt, (carry, source_context)) = runtime.accept_transition_resolved_with_source(
            guard,
            session_guard,
            |source_definition, destination| {
                self.exact_package_for_definition(source_definition)?;
                match destination {
                    RuntimeFlowDestination::Level { level_id } => self
                        .package(level_id)
                        .map(|package| {
                            crate::game_runtime::ResolvedCompletionTarget::Level(Arc::clone(
                                &package.definition,
                            ))
                        })
                        .ok_or_else(|| {
                            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                                message: format!(
                                    "installed package resolver has no binding for {}",
                                    level_id.as_str()
                                ),
                            }
                        }),
                    RuntimeFlowDestination::Title { .. } => {
                        Ok(crate::game_runtime::ResolvedCompletionTarget::Title)
                    }
                }
            },
            |session| {
                session
                    .backend()
                    .transition_spell_carry()
                    .map(|carry| (carry, session.backend().campaign.source_global_context()))
            },
        )?;
        contexts.insert(guard.runtime_id, source_context);
        let destination_level = match &receipt.completion_destination {
            RuntimeFlowDestination::Level { level_id } => level_id.clone(),
            RuntimeFlowDestination::Title { .. } => receipt.completed_level_id.clone(),
        };
        let replaced = pending.insert(
            guard.runtime_id,
            Mc2PendingSpellCarry {
                session_generation: receipt.source_session.generation + 1,
                destination_level,
                carry,
            },
        );
        debug_assert!(replaced.is_none());
        Ok(receipt)
    }

    /// Apply a guarded campaign map action and resolve semantic selections
    /// through the same immutable installed package set used for loading.
    pub fn campaign_menu_command(
        &self,
        runtime: &mut crate::game_runtime::GameRuntime<Mc2CampaignBackend>,
        guard: crate::game_runtime::RuntimeGuard,
        command: crate::game_runtime::CampaignMenuCommand,
    ) -> Result<crate::game_runtime::RuntimeIdentity, crate::game_runtime::RuntimeTransitionError>
    {
        let mut pending = self.pending_spell_carries.lock().map_err(|_| {
            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                message: "resolver spell-carry state is unavailable".to_owned(),
            }
        })?;
        let reset = matches!(
            command,
            crate::game_runtime::CampaignMenuCommand::ResetCampaign
        );
        let identity = runtime.campaign_menu_command_resolved(guard, command, |level_id| {
            self.package(level_id)
                .map(|package| Arc::clone(&package.definition))
                .ok_or_else(
                    || crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "selected mission is not installed".to_owned(),
                    },
                )
        })?;
        if reset {
            pending.remove(&guard.runtime_id);
        } else if let Some(carry) = pending.get_mut(&guard.runtime_id) {
            let selected = identity
                .campaign_menu
                .as_ref()
                .and_then(|menu| menu.selected_level_id.as_ref())
                .or_else(|| {
                    identity
                        .pending_definition
                        .as_ref()
                        .and_then(|definition| definition.runtime_flow.as_ref())
                        .map(RuntimeFlowDefinition::bound_level_id)
                });
            if let Some(selected) = selected {
                carry.destination_level.clone_from(selected);
            }
        }
        Ok(identity)
    }
}

/// Definition-bound campaign backend. The wrapped [`CampaignSession`] owns
/// live gameplay state, ordering, RNG, journals, reset, and replay.
#[derive(Debug)]
pub struct Mc2CampaignBackend {
    campaign: CampaignSession,
    package_campaign: CampaignSession,
    flight_binding: DefinitionFlightBinding,
    fireball_binding: Option<DefinitionFireballBinding>,
    fireball_projectile_asset: Option<GameAssetReference>,
    fireball_launch_sound_choices: BTreeMap<String, u16>,
    goat_policy_binding: Option<DefinitionGoatPolicyBinding>,
    package_base: GameDefinition,
    package_graph_hash: String,
    artifact_graph_hash: String,
    replay_operations: Vec<crate::game_runtime::ReplayOperation<GameCommand>>,
    global_context_changes: Vec<Mc2GlobalContextChange>,
    dynamic_lighting_changes: Vec<Mc2DynamicLightingChange>,
}

impl Mc2CampaignBackend {
    #[must_use]
    pub fn dynamic_lighting_enabled(&self) -> bool {
        self.campaign
            .simulation()
            .source_arena()
            .dynamic_lighting_enabled
    }

    /// Retain changes at the boundary where source constructors will observe them.
    pub fn set_dynamic_lighting_enabled(&mut self, enabled: bool) {
        if self.dynamic_lighting_enabled() == enabled {
            return;
        }
        self.campaign.set_dynamic_lighting_enabled(enabled);
        let change = Mc2DynamicLightingChange {
            before_operation: self.replay_operations.len(),
            enabled,
        };
        self.dynamic_lighting_changes.push(change);
    }

    #[must_use]
    pub fn dynamic_lighting_change_count(&self) -> usize {
        self.dynamic_lighting_changes.len()
    }

    /// Restore only the policy and history changed by a rejected caller.
    pub fn restore_dynamic_lighting_after_rejection(&mut self, enabled: bool, change_count: usize) {
        self.campaign.set_dynamic_lighting_enabled(enabled);
        self.dynamic_lighting_changes.truncate(change_count);
    }

    fn install_initial_mission_rewards(
        &mut self,
        policy: super::rewards::MissionRewards,
    ) -> Result<(), crate::game_runtime::RuntimeTransitionError> {
        for campaign in [&mut self.campaign, &mut self.package_campaign] {
            campaign
                .simulation_mut()
                .install_initial_mission_rewards(policy)
                .map_err(|message| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow { message }
                })?;
        }
        Ok(())
    }

    fn install_initial_secret_continuation(
        &mut self,
        continuation: Option<&sim_definition::runtime_flow::RuntimeFlowSecretEntry>,
    ) -> Result<(), crate::game_runtime::RuntimeTransitionError> {
        let route = if continuation.is_some() {
            crate::level_exit::OrdinaryExitRoute::UnfinishedSecretContinuation
        } else {
            crate::level_exit::OrdinaryExitRoute::CampaignMap
        };
        for campaign in [&mut self.campaign, &mut self.package_campaign] {
            campaign
                .simulation_mut()
                .install_initial_ordinary_exit_route(route)
                .map_err(|message| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow { message }
                })?;
        }
        Ok(())
    }

    fn install_initial_source_context(
        &mut self,
        context: GlobalSpecialState,
    ) -> Result<(), crate::game_runtime::RuntimeTransitionError> {
        self.campaign
            .install_initial_source_global_context(context)
            .map_err(
                |error| crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: error.to_string(),
                },
            )?;
        self.package_campaign
            .install_initial_source_global_context(context)
            .map_err(
                |error| crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: error.to_string(),
                },
            )?;
        Ok(())
    }

    fn apply_source_context_change(&mut self, context: GlobalSpecialState) {
        if self.campaign.source_global_context() == context {
            return;
        }
        self.campaign.apply_warm_source_global_context(context);
        let change = Mc2GlobalContextChange {
            before_operation: self.replay_operations.len(),
            context,
        };
        if self
            .global_context_changes
            .last()
            .is_some_and(|previous| previous.before_operation == change.before_operation)
        {
            *self
                .global_context_changes
                .last_mut()
                .expect("matched context boundary") = change;
        } else {
            self.global_context_changes.push(change);
        }
    }

    pub fn speech_enabled(&self) -> bool {
        self.campaign.speech_enabled()
    }

    pub fn set_speech_enabled(&mut self, enabled: bool) {
        self.set_objective_presentation_preferences(
            enabled,
            self.campaign.show_foreign_objective_text(),
        );
    }

    pub fn show_foreign_objective_text(&self) -> bool {
        self.campaign.show_foreign_objective_text()
    }

    pub fn set_objective_presentation_preferences(
        &mut self,
        enabled: bool,
        show_foreign_text: bool,
    ) {
        if self.campaign.speech_enabled() != enabled
            || self.campaign.show_foreign_objective_text() != show_foreign_text
        {
            self.campaign.set_speech_enabled(enabled);
            self.campaign
                .set_show_foreign_objective_text(show_foreign_text);
            self.replay_operations
                .push(crate::game_runtime::ReplayOperation::SpeechPreference {
                    enabled,
                    show_foreign_text,
                });
        }
    }

    pub fn replay_operation_count(&self) -> usize {
        self.replay_operations.len()
    }

    pub fn restore_speech_preference_after_rejection(
        &mut self,
        enabled: bool,
        show_foreign_text: bool,
        operation_count: usize,
    ) {
        self.campaign.set_speech_enabled(enabled);
        self.campaign
            .set_show_foreign_objective_text(show_foreign_text);
        self.replay_operations.truncate(operation_count);
    }

    /// Borrow the one live campaign authority for compatibility presentation
    /// adapters.  This never exposes mutation or creates another session; the
    /// neutral [`GameSession`] remains the sole lifecycle and step owner.
    #[doc(hidden)]
    #[must_use]
    pub fn campaign_presentation_source(&self) -> &CampaignSession {
        &self.campaign
    }
}

impl GameAdapter for Mc2CampaignAdapter {
    type Backend = Mc2CampaignBackend;
    type OpenInput = Mc2CampaignInputs;
    type Error = CampaignBackendError;

    fn open_backend(
        &self,
        definition: &GameDefinition,
        input: Self::OpenInput,
    ) -> Result<Self::Backend, Self::Error> {
        let catalog = default_catalog().map_err(CampaignBackendError::Definition)?;
        let flight_binding = DefinitionFlightBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let fireball_binding = DefinitionFireballBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let goat_policy_binding = DefinitionGoatPolicyBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let fireball_projectile_asset = fireball_projectile_asset_reference(definition)?;
        let mut package_base =
            load_mc2_campaign_inputs(&input, &catalog).map_err(CampaignBackendError::Definition)?;
        let selection = CampaignDescriptor::declared_selection(&input.package_root)
            .map_err(|error| CampaignBackendError::Open(CampaignOpenError::Preflight(error)))?;
        if let Some(flow) = definition.runtime_flow() {
            let (ordinary_count, secret_indices) =
                runtime_catalog::dimensions(flow).map_err(CampaignBackendError::Definition)?;
            let canonical = runtime_catalog::compose(selection, ordinary_count, &secret_indices)
                .map_err(CampaignBackendError::Definition)?;
            if flow != &canonical {
                return Err(CampaignBackendError::Definition(definition_error(
                    DefinitionErrorCode::InvalidSchema,
                    "mc2_campaign.runtime_flow",
                    "definition does not match its canonical source-selected catalog",
                )));
            }
            let level = package_base
                .level_definition()
                .expect("campaign has a level")
                .clone();
            package_base = with_level_and_runtime_flow(package_base, level, canonical);
        }
        definition
            .verify_semantic_variant_of(&package_base, &catalog)
            .map_err(CampaignBackendError::Definition)?;
        let mut package_campaign = match &input.owner_cache {
            Some(owner_cache) => CampaignSession::open_with_owner_cache_and_dynamic_lighting(
                &input.package_root,
                owner_cache,
                selection,
                input.dynamic_lighting_enabled,
            ),
            None => CampaignSession::open_with_dynamic_lighting(
                &input.package_root,
                selection,
                input.dynamic_lighting_enabled,
            ),
        }
        .map_err(CampaignBackendError::Open)?;
        let fireball_launch_sound_choices = fireball_launch_sound_choices(&package_base, &input)?;
        let fireball_launch_sound_id =
            selected_fireball_launch_sound(definition, &fireball_launch_sound_choices)?;
        require_catalog_defaults(
            definition,
            &catalog,
            fireball_binding.is_some(),
            goat_policy_binding.is_some(),
            consumes_fireball_projectile_asset(definition),
            fireball_launch_sound_id.is_some(),
        )?;
        // The neutral session is the campaign route: bind the authored
        // campaign entry stage before the first generation is exposed, like
        // the retained `mc_native_campaign_*` opens. The pristine
        // generation-0 state rebases, so reset restores the entry-staged
        // baseline instead of the raw package selector.
        if selection == CampaignSelection::LEVEL2 {
            package_campaign
                .simulation_mut()
                .select_level2_campaign_entry_stage();
        }
        let mut campaign = package_campaign.clone();
        campaign
            .apply_semantic_level_variant(
                definition
                    .level_definition()
                    .expect("campaign semantic variant retains its level definition"),
            )
            .map_err(|error| {
                CampaignBackendError::Open(CampaignOpenError::Materialization(error))
            })?;
        if let Some(binding) = goat_policy_binding {
            campaign.apply_enemy_goat_policy(binding);
        }
        if let Some(binding) = fireball_binding {
            campaign
                .apply_local_player_fireball_mana_cost(binding.mana_cost())
                .map_err(|error| {
                    CampaignBackendError::Open(CampaignOpenError::Materialization(error))
                })?;
        }
        if let Some(source_sound_id) = fireball_launch_sound_id {
            campaign.apply_fireball_launch_sound(source_sound_id);
        }
        Ok(Mc2CampaignBackend {
            campaign,
            package_campaign,
            flight_binding,
            fireball_binding,
            fireball_projectile_asset,
            fireball_launch_sound_choices,
            goat_policy_binding,
            package_graph_hash: definition.package_graph_hash().to_owned(),
            artifact_graph_hash: definition.artifact_graph_hash().to_owned(),
            replay_operations: Vec::new(),
            global_context_changes: Vec::new(),
            dynamic_lighting_changes: Vec::new(),
            package_base,
        })
    }
}

/// Admit only semantic deviations with a package-present runtime consumer.
/// Every other catalog value must remain at its package default so this route
/// cannot silently bind a definition whose authored value gameplay ignores.
fn require_catalog_defaults(
    definition: &GameDefinition,
    catalog: &SemanticCatalog,
    consumes_fireball_cost: bool,
    consumes_goat_policy: bool,
    consumes_fireball_projectile_asset: bool,
    consumes_fireball_launch_sound: bool,
) -> Result<(), CampaignBackendError> {
    for descriptor in catalog.descriptors() {
        if DefinitionFlightBinding::consumes(&descriptor.id)
            || (consumes_fireball_cost && DefinitionFireballBinding::consumes(&descriptor.id))
            || (consumes_goat_policy && DefinitionGoatPolicyBinding::consumes(&descriptor.id))
            || (consumes_fireball_projectile_asset
                && descriptor.id.as_str() == "presentation.spell.fireball.projectile_asset")
            || (consumes_fireball_launch_sound
                && descriptor.id.as_str() == sim_definition::FIREBALL_LAUNCH_SOUND_ASSET_SLOT_ID)
        {
            continue;
        }
        if definition.value(&descriptor.id) != Some(&descriptor.default_value) {
            return Err(CampaignBackendError::UnappliedSemanticValue {
                id: descriptor.id.clone(),
            });
        }
    }
    Ok(())
}

fn consumes_fireball_projectile_asset(definition: &GameDefinition) -> bool {
    let Ok(id) = SemanticId::parse("presentation.spell.fireball.projectile_asset") else {
        return false;
    };
    definition
        .required_capabilities()
        .iter()
        .any(|requirement| {
            requirement.id.as_str() == "engine.presentation.indexed_asset"
                && requirement.exact_version == 1
        })
        && definition.presentation_asset(&id).is_ok()
}

fn fireball_projectile_asset_reference(
    definition: &GameDefinition,
) -> Result<Option<GameAssetReference>, CampaignBackendError> {
    if !consumes_fireball_projectile_asset(definition) {
        return Ok(None);
    }
    let id = SemanticId::parse("presentation.spell.fireball.projectile_asset")
        .map_err(CampaignBackendError::Definition)?;
    let asset = definition
        .presentation_asset(&id)
        .map_err(CampaignBackendError::Definition)?;
    Ok(Some(GameAssetReference {
        id: id.as_str().to_owned(),
        content_address: asset.content_address,
    }))
}

fn fireball_launch_sound_choices(
    package_base: &GameDefinition,
    input: &Mc2CampaignInputs,
) -> Result<BTreeMap<String, u16>, CampaignBackendError> {
    let Some(owner_cache) = &input.owner_cache else {
        return Ok(BTreeMap::new());
    };
    if !package_base
        .required_capabilities()
        .iter()
        .any(|requirement| {
            requirement.id.as_str() == "engine.audio.semantic_asset"
                && requirement.exact_version == 1
        })
    {
        return Ok(BTreeMap::new());
    }
    let artifacts = crate::native_world::qualified_fireball_sound_artifacts(owner_cache)
        .map_err(|error| CampaignBackendError::Open(CampaignOpenError::Materialization(error)))?;
    Ok(artifacts
        .into_iter()
        .map(|artifact| {
            (
                format!("sha256:{}", artifact.content_hash),
                artifact.source_sound_id,
            )
        })
        .collect())
}

fn selected_fireball_launch_sound(
    definition: &GameDefinition,
    choices: &BTreeMap<String, u16>,
) -> Result<Option<u16>, CampaignBackendError> {
    if choices.is_empty() {
        return Ok(None);
    }
    let id = SemanticId::parse(sim_definition::FIREBALL_LAUNCH_SOUND_ASSET_SLOT_ID)
        .map_err(CampaignBackendError::Definition)?;
    let asset = definition
        .audio_asset(&id)
        .map_err(CampaignBackendError::Definition)?;
    choices
        .get(&asset.content_address)
        .copied()
        .map(Some)
        .ok_or_else(|| {
            CampaignBackendError::Definition(definition_error(
                DefinitionErrorCode::TypeMismatch,
                id.as_str(),
                "Fireball launch sound is not one of the qualified owner-cache choices",
            ))
        })
}

fn source_objective_input_admitted(
    simulation: &crate::native_world::Mc2Simulation,
    held: bool,
) -> bool {
    let runtime = simulation.runtime();
    let slot = usize::from(runtime.local_player_slot);
    let action = (slot < usize::from(runtime.player_count))
        .then(|| runtime.player_inputs.get(slot).map(|input| input.opcode))
        .flatten();
    held && super::source_menus::admits_keyboard_input(
        simulation.level2_player_menu_state(),
        action,
    )
}

impl GameSessionBackend for Mc2CampaignBackend {
    type Command = GameCommand;
    type Snapshot = CampaignSnapshot;
    type Error = CampaignBackendError;

    fn tick(&self) -> u64 {
        self.campaign.tick()
    }

    fn flight_assistance_menu_open(&self) -> bool {
        super::source_menus::suppresses_flight_assistance(
            self.campaign.simulation().level2_player_menu_state(),
        )
    }

    fn completion_status(&self) -> GameCompletionStatus {
        let exit = self.campaign.simulation().level_exit_sequence();
        if !exit.complete {
            GameCompletionStatus::InProgress
        } else if exit.result_code == 10 {
            GameCompletionStatus::Completed {
                completion: GameCompletion {
                    state_hash: self.campaign.state_hash(),
                    statistics: Some(self.campaign.simulation().completion_statistics()),
                },
            }
        } else {
            GameCompletionStatus::Invalid {
                message: "completed MC2 exit carrier has a non-success result".to_owned(),
            }
        }
    }

    fn snapshot(&self) -> Self::Snapshot {
        let flight = &self.campaign.simulation.state;
        let compatibility = self.campaign.simulation();
        let shared_spells = compatibility.shared_spells();
        let player_entity = shared_spells.player_entity();
        let level = compatibility
            .semantic_level_definition()
            .expect("campaign backend retains its bound semantic level definition");
        let local_objective = compatibility
            .runtime()
            .objectives
            .first()
            .expect("campaign runtime retains its local objective carrier");
        let total_count = u32::try_from(level.objectives().len())
            .expect("validated level objective count fits u32");
        let completed_count = u32::try_from(
            local_objective
                .stage_selectors
                .iter()
                .take(level.objectives().len())
                .filter(|selector| **selector == 2)
                .count(),
        )
        .expect("validated level objective count fits u32");
        let all_objectives_satisfied = local_objective.is_level_end != 0;
        let current_objective = (!all_objectives_satisfied)
            .then(|| {
                level
                    .objectives()
                    .get(usize::from(local_objective.text_selector))
            })
            .flatten()
            .map(|objective| {
                SemanticId::parse(objective.id().as_str())
                    .expect("validated level objective ID is a semantic ID")
            });
        let presentation_entities = self
            .fireball_projectile_asset
            .as_ref()
            .map(|asset| {
                let kind = SemanticId::parse("spell.fireball.projectile")
                    .expect("compiled semantic Fireball projectile ID");
                self.campaign
                    .simulation()
                    .economy()
                    .fireball_projectiles()
                    .iter()
                    .filter(|projectile| projectile.active && !projectile.drawing_disabled)
                    .map(|projectile| PresentationEntity {
                        actor: self
                            .actor(u64::from(projectile.source_entity_index))
                            .expect("opaque actor projection is total"),
                        kind: kind.clone(),
                        pose: PresentationPose {
                            x: projectile.position.x,
                            y: projectile.position.y,
                            z: projectile.position.z,
                            yaw: projectile.yaw,
                            pitch: projectile.pitch,
                        },
                        logical_height: FIREBALL_LOGICAL_HEIGHT,
                        asset: asset.clone(),
                    })
                    .collect()
            })
            .unwrap_or_default();
        CampaignSnapshot {
            tick: flight.tick,
            source_menu_admission: self.campaign.simulation().source_menu_admission(),
            return_to_title_requested: self.campaign.simulation().ordinary_banishment_result(),
            effect_head: self.campaign.effect_cursor().next_sequence,
            state_hash: self.campaign.state_hash(),
            terrain_hash: self.campaign.terrain_hash(),
            effect_journal_sha256: hex_digest(
                self.campaign
                    .simulation
                    .effect_journal()
                    .receipt()
                    .as_bytes(),
            ),
            player_pose: PlayerPose {
                x: flight.position.x,
                y: flight.position.y,
                z: flight.position.z,
                yaw: flight.yaw,
                display_pitch: flight.display_pitch,
                effective_pitch: flight.effective_pitch,
                roll: flight.roll_accumulator,
            },
            source_camera_pose: compatibility.source_camera_pose(),
            player_motion: PlayerMotion {
                target_speed: flight.target_speed,
                actual_speed: flight.actual_speed,
                strafe_speed: flight.strafe_speed,
            },
            player_vitals: PlayerVitals {
                life: player_entity.life,
                max_life: player_entity.max_life,
                mana: shared_spells.player_mana(),
                max_mana: player_entity.max_mana,
            },
            source_scoreboard: source_scoreboard::observe(
                compatibility,
                &source_scoreboard::source_names(),
            )
            .unwrap_or_else(|error| sim_session::SourceScoreboard {
                players: Vec::new(),
                projection_error: Some(error.to_string()),
            }),
            player_spells: spells::observe(
                shared_spells,
                |holder| self.spell_holder_actor(holder),
                |holder| {
                    let simulation = self.campaign.simulation();
                    let owner = holder.source_spell_parent_entity_index();
                    spells::emission_availability(
                        holder,
                        simulation.source_arena().entities().get(usize::from(owner)),
                        simulation
                            .economy()
                            .castle_for_owner(owner)
                            .map(|castle| castle.mana),
                    )
                },
            ),
            player_immobilized_ticks: u16::from(flight.immobilize_counter.cast_unsigned()),
            source_camera_fov: {
                let exit = self.campaign.simulation().level_exit_sequence();
                if exit.active || exit.complete {
                    exit.camera_fov
                } else {
                    128
                }
            },
            objective_progress: ObjectiveProgress {
                current_objective,
                completed_count,
                total_count,
                all_objectives_satisfied,
            },
            objective_textbox_ticks: compatibility.runtime().objective_textbox_ticks,
            exit_sequence_active: compatibility.level_exit_sequence().active,
            presentation_entities,
        }
    }

    fn events_after(&self, cursor: u64, limit: usize) -> Result<EventPage, Self::Error> {
        let head = self.campaign.effect_cursor().next_sequence;
        let requested = EffectCursor {
            generation: self.campaign.generation(),
            next_sequence: cursor,
        };
        let page = match self.campaign.effects_after(requested, limit.max(1)) {
            Ok(page) => page,
            Err(EffectPageError::FutureCursor { requested, .. }) => {
                return Err(CampaignBackendError::CursorBeyondHead { head, requested });
            }
            Err(EffectPageError::ExpiredCursor {
                first_available,
                requested,
            }) => {
                return Err(CampaignBackendError::CursorExpired {
                    first_available,
                    requested,
                });
            }
            Err(
                EffectPageError::StaleGeneration { .. } | EffectPageError::OutputTooSmall { .. },
            ) => {
                return Err(CampaignBackendError::JournalDesync);
            }
        };
        let records: &[EffectRecord] = if limit == 0 { &[] } else { &page.records };
        let events = records
            .iter()
            .map(|record| self.game_event(record))
            .collect::<Result<Vec<_>, _>>()?;
        let next_cursor = events.last().map_or(cursor, |event| event.sequence);
        Ok(EventPage {
            requested_cursor: cursor,
            next_cursor,
            event_head: head,
            has_more: next_cursor < head,
            events,
            compatibility: None,
        })
    }

    fn audio_for_event(&self, event_sequence: u64) -> Result<GameAudioCommand, Self::Error> {
        Err(CampaignBackendError::NoAudioSidecar { event_sequence })
    }

    fn step(&mut self, command: Self::Command) -> Result<(), Self::Error> {
        let mut player_command = self.campaign_player_command(&command)?;
        let mut candidate = self.campaign.clone();
        let show_objective =
            source_objective_input_admitted(candidate.simulation(), command.show_objective);
        candidate
            .simulation_mut()
            .apply_objective_input(show_objective);
        let menu_admitted = command.abandon_action.is_some_and(|action| {
            candidate
                .simulation_mut()
                .prepare_source_menu_action(action, &mut player_command)
        });
        candidate
            .simulation_mut()
            .advance_elapsed_centiseconds(command.elapsed_centiseconds);
        let _evidence = candidate.step_with_tuning(
            player_command,
            CAMPAIGN_SPEED_INDEX,
            self.flight_binding.tuning(),
        );
        if let Some(message) = candidate.events().iter().find_map(|event| match event {
            Mc2DispatchEvent::Error { message, .. } => Some(message.clone()),
            _ => None,
        }) {
            return Err(CampaignBackendError::StepRejected { message });
        }
        candidate
            .simulation_mut()
            .finish_source_menu_action(command.abandon_action, menu_admitted);
        self.campaign = candidate;
        self.replay_operations
            .push(crate::game_runtime::ReplayOperation::Step { command });
        Ok(())
    }

    fn paused_frame(&mut self) -> Result<(), Self::Error> {
        self.paused_frame_timed(0, false)
    }

    fn enter_pause(&mut self) {
        self.campaign.simulation_mut().clear_objective_textbox();
        self.replay_operations
            .push(crate::game_runtime::ReplayOperation::Pause);
    }

    fn paused_frame_timed(
        &mut self,
        elapsed_centiseconds: u32,
        show_objective: bool,
    ) -> Result<(), Self::Error> {
        let mut candidate = self.campaign.clone();
        candidate
            .simulation_mut()
            .advance_elapsed_centiseconds(elapsed_centiseconds);
        let admitted_objective =
            source_objective_input_admitted(candidate.simulation(), show_objective);
        candidate
            .simulation_mut()
            .apply_objective_input(admitted_objective);
        candidate.paused_frame();
        self.campaign = candidate;
        self.replay_operations
            .push(crate::game_runtime::ReplayOperation::PausedFrame {
                elapsed_centiseconds,
                show_objective,
            });
        Ok(())
    }

    fn reset_for_definition(&mut self, definition: &GameDefinition) -> Result<(), Self::Error> {
        if definition.package_graph_hash() != self.package_graph_hash
            || definition.artifact_graph_hash() != self.artifact_graph_hash
        {
            return Err(CampaignBackendError::PackageSubstitution);
        }
        let catalog = default_catalog().map_err(CampaignBackendError::Definition)?;
        let flight_binding = DefinitionFlightBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let fireball_binding = DefinitionFireballBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let goat_policy_binding = DefinitionGoatPolicyBinding::from_definition(definition)
            .map_err(CampaignBackendError::Definition)?;
        let fireball_projectile_asset = fireball_projectile_asset_reference(definition)?;
        definition
            .verify_semantic_variant_of(&self.package_base, &catalog)
            .map_err(CampaignBackendError::Definition)?;
        require_catalog_defaults(
            definition,
            &catalog,
            fireball_binding.is_some(),
            goat_policy_binding.is_some(),
            consumes_fireball_projectile_asset(definition),
            !self.fireball_launch_sound_choices.is_empty(),
        )?;
        let fireball_launch_sound_id =
            selected_fireball_launch_sound(definition, &self.fireball_launch_sound_choices)?;
        let next_generation = self.campaign.generation().wrapping_add(1);
        let source_context = self.campaign.source_global_context();
        let dynamic_lighting_enabled = self.dynamic_lighting_enabled();
        let mut campaign = self.package_campaign.clone();
        campaign
            .apply_semantic_level_variant(
                definition
                    .level_definition()
                    .expect("campaign semantic variant retains its level definition"),
            )
            .map_err(|error| {
                CampaignBackendError::Open(CampaignOpenError::Materialization(error))
            })?;
        if let Some(binding) = goat_policy_binding {
            campaign.apply_enemy_goat_policy(binding);
        }
        if let Some(binding) = fireball_binding {
            campaign
                .apply_local_player_fireball_mana_cost(binding.mana_cost())
                .map_err(|error| {
                    CampaignBackendError::Open(CampaignOpenError::Materialization(error))
                })?;
        }
        if let Some(source_sound_id) = fireball_launch_sound_id {
            campaign.apply_fireball_launch_sound(source_sound_id);
        }
        campaign.set_runtime_generation(next_generation);
        campaign
            .install_initial_source_global_context(source_context)
            .map_err(|error| {
                CampaignBackendError::Open(CampaignOpenError::Materialization(error))
            })?;
        self.package_campaign
            .install_initial_source_global_context(source_context)
            .map_err(|error| {
                CampaignBackendError::Open(CampaignOpenError::Materialization(error))
            })?;
        self.campaign = campaign;
        self.flight_binding = flight_binding;
        self.fireball_binding = fireball_binding;
        self.fireball_projectile_asset = fireball_projectile_asset;
        self.goat_policy_binding = goat_policy_binding;
        self.replay_operations.clear();
        self.global_context_changes.clear();
        self.dynamic_lighting_changes.clear();
        // Reset restores the constructor baseline. The persistent source-global
        // option then takes effect at the new replay's operation-zero boundary.
        self.set_dynamic_lighting_enabled(dynamic_lighting_enabled);
        Ok(())
    }
}

impl Mc2CampaignBackend {
    fn semantic_spell_carry(
        &self,
    ) -> Result<Mc2SemanticSpellCarry, crate::game_runtime::RuntimeTransitionError> {
        Self::semantic_spell_carry_from_campaign(&self.campaign)
    }

    fn transition_spell_carry(
        &self,
    ) -> Result<Mc2SemanticSpellCarry, crate::game_runtime::RuntimeTransitionError> {
        let mut carry = self.semantic_spell_carry()?;
        // Victory calls sub_6DB50(1, 0): bank the earned total, capped at
        // the last source threshold. New player construction clears the
        // mission XP buffer and sub_5CF40 resets selected subspells, not
        // SpellLevels or the learned family flags.
        for progress in &mut carry.progression {
            let family = mc2_spell_family(progress.spell).expect("exported semantic family");
            if carry.acquired.contains(&progress.spell) {
                progress.persistent_experience =
                    self.campaign.simulation().bank_carried_spell_experience(
                        family,
                        progress.persistent_experience,
                        progress.runtime_experience,
                    );
            }
            progress.runtime_experience = 0;
            progress.selected_tier = 0;
        }
        Ok(carry)
    }

    fn initial_semantic_spell_carry(
        &self,
    ) -> Result<Mc2SemanticSpellCarry, crate::game_runtime::RuntimeTransitionError> {
        // The loader installs this carrier before replaying the first command.
        // Selection and acquisitions made by those commands belong only to the
        // live campaign. Saving them here changes the replay's reset baseline.
        Self::semantic_spell_carry_from_campaign(&self.package_campaign)
    }

    fn semantic_spell_carry_from_campaign(
        campaign: &CampaignSession,
    ) -> Result<Mc2SemanticSpellCarry, crate::game_runtime::RuntimeTransitionError> {
        let shared = campaign.simulation().shared_spells();
        let player = shared.local_player();
        let mut acquired = Vec::new();
        let mut progression = Vec::new();
        for (family, holder_index) in player.enabled_spell_holders.iter().copied().enumerate() {
            let index = family;
            if holder_index == 0
                && player.spell_enabled_flags[index] == 0
                && player.acquired_spell_flags[index] == 0
            {
                continue;
            }
            let family = u8::try_from(family).expect("player spell family index fits u8");
            let kind = mc2_spell_kind_for_family(family).ok_or_else(|| {
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: format!(
                        "local acquired holder family {family} has no closed semantic spell kind"
                    ),
                }
            })?;
            if holder_index != 0 && spells::acquired_holder(shared, family).is_none() {
                return Err(
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: format!(
                            "local acquired semantic spell {} has an invalid holder relation",
                            kind.as_str()
                        ),
                    },
                );
            }
            acquired.push(kind);
        }
        for family in 0..player.enabled_spell_holders.len() {
            if player.persistent_spell_experience[family] == 0
                && player.runtime_spell_experience[family] == 0
                && player.spell_unlocked_levels[family] == 0
                && player.family_selected_tiers[family] == 0
            {
                continue;
            }
            let spell = mc2_spell_kind_for_family(family as u8).ok_or_else(|| {
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: format!("spell progression family {family} has no semantic binding"),
                }
            })?;
            progression.push(Mc2SemanticSpellProgress {
                spell,
                persistent_experience: player.persistent_spell_experience[family],
                runtime_experience: player.runtime_spell_experience[family],
                unlocked_tier: player.spell_unlocked_levels[family],
                selected_tier: player.family_selected_tiers[family],
            });
        }
        let selected = SOURCE_SPELL_INDEX_MAP
            .get(usize::from(player.selected_spell_ui_index))
            .filter(|family| spells::acquired_holder(shared, **family).is_some())
            .and_then(|family| mc2_spell_kind_for_family(*family))
            .filter(|kind| acquired.contains(kind));
        Ok(Mc2SemanticSpellCarry {
            acquired,
            selected,
            progression,
        })
    }

    fn apply_semantic_spell_carry(
        &mut self,
        carry: &Mc2SemanticSpellCarry,
    ) -> Result<(), crate::game_runtime::RuntimeTransitionError> {
        // Replay saves retain the semantic entry spell state, while a
        // freshly opened bound package may already contain that exact state.
        // Treat an equivalent installation as observationally inert: the
        // materializer seals a new reset baseline, which is correct for real
        // cross-level additions but would otherwise change an unchanged
        // package's canonical state receipt before replay begins.
        let current = self.semantic_spell_carry()?;
        if current.acquired == carry.acquired
            && current.selected == carry.selected
            && (carry.progression.is_empty() || current.progression == carry.progression)
        {
            return Ok(());
        }
        let mut families = carry
            .acquired
            .iter()
            .map(|kind| {
                mc2_spell_family(*kind).ok_or_else(|| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: format!(
                            "carried semantic spell {} has no closed MC2 family",
                            kind.as_str()
                        ),
                    }
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        // sub_5CF40 allocates in family-number order, independent of the
        // serialized semantic vector's ordering. Preserve replay slot/RNG identity.
        families.sort_unstable();
        if families.windows(2).any(|pair| pair[0] == pair[1]) {
            return Err(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "carried spell families are duplicated".to_owned(),
                },
            );
        }
        let selected_family = carry
            .selected
            .map(|kind| {
                mc2_spell_family(kind).ok_or_else(|| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: format!(
                            "carried selected spell {} has no closed MC2 family",
                            kind.as_str()
                        ),
                    }
                })
            })
            .transpose()?;
        let apply = |campaign: &mut CampaignSession| {
            let progression = carry
                .progression
                .iter()
                .map(|entry| {
                    Ok(crate::native_world::CarriedSpellProgress {
                        family: mc2_spell_family(entry.spell).ok_or_else(|| {
                            crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                                message: "carried progression has no MC2 spell family".to_owned(),
                            }
                        })?,
                        persistent_experience: entry.persistent_experience,
                        runtime_experience: entry.runtime_experience,
                        unlocked_tier: entry.unlocked_tier,
                        selected_tier: entry.selected_tier,
                    })
                })
                .collect::<Result<Vec<_>, crate::game_runtime::RuntimeTransitionError>>()?;
            // InitialiseSpells admits learned families before any map-start
            // allocation. Rebuild that unpublished entry rather than keeping
            // the destination's direct-entry StartingSpells or their RNG use.
            let selected = campaign
                .rebuild_for_spell_carry(&families, selected_family)
                .and_then(|selected| {
                    campaign
                        .simulation_mut()
                        .apply_carried_spell_progression(&progression)?;
                    Ok(selected)
                })
                .map_err(|error| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: format!("cannot apply semantic spell carry: {error}"),
                    }
                })?;
            Ok::<_, crate::game_runtime::RuntimeTransitionError>(selected)
        };
        let mut campaign = self.campaign.clone();
        let mut package_campaign = self.package_campaign.clone();
        let selected_family = apply(&mut campaign)?;
        apply(&mut package_campaign)?;
        if let Some(binding) = self.goat_policy_binding {
            campaign.apply_enemy_goat_policy(binding);
        }
        if let Some(binding) = self.fireball_binding {
            campaign
                .apply_local_player_fireball_mana_cost(binding.mana_cost())
                .map_err(|error| {
                    crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                        message: format!("cannot reapply carried Fireball binding: {error}"),
                    }
                })?;
        }
        campaign.apply_fireball_launch_sound(self.campaign.simulation().fireball_launch_sound_id);
        let installed = Self::semantic_spell_carry_from_campaign(&campaign)?;
        if installed.acquired.len() != carry.acquired.len()
            || !carry
                .acquired
                .iter()
                .all(|kind| installed.acquired.contains(kind))
            || installed.selected != selected_family.and_then(mc2_spell_kind_for_family)
            || carry.progression.iter().any(|entry| {
                let family =
                    usize::from(mc2_spell_family(entry.spell).expect("validated carry family"));
                let player = campaign.simulation().shared_spells().local_player();
                player.persistent_spell_experience[family] != entry.persistent_experience
                    || player.runtime_spell_experience[family] != entry.runtime_experience
                    || player.spell_unlocked_levels[family] != entry.unlocked_tier
                    || player.family_selected_tiers[family] != entry.selected_tier
            })
        {
            return Err(
                crate::game_runtime::RuntimeTransitionError::InvalidRuntimeFlow {
                    message: "semantic spell carry did not survive candidate installation"
                        .to_owned(),
                },
            );
        }
        self.campaign = campaign;
        self.package_campaign = package_campaign;
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn install_semantic_spell_carry_for_test(
        &mut self,
        acquired: Vec<SpellKind>,
        selected: Option<SpellKind>,
    ) -> Result<(), crate::game_runtime::RuntimeTransitionError> {
        self.apply_semantic_spell_carry(&Mc2SemanticSpellCarry {
            acquired,
            selected,
            progression: Vec::new(),
        })
    }

    #[cfg(test)]
    pub(crate) fn semantic_spell_state_for_test(
        &self,
    ) -> Result<(Vec<SpellKind>, Option<SpellKind>), crate::game_runtime::RuntimeTransitionError>
    {
        let carry = self.semantic_spell_carry()?;
        Ok((carry.acquired, carry.selected))
    }

    /// Read-only view of this backend's one live campaign authority for the
    /// retained `mc_native_campaign_*` presentation projections. No mutable
    /// counterpart exists: the neutral session lifecycle stays the only
    /// campaign gameplay writer.
    #[doc(hidden)]
    #[must_use]
    pub fn compatibility_campaign(&self) -> &CampaignSession {
        &self.campaign
    }

    #[cfg(test)]
    pub(crate) fn compatibility_campaign_mut_for_test(&mut self) -> &mut CampaignSession {
        &mut self.campaign
    }

    fn opaque_runtime_handle(&self, namespace: &[u8], source_value: u64) -> u64 {
        let mut digest = Sha256::new();
        digest.update(b"mc2-campaign-runtime-handle/v1\0");
        digest.update(self.campaign.definition().package_sha256.as_bytes());
        digest.update([0]);
        digest.update(namespace);
        digest.update([0]);
        digest.update(source_value.to_le_bytes());
        let bytes: [u8; 8] = digest.finalize()[..8]
            .try_into()
            .expect("SHA-256 prefix is eight bytes");
        u64::from_le_bytes(bytes).max(1)
    }

    fn actor(&self, source_value: u64) -> Option<RuntimeActorId> {
        Some(RuntimeActorId(
            self.opaque_runtime_handle(b"actor", source_value),
        ))
    }

    fn spell_holder_actor(
        &self,
        holder: &crate::native_world::EntitySnapshot,
    ) -> Option<RuntimeActorId> {
        use crate::campaign::source_arena::SourceEntityView;
        use crate::native_world::Level2DynamicArenaKind;

        if holder.model == 12
            && self
                .campaign
                .simulation()
                .current_beyond_sight_holder()
                .is_none_or(|current| current.index != holder.index)
        {
            return None;
        }
        let arena = self.campaign.simulation().source_arena();
        let handle = arena.handle(holder.index)?;
        match arena.resolve(handle)? {
            SourceEntityView::Imported(_) => {}
            SourceEntityView::Dynamic(
                Level2DynamicArenaKind::SpellPickup | Level2DynamicArenaKind::SpellReplacement,
            ) => {}
            SourceEntityView::Dynamic(_) => return None,
        }
        let source = arena.entities().get(usize::from(holder.index))?;
        if !source.active
            || source.class != 15
            || source.model != holder.model
            || source.source_spell_parent_entity_index()
                != holder.source_spell_parent_entity_index()
        {
            return None;
        }
        let source_value = (u64::from(handle.generation) << 16) | u64::from(holder.index);
        Some(RuntimeActorId(
            self.opaque_runtime_handle(b"spell-holder", source_value),
        ))
    }

    fn validate_spell_holder_actor(
        &self,
        spell_id: &SemanticId,
        expected: Option<RuntimeActorId>,
    ) -> Result<(), CampaignBackendError> {
        let Some(expected) = expected else {
            return Ok(());
        };
        let holder = semantic_spell_kind(spell_id)
            .and_then(mc2_spell_family)
            .and_then(|family| {
                spells::acquired_holder(self.campaign.simulation().shared_spells(), family)
            });
        if holder.is_none_or(|holder| self.spell_holder_actor(holder) != Some(expected)) {
            return Err(CampaignBackendError::StepRejected {
                message: format!(
                    "spell {} holder binding is stale or unavailable",
                    spell_id.as_str()
                ),
            });
        }
        Ok(())
    }

    fn participant(&self, source_value: u64) -> Option<RuntimeParticipantId> {
        Some(RuntimeParticipantId(
            self.opaque_runtime_handle(b"participant", source_value),
        ))
    }

    fn game_event(&self, record: &EffectRecord) -> Result<GameEvent, CampaignBackendError> {
        let (event_id, actor, participant) = match &record.effect {
            CampaignEffect::Dispatch(event) => match event {
                Mc2DispatchEvent::Error { .. } => ("session.dispatch_fault", None, None),
                _ => {
                    let (_, _, _, _, source_slot) = event.campaign_projection();
                    (
                        "actor.behavior_dispatched",
                        self.actor(source_slot.into()),
                        None,
                    )
                }
            },
            CampaignEffect::SharedSpell(event) => match *event {
                Level2SharedSpellEvent::SpellCollected {
                    source_slot,
                    player_entity_index,
                    ..
                } => (
                    "spell.collected",
                    self.actor(source_slot.into()),
                    self.participant(player_entity_index.into()),
                ),
                Level2SharedSpellEvent::SpellAcquired {
                    source_slot,
                    player_entity_index,
                    ..
                } => (
                    "spell.acquired",
                    self.actor(source_slot.into()),
                    self.participant(player_entity_index.into()),
                ),
                Level2SharedSpellEvent::ShieldDamageApplied {
                    target_entity_index,
                    ..
                } => (
                    "combat.actor_damaged",
                    self.actor(target_entity_index.into()),
                    None,
                ),
                Level2SharedSpellEvent::ExperienceScrollCollected {
                    source_slot,
                    player_entity_index,
                } => (
                    "progression.experience_collected",
                    self.actor(source_slot.into()),
                    self.participant(player_entity_index.into()),
                ),
                Level2SharedSpellEvent::AbilityImproved { .. } => ("ability.improved", None, None),
            },
            CampaignEffect::Flight(event) => match *event {
                FlightEvent::PrepareSound {
                    entity_index,
                    player_index,
                    ..
                } => (
                    "audio.sound_prepared",
                    (entity_index != 0)
                        .then(|| self.actor(entity_index.into()))
                        .flatten(),
                    (player_index >= 0)
                        .then(|| self.participant(player_index.cast_unsigned().into()))
                        .flatten(),
                ),
                FlightEvent::EndLoop {
                    entity_index,
                    player_index,
                    ..
                } => (
                    "audio.loop_ended",
                    (entity_index != 0)
                        .then(|| self.actor(entity_index.into()))
                        .flatten(),
                    (player_index >= 0)
                        .then(|| self.participant(player_index.cast_unsigned().into()))
                        .flatten(),
                ),
                FlightEvent::UpdateMusic { .. } => ("audio.music_updated", None, None),
                FlightEvent::RequestSpellActivation {
                    holder_entity_index,
                    ..
                } => (
                    "spell.activation_requested",
                    self.actor(holder_entity_index.into()),
                    None,
                ),
                FlightEvent::ShowHelpHint { .. } => ("ui.help_hint_requested", None, None),
            },
            CampaignEffect::SceneChange { .. } => ("session.scene_changed", None, None),
            CampaignEffect::ObjectivePresentation { .. } => ("ui.objective_presented", None, None),
        };
        Ok(GameEvent {
            sequence: record.sequence.wrapping_add(1),
            // The journal retains exact effect content, not per-effect state
            // fingerprints; the authoritative state hash lives on the
            // snapshot, so this field stays at its unbound zero value.
            state_hash: 0,
            event_id: SemanticId::parse(event_id).map_err(CampaignBackendError::Definition)?,
            actor,
            participant,
            asset: None,
        })
    }
}

impl Mc2CampaignBackend {
    fn campaign_player_command(
        &self,
        command: &GameCommand,
    ) -> Result<PlayerCommand, CampaignBackendError> {
        if let Some(assignment) = &command.assign_spell {
            self.validate_spell_holder_actor(&assignment.spell_id, assignment.holder_actor)?;
        }
        if let Some(mark) = &command.mark_spell {
            self.validate_spell_holder_actor(&mark.spell_id, mark.holder_actor)?;
        }
        let mut player_command = campaign_player_command(command);
        if command.recover_player
            || command.remove_castle_stage
            || command.recenter
            || command.full_stop
        {
            return Ok(player_command);
        }
        if command.mark_spell.is_some() || command.cycle_marked_spell.is_some() {
            return marked_spells::player_command(
                self.campaign.simulation().shared_spells(),
                command,
                player_command,
            )
            .map_err(|message| CampaignBackendError::StepRejected { message });
        }
        if let Some(assignment) = &command.assign_spell {
            if command.select_spell.is_some() {
                return Err(CampaignBackendError::StepRejected {
                    message: "spell assignment and selection require separate commands".to_owned(),
                });
            }
            return spells::assigned_player_command(
                self.campaign.simulation().shared_spells(),
                assignment,
                player_command,
            )
            .map_err(|message| CampaignBackendError::StepRejected { message });
        }
        let Some(selection) = command.select_spell.as_ref() else {
            return Ok(player_command);
        };
        let Some(kind) = semantic_spell_kind(selection) else {
            return Err(CampaignBackendError::StepRejected {
                message: format!(
                    "spell selection {} is not a closed semantic spell ID",
                    selection.as_str()
                ),
            });
        };
        let compatibility = self.campaign.simulation();
        let family = mc2_spell_family(kind).ok_or_else(|| CampaignBackendError::StepRejected {
            message: format!(
                "spell selection {} has no bound private spell family",
                selection.as_str()
            ),
        })?;
        let shared = compatibility.shared_spells();
        if spells::acquired_holder(shared, family).is_none() {
            return Err(CampaignBackendError::StepRejected {
                message: format!(
                    "spell selection {} is not acquired by the local player",
                    selection.as_str()
                ),
            });
        }
        let ui_index = SOURCE_SPELL_INDEX_MAP
            .iter()
            .position(|candidate| *candidate == family)
            .expect("bound private spell family retains a source UI index");
        player_command.opcode = 40;
        player_command.argument_1 =
            i8::try_from(ui_index).expect("source spell UI index fits the private input byte");
        Ok(player_command)
    }
}

fn campaign_player_command(command: &GameCommand) -> PlayerCommand {
    let mut flags = match command.longitudinal {
        LongitudinalControl::Coast => 0,
        LongitudinalControl::Accelerate => 0x01,
        LongitudinalControl::Decelerate => 0x02,
    };
    flags |= match command.lateral {
        LateralControl::Neutral => 0,
        LateralControl::Negative => 0x04,
        LateralControl::Positive => 0x08,
    };
    flags |= u8::from(command.cast_left) * 0x10;
    flags |= u8::from(command.cast_right) * 0x20;
    flags |= u8::from(command.cast_selected) * 0x40;
    PlayerCommand {
        opcode: if command.recover_player {
            0x0f
        } else if command.remove_castle_stage {
            42
        } else if command.recenter || command.full_stop {
            0x27
        } else {
            0
        },
        argument_1: i8::from(command.full_stop),
        roll: command.roll_axis,
        pitch: command.pitch_axis,
        flags: flags.cast_signed(),
        argument_6: command.look_yaw.cast_unsigned(),
        argument_8: command.look_pitch.cast_unsigned(),
        ..PlayerCommand::default()
    }
}

fn hex_digest(bytes: [u8; 32]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

