    #[test]
    fn abandoned_secret_return_preserves_parent_and_entry_carry() {
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime, RuntimeMode,
            RuntimeTransitionError, SecretTransitionKind,
        };
        use crate::game_session::GameCompletionStatistics;

        // This boundary fixture supplies a retained Level-5 frontier and enters
        // its installed secret through the existing runtime boundary. Inventory
        // and XP use the genuine Level 1 package and award primitive; this does
        // not claim a played Level 1-4 frontier or source portal gameplay.
        let generated = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../generated");
        let resolver = Mc2RuntimePackageResolver::load(
            [
                "mc-bhq8-level1-collision-v5-night",
                "level2-day-block32-campaign-v2",
                "level3-day-block32-campaign-recipe-v2",
                "mc-bhq6-ordinary-20261025-zclu5fjj/level4",
                "mc-paj2-source4-campaign-package",
                "mc-paj2-source30-campaign-package",
            ]
            .map(|path| Mc2CampaignInputs::new(generated.join(path))),
        )
        .unwrap();
        let level1_root = generated.join("mc-bhq8-level1-collision-v5-night");
        let level1_package = resolver
            .package(resolver.flow().entry_level_id())
            .expect("resolver retains the genuine Level 1 package");
        let mut level1_session = GameSession::open(
            &Mc2CampaignAdapter,
            Arc::clone(&level1_package.definition),
            7434,
            Mc2CampaignInputs::new(level1_root),
        )
        .unwrap();
        let initial_inventory = level1_session.backend().semantic_spell_carry().unwrap();
        assert_eq!(
            initial_inventory.acquired,
            vec![SpellKind::Fireball, SpellKind::Possession]
        );
        let fireball_family = mc2_spell_family(SpellKind::Fireball).unwrap();
        let level1_player = level1_session
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .entity_index;
        level1_session
            .backend_mut()
            .campaign
            .simulation_mut()
            .shared_spells_mut()
            .award_spell_experience(level1_player, fireball_family, 1);
        let inherited_carry = level1_session.backend().transition_spell_carry().unwrap();
        assert_eq!(inherited_carry.acquired, initial_inventory.acquired);
        assert_eq!(inherited_carry.selected, initial_inventory.selected);
        let inherited_fireball = inherited_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the source award adds Fireball to the genuine Level 1 carry");
        assert!(inherited_fireball.persistent_experience > 0);
        assert_eq!(inherited_fireball.runtime_experience, 0);
        let secret_entry = resolver.flow().secret_entries().first().unwrap();
        let origin = secret_entry.origin_level_id().clone();
        let secret_level = secret_entry.secret_level_id().clone();
        let origin_index = resolver
            .flow()
            .entries()
            .iter()
            .position(|entry| entry.level_id() == &origin)
            .unwrap();
        assert_eq!(origin_index, 4);
        let completed_levels = resolver
            .flow()
            .entries()
            .iter()
            .take(origin_index)
            .map(|entry| entry.level_id().clone())
            .collect::<Vec<_>>();
        let level_statistics = completed_levels
            .iter()
            .map(|level_id| crate::game_runtime::CompletedLevelStatistics {
                level_id: level_id.clone(),
                statistics: GameCompletionStatistics {
                    spells_found_percent: 15,
                    hit_accuracy_percent: 25,
                    creatures_killed_percent: 35,
                    mana_collected_percent: 45,
                    time_taken_seconds: 123,
                },
            })
            .collect::<Vec<_>>();
        let entry_definition = Arc::clone(
            &resolver
                .package(resolver.flow().entry_level_id())
                .unwrap()
                .definition,
        );
        let parent_save = CampaignSaveState {
            definition: entry_definition.as_ref().clone(),
            phase: CampaignMenuPhase::MissionSelect,
            completed_level_id: None,
            selected_level_id: Some(origin.clone()),
            completed_levels: completed_levels.clone(),
            level_statistics: level_statistics.clone(),
        };
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7433).unwrap();
        let title = runtime.identity();
        let map = runtime
            .restore_campaign_resolved(
                title.guard(),
                parent_save,
                Default::default(),
                |definition, selected| {
                    resolver.exact_package_for_definition(definition)?;
                    resolver
                        .package(selected)
                        .map(|package| Arc::clone(&package.definition))
                        .ok_or_else(|| RuntimeTransitionError::InvalidRuntimeFlow {
                            message: "saved campaign selection is not installed".to_owned(),
                        })
                },
            )
            .unwrap();
        let loading = resolver
            .campaign_menu_command(&mut runtime, map.guard(), CampaignMenuCommand::StartMission)
            .unwrap();
        let playing = resolver
            .open_pending(&mut runtime, loading.guard(), 7433)
            .unwrap();
        let ordinary_session_guard = playing.session.as_ref().unwrap().guard();
        let ordinary_before = runtime.identity();
        assert!(
            resolver
                .abandon_secret_if_active(&mut runtime, playing.guard(), ordinary_session_guard)
                .unwrap()
                .is_none()
        );
        assert_eq!(runtime.identity(), ordinary_before);

        let stale_outer = crate::game_runtime::RuntimeGuard {
            runtime_id: playing.runtime_id,
            generation: playing.generation - 1,
        };
        assert!(matches!(
            resolver.abandon_secret_if_active(&mut runtime, stale_outer, ordinary_session_guard),
            Err(RuntimeTransitionError::Guard(_))
        ));
        let mut stale_session = ordinary_session_guard;
        stale_session.expected_tick += 1;
        assert!(matches!(
            resolver.abandon_secret_if_active(&mut runtime, playing.guard(), stale_session),
            Err(RuntimeTransitionError::SessionGuard(_))
        ));
        assert_eq!(runtime.identity(), ordinary_before);
        assert!(runtime.secret_flow_state().return_frame().is_none());

        runtime
            .session_mut()
            .unwrap()
            .backend_mut()
            .apply_semantic_spell_carry(&inherited_carry)
            .unwrap();
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .semantic_spell_carry()
                .unwrap(),
            inherited_carry
        );
        let retained_parent = runtime.retained_campaign().cloned().unwrap();
        assert_eq!(retained_parent.selected_level_id.as_ref(), Some(&origin));
        assert_eq!(retained_parent.completed_levels, completed_levels);
        assert_eq!(retained_parent.level_statistics, level_statistics);

        let parent_session_guard = runtime.session().unwrap().identity().guard();
        let secret_receipt = runtime
            .enter_secret_resolved(playing.guard(), parent_session_guard, |parent_session| {
                resolver.exact_package_for_definition(parent_session.definition())?;
                let destination = resolver.package(&secret_level).ok_or_else(|| {
                    RuntimeTransitionError::InvalidRuntimeFlow {
                        message: "installed secret package is unavailable".to_owned(),
                    }
                })?;
                let generation = parent_session
                    .identity()
                    .generation
                    .checked_add(1)
                    .and_then(std::num::NonZeroU64::new)
                    .ok_or(RuntimeTransitionError::GenerationExhausted)?;
                let mut candidate = GameSession::open_with_generation(
                    &Mc2CampaignAdapter,
                    Arc::clone(&destination.definition),
                    parent_session.identity().session_id,
                    generation,
                    destination.inputs.clone(),
                )
                .map_err(|error| {
                    RuntimeTransitionError::InvalidNextDefinition {
                        message: error.to_string(),
                    }
                })?;
                let carry = parent_session.backend().transition_spell_carry()?;
                let context = parent_session.backend().campaign.source_global_context();
                candidate.backend_mut().apply_semantic_spell_carry(&carry)?;
                candidate
                    .backend_mut()
                    .install_initial_source_context(context)?;
                Ok((secret_level.clone(), candidate))
            })
            .unwrap();
        assert!(secret_receipt.verify());
        assert_eq!(secret_receipt.kind, SecretTransitionKind::Entry);

        let entry_carry = runtime
            .session()
            .unwrap()
            .backend()
            .initial_semantic_spell_carry()
            .unwrap();
        assert_eq!(entry_carry, inherited_carry);
        let source_context = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .source_global_context();
        let entry_fireball = entry_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the genuine inherited carry retains its Fireball XP baseline");
        let secret_player = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .entity_index;
        runtime
            .session_mut()
            .unwrap()
            .backend_mut()
            .campaign
            .simulation_mut()
            .shared_spells_mut()
            .award_spell_experience(secret_player, fireball_family, 777);
        let mission_carry = runtime
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert_eq!(mission_carry.acquired, entry_carry.acquired);
        let mission_fireball = mission_carry
            .progression
            .iter()
            .find(|progress| progress.spell == SpellKind::Fireball)
            .expect("the secret's source XP award updates the carried Fireball");
        assert_eq!(
            mission_fireball.persistent_experience,
            entry_fireball.persistent_experience
        );
        assert_eq!(
            mission_fireball.runtime_experience,
            entry_fireball.runtime_experience.checked_add(777).unwrap()
        );
        assert_ne!(mission_carry, entry_carry);

        let secret_playing = runtime.identity();
        let paused = runtime.pause(secret_playing.guard()).unwrap();
        assert_eq!(paused.mode, RuntimeMode::Paused);
        let paused_session_guard = paused.session.as_ref().unwrap().guard();
        let paused_context = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .source_global_context();
        let receipt = resolver
            .abandon_secret_if_active(&mut runtime, paused.guard(), paused_session_guard)
            .unwrap()
            .unwrap();
        assert!(receipt.verify());
        assert_eq!(receipt.kind, SecretTransitionKind::AbandonedReturn);
        assert_eq!(receipt.before.mode, RuntimeMode::Paused);
        assert_eq!(receipt.after.mode, RuntimeMode::Campaign);
        assert_eq!(receipt.origin_level_id, origin);
        assert_eq!(
            receipt
                .after
                .campaign_menu
                .as_ref()
                .unwrap()
                .selected_level_id
                .as_ref(),
            Some(&origin)
        );
        let mut activated_parent = retained_parent;
        if !activated_parent.completed_levels.contains(&origin) {
            activated_parent.completed_levels.push(origin.clone());
        }
        assert_eq!(runtime.campaign_save_state().unwrap(), activated_parent);
        let secret_progress = receipt.after.secret_campaign.as_ref().unwrap();
        assert!(secret_progress.discovered_levels.contains(&secret_level));
        assert!(!secret_progress.completed_levels.contains(&secret_level));

        let pending = resolver
            .pending_spell_carries
            .lock()
            .unwrap()
            .get(&paused.runtime_id)
            .cloned()
            .unwrap();
        assert_eq!(pending.destination_level, origin);
        assert_eq!(
            pending.session_generation,
            runtime.campaign_session_generation().unwrap()
        );
        assert_eq!(pending.carry, entry_carry);
        assert_eq!(
            resolver
                .detached_source_contexts
                .lock()
                .unwrap()
                .get(&paused.runtime_id),
            Some(&paused_context)
        );
        assert_ne!(mission_carry, pending.carry);
        assert_eq!(source_context, paused_context);
    }

    #[test]
    fn dynamic_light_constructor_option_and_live_changes_survive_replay_and_reset() {
        use crate::game_runtime::{GameRuntime, preferences::PreferencesCommand};

        let night = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../generated/mc-bhq8-level1-collision-v5-night");
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&night),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let profile = std::env::temp_dir().join(format!(
            "mc-dynamic-light-replay-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos(),
        ));
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7130).unwrap();
        runtime
            .preferences_command(
                runtime.identity().guard(),
                PreferencesCommand::Install {
                    profile_dir: profile.to_string_lossy().into_owned(),
                },
            )
            .unwrap();
        let mut preferences = runtime.identity().player_preferences.preferences;
        preferences.dynamic_lighting = false;
        runtime
            .preferences_command(
                runtime.identity().guard(),
                PreferencesCommand::Apply { preferences },
            )
            .unwrap();
        let title_guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, title_guard).unwrap();
        resolver
            .open_pending(&mut runtime, loading.guard(), 7130)
            .unwrap();
        let definition = Arc::clone(runtime.session().unwrap().definition());
        let cast = GameCommand {
            cast_left: true,
            ..GameCommand::default()
        };
        {
            let session = runtime.session_mut().unwrap();
            assert!(!session.backend().dynamic_lighting_enabled());
            session
                .step(session.identity().guard(), cast.clone())
                .unwrap();
            assert!(
                player_spell_projectile_count(session) > 0,
                "disabled lighting must retain the real ordinary Fireball producer"
            );
            assert_eq!(
                session
                    .backend()
                    .campaign
                    .simulation()
                    .source_arena()
                    .dynamic_lighting
                    .active_count(),
                0
            );
            session.backend_mut().set_dynamic_lighting_enabled(true);
            session
                .step(session.identity().guard(), GameCommand::default())
                .unwrap();
            session.backend_mut().set_dynamic_lighting_enabled(false);
            session.backend_mut().set_dynamic_lighting_enabled(true);
            let checkpoint = session.backend().dynamic_lighting_change_count();
            session.backend_mut().set_dynamic_lighting_enabled(false);
            session
                .backend_mut()
                .restore_dynamic_lighting_after_rejection(true, checkpoint);
            assert_eq!(
                session.backend().dynamic_lighting_change_count(),
                checkpoint
            );
        }
        let mut enabled = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            7131,
            Mc2CampaignInputs::new(&night),
        )
        .unwrap();
        enabled.step(enabled.identity().guard(), cast).unwrap();
        assert!(player_spell_projectile_count(&enabled) > 0);
        assert!(
            enabled
                .backend()
                .campaign
                .simulation()
                .source_arena()
                .dynamic_lighting
                .active_count()
                > 0,
            "the same ordinary Fireball constructor must admit a real light when enabled"
        );

        let paused = runtime.pause(runtime.identity().guard()).unwrap();
        // Paused frames consume the persistent option too. Keep the real
        // preference in sync with the live changes exercised above.
        let mut preferences = runtime.identity().player_preferences.preferences;
        preferences.dynamic_lighting = true;
        runtime
            .preferences_command(
                runtime.identity().guard(),
                PreferencesCommand::Apply { preferences },
            )
            .unwrap();
        runtime
            .apply_current_dynamic_lighting_preference(runtime.identity().guard())
            .unwrap();
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime
            .paused_campaign_frame_timed(paused.guard(), session_guard, 13, false)
            .unwrap();
        let bytes = resolver.save_replay(&runtime).unwrap();
        let saved: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        assert!(!saved.initial_dynamic_lighting);
        assert_eq!(
            saved.dynamic_lighting_changes,
            vec![
                Mc2DynamicLightingChange {
                    before_operation: 1,
                    enabled: true
                },
                Mc2DynamicLightingChange {
                    before_operation: 2,
                    enabled: false
                },
                Mc2DynamicLightingChange {
                    before_operation: 2,
                    enabled: true
                },
            ]
        );
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7132).unwrap();
        let restore_guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, restore_guard, 7132, &bytes)
            .unwrap();
        assert!(
            restored
                .session()
                .unwrap()
                .backend()
                .dynamic_lighting_enabled()
        );
        assert_eq!(
            resolver.save_replay(&restored).unwrap(),
            bytes,
            "ordinary cast, pause and policy boundaries must reproduce all saved receipts"
        );

        let mut corrupt = saved;
        corrupt.dynamic_lighting_changes[0].before_operation = corrupt.operations.len() + 1;
        corrupt.receipt_sha256 = corrupt.compute_receipt_sha256();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7133).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay(
                &mut rejected,
                before.guard(),
                7133,
                &serde_json::to_vec(&corrupt).unwrap()
            ),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());

        let resumed = restored.resume(restored.identity().guard()).unwrap();
        let session = restored.session_mut().unwrap();
        session.reset(session.identity().guard()).unwrap();
        assert!(session.backend().dynamic_lighting_enabled());
        assert_eq!(
            session.backend().dynamic_lighting_changes,
            vec![Mc2DynamicLightingChange {
                before_operation: 0,
                enabled: true
            },]
        );
        assert_eq!(restored.identity().generation, resumed.generation);
        let reset_bytes = resolver.save_replay(&restored).unwrap();
        let mut reset_replay = GameRuntime::<Mc2CampaignBackend>::title(7134).unwrap();
        let reset_guard = reset_replay.identity().guard();
        resolver
            .load_replay(&mut reset_replay, reset_guard, 7134, &reset_bytes)
            .unwrap();
        assert_eq!(resolver.save_replay(&reset_replay).unwrap(), reset_bytes);

        std::fs::remove_file(profile.join("player-preferences.json")).unwrap();
        std::fs::remove_dir(profile).unwrap();
    }

    #[test]
    fn campaign_elapsed_clock_repair_replays_step_and_pause_without_tick_guessing() {
        use crate::game_runtime::GameRuntime;
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(
                PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                    .join("../../../generated/mc-bhq8-level1-collision-v5-night"),
            ),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7120).unwrap();
        let guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, guard).unwrap();
        resolver
            .open_pending(&mut runtime, loading.guard(), 7120)
            .unwrap();
        let session = runtime.session_mut().unwrap();
        session
            .step(
                session.identity().guard(),
                GameCommand {
                    elapsed_centiseconds: 123,
                    ..Default::default()
                },
            )
            .unwrap();
        let tick = runtime.session().unwrap().identity().tick;
        let source_turn = runtime
            .session()
            .unwrap()
            .backend()
            .campaign
            .simulation()
            .shared_spells()
            .local_player()
            .turn;
        let source_camera_pose = runtime
            .session()
            .unwrap()
            .snapshot()
            .value
            .source_camera_pose;
        let guard = runtime.identity().guard();
        let paused = runtime.pause(guard).unwrap();
        let session_guard = runtime.session().unwrap().identity().guard();
        runtime
            .paused_campaign_frame_timed(paused.guard(), session_guard, 177, false)
            .unwrap();
        assert_eq!(runtime.session().unwrap().identity().tick, tick);
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .shared_spells()
                .local_player()
                .turn,
            source_turn.wrapping_add(1)
        );
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .snapshot()
                .value
                .source_camera_pose,
            source_camera_pose,
            "paused PlayerEvents must preserve the captured source view"
        );
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .completion_statistics()
                .time_taken_seconds,
            3
        );
        let bytes = resolver.save_replay(&runtime).unwrap();
        let mut forged: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        assert!(forged.initial_mission_rewards.is_none());
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .mission_rewards(),
            crate::campaign::rewards::MissionRewards::Enabled
        );
        let mut forged_rewards = forged.clone();
        forged_rewards.initial_mission_rewards =
            Some(crate::campaign::rewards::MissionRewards::Suppressed);
        forged_rewards.receipt_sha256 = forged_rewards.compute_receipt_sha256();
        let mut rejected_rewards = GameRuntime::<Mc2CampaignBackend>::title(7126).unwrap();
        let before_rewards = rejected_rewards.identity();
        assert!(matches!(
            resolver.load_replay(
                &mut rejected_rewards,
                before_rewards.guard(),
                7126,
                &serde_json::to_vec(&forged_rewards).unwrap(),
            ),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected_rewards.identity(), before_rewards);
        assert!(forged.initial_secret_continuation.is_none());
        assert!(
            serde_json::from_slice::<serde_json::Value>(&bytes)
                .unwrap()
                .get("initial_secret_continuation")
                .is_none()
        );
        let origin = forged
            .definition
            .runtime_flow()
            .unwrap()
            .bound_level_id()
            .clone();
        forged.initial_secret_continuation =
            Some(sim_definition::runtime_flow::RuntimeFlowSecretEntry::new(
                origin,
                SemanticLevelId::parse("level.magic_carpet_2.unavailable_secret").unwrap(),
            ));
        forged.receipt_sha256 = forged.compute_receipt_sha256();
        let forged_bytes = serde_json::to_vec(&forged).unwrap();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7125).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay(&mut rejected, before.guard(), 7125, &forged_bytes),
            Err(Mc2CampaignReplaySaveError::InvalidSave { .. })
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7121).unwrap();
        let guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, guard, 7121, &bytes)
            .unwrap();
        assert_eq!(
            restored.session().unwrap().snapshot().value,
            runtime.session().unwrap().snapshot().value
        );
        assert_eq!(
            restored
                .session()
                .unwrap()
                .backend()
                .campaign
                .simulation()
                .completion_statistics()
                .time_taken_seconds,
            3
        );
        assert_eq!(resolver.save_replay(&restored).unwrap(), bytes);
        let warm_context = GlobalSpecialState {
            protection_ticks: 23,
            visibility_mode: 2,
            damage_flash_ticks: 0,
        };
        // Keep the envelope valid while making the replay's final state
        // receipt false, so this exercises candidate verification itself.
        let mut corrupt: Mc2CampaignReplaySave = serde_json::from_slice(&bytes).unwrap();
        corrupt.expected_state_hash ^= 1;
        corrupt.receipt_sha256 = corrupt.compute_receipt_sha256();
        let corrupt_bytes = serde_json::to_vec(&corrupt).unwrap();
        let mut rejected = GameRuntime::<Mc2CampaignBackend>::title(7124).unwrap();
        let before = rejected.identity();
        assert!(matches!(
            resolver.load_replay_with_source_context(
                &mut rejected,
                before.guard(),
                7124,
                &corrupt_bytes,
                warm_context,
            ),
            Err(Mc2CampaignReplaySaveError::Restore(
                crate::game_runtime::RestorePlayingError::Transition(
                    crate::game_runtime::RuntimeTransitionError::InvalidReplay { .. }
                )
            ))
        ));
        assert_eq!(rejected.identity(), before);
        assert!(rejected.session().is_none());
        let mut warm = GameRuntime::<Mc2CampaignBackend>::title(7122).unwrap();
        let guard = warm.identity().guard();
        let loaded = resolver
            .load_replay_with_source_context(&mut warm, guard, 7122, &bytes, warm_context)
            .unwrap();
        assert_eq!(loaded.mode, crate::game_runtime::RuntimeMode::Paused);
        assert!(
            warm.session_mut().is_none(),
            "warm restore must preserve the paused gameplay mutation gate"
        );
        assert_eq!(warm.session().unwrap().identity().tick, tick);
        assert_eq!(
            warm.session()
                .unwrap()
                .backend()
                .campaign
                .source_global_context(),
            warm_context
        );
        let warm_bytes = resolver.save_replay(&warm).unwrap();
        let mut roundtrip = GameRuntime::<Mc2CampaignBackend>::title(7123).unwrap();
        let guard = roundtrip.identity().guard();
        resolver
            .load_replay(&mut roundtrip, guard, 7123, &warm_bytes)
            .unwrap();
        assert_eq!(
            roundtrip.identity().mode,
            crate::game_runtime::RuntimeMode::Paused
        );
        assert_eq!(
            roundtrip.session().unwrap().snapshot().value,
            warm.session().unwrap().snapshot().value
        );
        assert_eq!(resolver.save_replay(&roundtrip).unwrap(), warm_bytes);
    }

    #[test]
    fn campaign_map_save_repair_roundtrips_frontier_carry_and_rejects_tampering() {
        use crate::game_runtime::{
            CampaignMenuCommand, CampaignMenuPhase, CampaignSaveState, GameRuntime, RuntimeMode,
        };
        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(7110).unwrap();
        let guard = runtime.identity().guard();
        let loading = resolver.new_game(&mut runtime, guard).unwrap();
        runtime.show_new_game_map(loading.guard()).unwrap();
        let new_map = resolver.save_replay(&runtime).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7111).unwrap();
        let guard = restored.identity().guard();
        resolver
            .load_replay(&mut restored, guard, 7111, &new_map)
            .unwrap();
        assert_eq!(restored.identity().mode, RuntimeMode::Campaign);
        assert!(restored.session().is_none());
        assert_eq!(resolver.save_replay(&restored).unwrap(), new_map);

        // Isolated persistence-boundary fixture, not an earned completion.
        // The real retained carry is obtained from the ordinary package.
        let entry = resolver.flow.entry_level_id().clone();
        let destination = resolver.flow.entries()[1].level_id().clone();
        let mut playing = GameRuntime::<Mc2CampaignBackend>::title(7112).unwrap();
        let guard = playing.identity().guard();
        let loading = resolver.new_game(&mut playing, guard).unwrap();
        resolver
            .open_pending(&mut playing, loading.guard(), 7112)
            .unwrap();
        let carry = playing
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        let state = CampaignSaveState {
            definition: resolver
                .package(&entry)
                .unwrap()
                .definition
                .as_ref()
                .clone(),
            phase: CampaignMenuPhase::Results,
            completed_level_id: Some(entry.clone()),
            selected_level_id: Some(destination.clone()),
            completed_levels: vec![entry],
            level_statistics: vec![],
        };
        let mut save = Mc2CampaignMapSave {
            save_contract: MC2_CAMPAIGN_MAP_SAVE_CONTRACT.to_owned(),
            state,
            semantic_spell_carry: Some(carry.clone()),
            carry_destination_level: Some(destination),
            secret_flow: None,
            source_context: None,
            receipt_sha256: String::new(),
        };
        save.receipt_sha256 = save.compute_receipt_sha256();
        let bytes = serde_json::to_vec(&save).unwrap();
        let mut restored = GameRuntime::<Mc2CampaignBackend>::title(7113).unwrap();
        let guard = restored.identity().guard();
        let mut tampered = serde_json::to_value(&save).unwrap();
        tampered["state"]["completed_levels"] = serde_json::json!([]);
        assert!(
            resolver
                .load_replay(
                    &mut restored,
                    guard,
                    7113,
                    &serde_json::to_vec(&tampered).unwrap()
                )
                .is_err()
        );
        assert_eq!(restored.identity().mode, RuntimeMode::Title);
        resolver
            .load_replay(&mut restored, guard, 7113, &bytes)
            .unwrap();
        assert!(restored.session().is_none());
        assert_eq!(resolver.save_replay(&restored).unwrap(), bytes);
        let guard = restored.identity().guard();
        resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::DismissResults)
            .unwrap();
        let mut retained_map = restored.campaign_menu_snapshot().unwrap();
        // Re-entering from Title has no active results sheet. Its completed
        // missions, frontier, spell carry and retained statistics remain.
        retained_map.completed_level_id = None;
        let guard = restored.identity().guard();
        resolver
            .campaign_menu_command(
                &mut restored,
                guard,
                CampaignMenuCommand::SelectMission {
                    level_id: resolver.flow.entry_level_id().clone(),
                },
            )
            .unwrap();
        let guard = restored.identity().guard();
        let title = resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::ReturnTitle)
            .unwrap();
        let title_save = resolver.save_replay(&restored).unwrap();
        assert_eq!(restored.identity(), title, "Title Save is observational");
        let mut title_restored = GameRuntime::<Mc2CampaignBackend>::title(7115).unwrap();
        let title_guard = title_restored.identity().guard();
        resolver
            .load_replay(&mut title_restored, title_guard, 7115, &title_save)
            .unwrap();
        assert_eq!(title_restored.identity().mode, RuntimeMode::Campaign);
        assert_eq!(
            title_restored.campaign_menu_snapshot().unwrap(),
            retained_map,
            "the original title Save loads its retained campaign at the unfinished map frontier"
        );
        let loading = resolver.new_game(&mut restored, title.guard()).unwrap();
        let map = resolver
            .show_new_game_map(&mut restored, loading.guard())
            .unwrap();
        assert_eq!(
            restored.campaign_menu_snapshot().unwrap(),
            retained_map,
            "Title New Game returns to the unfinished frontier without clearing retained progress"
        );
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&7113)
                .unwrap()
                .carry,
            carry
        );
        let reopened_map_save = resolver.save_replay(&restored).unwrap();
        let mut reopened_map = GameRuntime::<Mc2CampaignBackend>::title(7114).unwrap();
        let reopened_guard = reopened_map.identity().guard();
        resolver
            .load_replay(&mut reopened_map, reopened_guard, 7114, &reopened_map_save)
            .unwrap();
        assert_eq!(
            reopened_map.campaign_menu_snapshot().unwrap(),
            retained_map,
            "saving after Title preserves carry even though the map is no longer showing a completed results row"
        );
        assert!(
            resolver
                .campaign_menu_command(
                    &mut restored,
                    title.guard(),
                    CampaignMenuCommand::ResetCampaign
                )
                .is_err()
        );
        assert_eq!(
            restored.identity(),
            map,
            "stale reset leaves the campaign and carry intact"
        );
        let guard = restored.identity().guard();
        let loading = resolver
            .campaign_menu_command(&mut restored, guard, CampaignMenuCommand::StartMission)
            .unwrap();
        resolver
            .open_pending(&mut restored, loading.guard(), 7113)
            .unwrap();
        let installed = restored
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert!(
            carry
                .acquired
                .iter()
                .all(|spell| installed.acquired.contains(spell))
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&7113)
        );
        let playing = restored.identity();
        let baseline = restored
            .session()
            .unwrap()
            .backend()
            .initial_semantic_spell_carry()
            .unwrap();
        let title = resolver
            .close_to_title(
                &mut restored,
                playing.guard(),
                playing.session.unwrap().guard(),
            )
            .unwrap();
        let loading = resolver.new_game(&mut restored, title.guard()).unwrap();
        let map = resolver
            .show_new_game_map(&mut restored, loading.guard())
            .unwrap();
        assert_eq!(restored.campaign_menu_snapshot().unwrap(), retained_map);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&7113)
                .unwrap()
                .carry,
            baseline,
            "abandon retains entry progression rather than promoting in-level pickups or runtime XP"
        );
        let reset = resolver
            .campaign_menu_command(
                &mut restored,
                map.guard(),
                CampaignMenuCommand::ResetCampaign,
            )
            .unwrap();
        let cleared = reset.campaign_menu.unwrap();
        assert!(cleared.completed_levels.is_empty());
        assert!(cleared.level_statistics.is_empty());
        assert_eq!(
            cleared.selected_level_id.as_ref(),
            Some(resolver.flow.entry_level_id())
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&7113)
        );
    }

    #[test]
    fn runtime_package_resolver_stale_guard_precedes_pending_spell_carry() {
        use crate::game_runtime::{
            GameRuntime, RuntimeGuardErrorCode, RuntimeMode, RuntimeTransitionError,
        };

        let resolver = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(level_one_descriptor_fixture_path()),
            Mc2CampaignInputs::new(descriptor_fixture_path()),
            Mc2CampaignInputs::new(level_three_descriptor_fixture_path()),
        ])
        .unwrap();
        let mut runtime = GameRuntime::<Mc2CampaignBackend>::title(94).unwrap();
        let title = runtime.identity();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        let playing = resolver
            .open_pending(&mut runtime, loading.guard(), 94)
            .unwrap();
        let session_guard = playing.session.as_ref().unwrap().guard();
        let snapshot = runtime.session().unwrap().snapshot();
        let carry = runtime
            .session()
            .unwrap()
            .backend()
            .semantic_spell_carry()
            .unwrap();
        assert_eq!(
            resolver.accept_transition(&mut runtime, playing.guard(), session_guard),
            Err(RuntimeTransitionError::CompletionNotReady)
        );
        assert_eq!(runtime.identity(), playing);
        assert_eq!(runtime.session().unwrap().snapshot(), snapshot);

        let title = runtime.close(playing.guard(), session_guard).unwrap();
        let loading = resolver.new_game(&mut runtime, title.guard()).unwrap();
        let pending = Mc2PendingSpellCarry {
            session_generation: session_guard.generation + 1,
            destination_level: resolver.flow().entry_level_id().clone(),
            carry: carry.clone(),
        };
        // Reproduce only the resolver storage condition created by an accepted
        // edge. Opening/closing above uses the real package and public runtime
        // lifecycle; this fixture does not claim gameplay completion.
        resolver
            .pending_spell_carries
            .lock()
            .unwrap()
            .insert(loading.runtime_id, pending.clone());
        assert_eq!(loading.mode, RuntimeMode::Loading);
        assert!(runtime.session().is_none());

        assert!(matches!(
            resolver.cancel_loading(&mut runtime, playing.guard()),
            Err(RuntimeTransitionError::Guard(_))
        ));
        assert_eq!(runtime.identity(), loading);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );

        let rejected = resolver.accept_transition(&mut runtime, playing.guard(), session_guard);
        assert!(matches!(
            rejected,
            Err(RuntimeTransitionError::Guard(error))
                if error.code == RuntimeGuardErrorCode::GenerationMismatch
                    && error.expected == loading && error.actual == playing.guard()
        ));
        assert_eq!(runtime.identity(), loading);
        assert!(runtime.session().is_none());
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );

        // A current outer guard retains the existing pending-carry rejection.
        let rejected = resolver.accept_transition(&mut runtime, loading.guard(), session_guard);
        assert!(matches!(
            rejected,
            Err(RuntimeTransitionError::InvalidRuntimeFlow { message })
                if message == "resolver already owns a pending spell carry for this runtime"
        ));
        assert_eq!(runtime.identity(), loading);
        assert_eq!(
            resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .get(&loading.runtime_id),
            Some(&pending)
        );
        let reopened = resolver
            .open_pending(&mut runtime, loading.guard(), 94)
            .unwrap();
        assert_eq!(reopened.mode, RuntimeMode::Playing);
        assert!(reopened.session.as_ref().unwrap().generation > session_guard.generation);
        assert_eq!(
            runtime
                .session()
                .unwrap()
                .backend()
                .semantic_spell_carry()
                .unwrap(),
            carry
        );
        assert!(
            !resolver
                .pending_spell_carries
                .lock()
                .unwrap()
                .contains_key(&loading.runtime_id)
        );
    }

    #[test]
    fn runtime_package_resolver_canonicalizes_order_and_rejects_open_flow_sets() {
        let level_one = level_one_descriptor_fixture_path();
        let level_two = descriptor_fixture_path();
        let level_three = level_three_descriptor_fixture_path();
        let forward = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap();
        let reverse = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_three),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_one),
        ])
        .unwrap();
        assert_eq!(forward.flow(), reverse.flow());
        assert_eq!(
            forward.flow().bound_level_id(),
            forward.flow().entry_level_id()
        );

        let incomplete = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap_err();
        assert_eq!(incomplete.code, DefinitionErrorCode::DependencyFailed);

        let duplicate = Mc2RuntimePackageResolver::load([
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_one),
            Mc2CampaignInputs::new(&level_two),
            Mc2CampaignInputs::new(&level_three),
        ])
        .unwrap_err();
        assert_eq!(duplicate.code, DefinitionErrorCode::DuplicateBinding);

        // No-Claim: this constructor gate proves only definition-derived,
        // order-independent closure for the three qualified resource roots.
        // It does not validate owner-cache bytes, install/discover packages,
        // open gameplay, or consume a completion edge.
    }

    fn publish_player_max_forward_speed(
        store: &WorkspaceStore,
        catalog: &SemanticCatalog,
        active: &GameDefinition,
        idempotency_key: &str,
        speed: i64,
    ) -> GameDefinition {
        let change_set = ChangeSetBuilder::new(
            "campaign-flight-authoring",
            active,
            idempotency_key,
            RequestedTiming::SessionReset,
        )
        .set_integer(IntegerParameter::PlayerMaxForwardSpeed, speed)
        .build()
        .expect("typed flight change set");
        let validation = store
            .validate(catalog, change_set.clone())
            .expect("flight change validates");
        assert!(validation.accepted, "{:#?}", validation.diagnostics);
        store
            .apply(
                catalog,
                change_set,
                &validation.receipt_hash,
                PublicationFault::None,
            )
            .expect("flight change publishes");
        store.active_definition().expect("published definition")
    }

