    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct SkeletonFireballDamageReceipt {
        source_slot: u16,
        life_before: i32,
        life_after: i32,
    }

    fn level_three_skeleton(
        session: &GameSession<Mc2CampaignBackend>,
        source_slot: u16,
    ) -> Option<crate::native_world::EntitySnapshot> {
        session
            .backend()
            .campaign
            .simulation()
            .entities()
            .get(usize::from(source_slot))
            .filter(|source| {
                source.active
                    && !source.drawing_disabled()
                    && source.index == source_slot
                    && source.class == 5
                    && source.model == 9
            })
            .cloned()
    }

    #[derive(Clone, Copy, Debug)]
    struct SkeletonDeathOutput {
        sphere_event: usize,
        sphere_id: u32,
        mana: i32,
        burst_event: usize,
        burst_slot: u16,
    }

    struct SkeletonLifecycleObservation {
        generation: u32,
        actions: BTreeSet<u8>,
        death_output: Option<SkeletonDeathOutput>,
    }

    impl SkeletonLifecycleObservation {
        fn new(session: &GameSession<Mc2CampaignBackend>, slot: u16) -> Self {
            let compatibility = session.backend().campaign.simulation();
            Self {
                generation: compatibility.economy().slot_generation(slot),
                actions: BTreeSet::from([level_three_skeleton(session, slot).unwrap().action]),
                death_output: None,
            }
        }
    }

    fn observed_level_three_skeleton(
        session: &GameSession<Mc2CampaignBackend>,
        slot: u16,
        observations: &BTreeMap<u16, SkeletonLifecycleObservation>,
    ) -> Option<crate::native_world::EntitySnapshot> {
        let original = observations.get(&slot)?;
        if session
            .backend()
            .campaign
            .simulation()
            .economy()
            .slot_generation(slot)
            != original.generation
        {
            return None;
        }
        level_three_skeleton(session, slot)
    }

    fn observe_real_level_three_skeleton_actions_for_test(
        session: &GameSession<Mc2CampaignBackend>,
        observed_actions: &mut BTreeMap<u16, SkeletonLifecycleObservation>,
    ) {
        for (source_slot, observation) in observed_actions {
            if let Some(source) = session
                .backend()
                .campaign
                .simulation()
                .entities()
                .get(usize::from(*source_slot))
                .filter(|source| {
                    source.active
                        && source.index == *source_slot
                        && source.class == 5
                        && source.model == 9
                })
            {
                if session
                    .backend()
                    .campaign
                    .simulation()
                    .economy()
                    .slot_generation(*source_slot)
                    == observation.generation
                {
                    observation.actions.insert(source.action);
                }
            }
        }
    }

    fn step_real_level_three_skeleton_route_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        command: GameCommand,
        observed_actions: &mut BTreeMap<u16, SkeletonLifecycleObservation>,
    ) {
        observe_real_level_three_skeleton_actions_for_test(session, observed_actions);
        let compatibility = session.backend().campaign.simulation();
        let event_start = compatibility.economy().events().len();
        let original_slots = observed_actions
            .iter()
            .filter(|(slot, observation)| {
                observation.death_output.is_none()
                    && compatibility.economy().slot_generation(**slot) == observation.generation
                    && compatibility
                        .entities()
                        .get(usize::from(**slot))
                        .is_some_and(|source| {
                            source.active && source.class == 5 && source.model == 9
                        })
            })
            .map(|(slot, _)| *slot)
            .collect::<Vec<_>>();
        session.step(guard(session), command).unwrap();
        let events = session.backend().campaign.simulation().economy().events();
        for slot in original_slots {
            let fresh = &events[event_start..];
            let Some((birth_offset, sphere_id, mana)) =
                fresh
                    .iter()
                    .enumerate()
                    .find_map(|(offset, event)| match event {
                        crate::native_world::Level2EconomyEvent::ManaSphereSpawned {
                            sphere_id,
                            source_entity_index,
                            mana,
                        } if *source_entity_index == slot => Some((offset, *sphere_id, *mana)),
                        _ => None,
                    })
            else {
                continue;
            };
            assert_eq!(
                mana, 500,
                "original Skeleton occurrence {slot} emits its exact mana payload"
            );
            let (burst_offset, burst_slot) = fresh
                .iter()
                .enumerate()
                .skip(birth_offset + 1)
                .find_map(|(offset, event)| match event {
                    crate::native_world::Level2EconomyEvent::DeathBurstSpawned {
                        source_entity_index,
                        parent_entity_index,
                        id_entity_index,
                    } if *parent_entity_index == slot && *id_entity_index == slot => {
                        Some((offset, *source_entity_index))
                    }
                    _ => None,
                })
                .expect("original Skeleton mana birth is followed by its ordinary death burst");
            assert_eq!(
                fresh[birth_offset..burst_offset].iter().filter(|event| matches!(event,
                    crate::native_world::Level2EconomyEvent::ManaSphereSpawned { source_entity_index, .. }
                        if *source_entity_index == slot
                )).count(),
                1,
                "one original Skeleton kill callback emits exactly one mana sphere"
            );
            observed_actions.get_mut(&slot).unwrap().death_output = Some(SkeletonDeathOutput {
                sphere_event: event_start + birth_offset,
                sphere_id,
                mana,
                burst_event: event_start + burst_offset,
                burst_slot,
            });
        }
        observe_real_level_three_skeleton_actions_for_test(session, observed_actions);
    }

    fn drive_real_level_three_skeleton_to_fireball_range_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        source_slot: u16,
        observed_actions: &mut BTreeMap<u16, SkeletonLifecycleObservation>,
    ) -> Option<crate::native_world::EntitySnapshot> {
        for _ in 0..24 {
            if let Some(source) =
                observed_level_three_skeleton(session, source_slot, observed_actions)
                && source.life >= 0
                && matches!(source.action, 74 | 79)
            {
                break;
            }
            step_real_level_three_skeleton_route_for_test(
                session,
                GameCommand::default(),
                observed_actions,
            );
        }

        for _ in 0..640 {
            let Some(source) =
                observed_level_three_skeleton(session, source_slot, observed_actions)
            else {
                let observation = &observed_actions[&source_slot];
                assert!(
                    observation.actions.contains(&76) && observation.actions.contains(&77),
                    "selected Skeleton occurrence {source_slot} disappeared without its observed pre-kill/kill: {:?}",
                    observation.actions,
                );
                return None;
            };
            if source.life < 0 {
                assert!(
                    matches!(source.action, 76 | 77),
                    "selected negative-life Skeleton must enter ordinary pre-kill/kill: {source:?}",
                );
                return None;
            }
            if !matches!(source.action, 74 | 79) {
                assert!(
                    matches!(source.action, 72 | 73),
                    "selected live Skeleton entered an unsupported source action: {source:?}",
                );
                // Ordinary movement/countdown may be revisited while prior
                // impacts drain or the player approaches. Keep the original
                // occurrence and let its real callback resume damage handling.
                step_real_level_three_skeleton_route_for_test(
                    session,
                    GameCommand::default(),
                    observed_actions,
                );
                continue;
            }
            let state = session.backend().campaign.simulation().state;
            let dx = i32::from(
                source
                    .position
                    .x
                    .wrapping_sub(state.position.x)
                    .cast_signed(),
            );
            let dy = i32::from(
                source
                    .position
                    .y
                    .wrapping_sub(state.position.y)
                    .cast_signed(),
            );
            let distance = crate::legacy_sqrt(
                dx.wrapping_mul(dx)
                    .wrapping_add(dy.wrapping_mul(dy))
                    .cast_unsigned(),
            );
            if distance <= 3_500 {
                return Some(source);
            }
            // Decode steering through the ordinary source roll accumulator
            // and choose an admitted pitch toward the live target height. A
            // constant climb while stopping to turn can stall this pursuit.
            let command = source_public_creature_pursuit_command_for_test(session, source.position);
            step_real_level_three_skeleton_route_for_test(session, command, observed_actions);
        }
        panic!(
            "ordinary player flight did not reach Skeleton source slot {source_slot}: player={:?} source={:?} actions={:?}",
            session.backend().campaign.simulation().state,
            observed_level_three_skeleton(session, source_slot, observed_actions),
            observed_actions[&source_slot].actions
        );
    }

    fn fire_real_player_fireball_at_level_three_skeleton_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
        source_slot: u16,
        exact_skeleton_slots: &[u16],
        observed_actions: &mut BTreeMap<u16, SkeletonLifecycleObservation>,
    ) -> Vec<SkeletonFireballDamageReceipt> {
        for _ in 0..=24 {
            let compatibility = session.backend().campaign.simulation();
            let economy = compatibility.economy();
            let player_slot = compatibility.state.entity_index;
            let has_player_projectile = economy
                .fireball_projectiles()
                .iter()
                .any(|projectile| projectile.owner_entity_index == player_slot);
            let has_player_impact = economy.model17_spawned_children().iter().any(|impact| {
                impact.source_class == 10
                    && impact.model == 0
                    && impact.parent_entity_id == player_slot
            });
            if !has_player_projectile && !has_player_impact {
                break;
            }
            step_real_level_three_skeleton_route_for_test(
                session,
                GameCommand::default(),
                observed_actions,
            );
        }

        let Some(aimed) = drive_real_level_three_skeleton_to_fireball_range_for_test(
            session,
            source_slot,
            observed_actions,
        ) else {
            // This occurrence completed its ordinary terminal lifecycle while
            // earlier real impacts drained. The outer bounded controller will
            // recensus surviving original occurrences; no new hit is claimed.
            return Vec::new();
        };
        let (attacker, before, projectile_occurrences_before, impact_occurrences_before) = {
            let compatibility = session.backend().campaign.simulation();
            let shared = compatibility.shared_spells();
            let player = shared.local_player();
            let holder_slot = player.enabled_spell_holders[0];
            let holder = shared
                .pickups()
                .iter()
                .chain(shared.holders())
                .chain(shared.dynamic_pickups())
                .find(|holder| holder.index == holder_slot)
                .expect("incoming campaign state retains the carried Fireball holder");
            assert!(holder.active);
            assert_eq!((holder.class, holder.model, holder.action), (15, 0, 0));
            assert_eq!(
                holder.source_spell_parent_entity_index(),
                player.entity_index
            );
            assert!((0..=2).contains(&holder.level_gate));
            assert!(shared.player_mana() >= holder.max_mana);
            // Draining the previous cast and flying to this target run the
            // real source scheduler. Peers in the caller's earlier census may
            // finish ordinary pre-kill, kill, hide and reclaim during that gap.
            let before = exact_skeleton_slots
                .iter()
                .filter_map(|slot| match observed_level_three_skeleton(session, *slot, observed_actions) {
                    Some(source) if source.life >= 0 => Some((*slot, source.life)),
                    Some(source) => {
                        assert!(
                            matches!(source.action, 76 | 77),
                            "negative-life Skeleton slot {slot} must be in ordinary pre-kill/kill"
                        );
                        None
                    }
                    None => {
                        let actions = &observed_actions
                            .get(slot)
                            .expect("every package Skeleton retains its lifecycle observations")
                            .actions;
                        assert!(
                            actions.contains(&76) && actions.contains(&77),
                            "absent Skeleton slot {slot} must have completed ordinary pre-kill/kill: {actions:?}"
                        );
                        None
                    }
                })
                .collect::<Vec<_>>();
            (
                compatibility.state.entity_index,
                before,
                compatibility
                    .economy()
                    .fireball_projectiles()
                    .iter()
                    .map(|projectile| {
                        (
                            projectile.source_entity_index,
                            compatibility
                                .economy()
                                .slot_generation(projectile.source_entity_index),
                        )
                    })
                    .collect::<BTreeSet<_>>(),
                compatibility
                    .economy()
                    .model17_spawned_children()
                    .iter()
                    .map(|impact| {
                        (
                            impact.source_entity_index,
                            compatibility
                                .economy()
                                .slot_generation(impact.source_entity_index),
                        )
                    })
                    .collect::<BTreeSet<_>>(),
            )
        };
        assert_eq!(
            aimed.life,
            before
                .iter()
                .find(|(slot, _)| *slot == source_slot)
                .unwrap()
                .1
        );

        // Public selected casting installs the left-hand bit regardless of
        // incoming flags. Forecast the actual Coast body callback: its BODY
        // yaw owns the256 launch displacement, independently of spell look.
        let forecast_command = GameCommand {
            select_spell: Some(SemanticId::parse("spell.fireball").unwrap()),
            ..GameCommand::default()
        };
        let mut cast_forecast = session.backend().campaign.clone();
        cast_forecast.step_with_tuning(
            session
                .backend()
                .campaign_player_command(&forecast_command)
                .unwrap(),
            CAMPAIGN_SPEED_INDEX,
            session.backend().flight_binding.tuning(),
        );
        let forecast = cast_forecast.simulation();
        let cast_state = forecast.state;
        let Some(scheduled_target) =
            forecast
                .entities()
                .get(usize::from(source_slot))
                .filter(|source| {
                    source.active
                        && source.index == source_slot
                        && source.class == 5
                        && source.model == 9
                        && source.life >= 0
                        && forecast.economy().slot_generation(source_slot)
                            == observed_actions[&source_slot].generation
                })
        else {
            return Vec::new();
        };
        let collision = scheduled_target.collision_target();
        let predicted_target = crate::Position {
            z: scheduled_target
                .position
                .z
                .wrapping_add(collision.collision_vertical_offset)
                .wrapping_sub(crate::level1_mission::FIREBALL_COLLISION_VERTICAL_OFFSET),
            ..scheduled_target.position
        };
        let mut launch_position = cast_state.position;
        crate::move_entity(
            &mut launch_position,
            cast_state.yaw.wrapping_sub(512),
            0,
            256,
        );
        if crate::FlightWorld::ground_height(
            session.backend().campaign.simulation().canonical_terrain(),
            launch_position,
        ) > launch_position.z
        {
            launch_position = cast_state.position;
        }
        launch_position.z = launch_position.z.wrapping_add(cast_state.entity_fov);
        let (aim_yaw, aim_pitch) =
            crate::level1_mission::projectile_guidance_angles(launch_position, predicted_target);
        step_real_level_three_skeleton_route_for_test(
            session,
            GameCommand {
                select_spell: Some(SemanticId::parse("spell.fireball").unwrap()),
                cast_selected: true,
                look_yaw: aim_yaw.wrapping_sub(cast_state.yaw),
                look_pitch: aim_pitch.wrapping_sub(cast_state.display_pitch),
                ..GameCommand::default()
            },
            observed_actions,
        );

        let mut saw_projectile = false;
        let mut saw_impact = false;
        let mut projectile_slot = None;
        let mut impact_slot = None;
        for _ in 0..=24 {
            {
                let compatibility = session.backend().campaign.simulation();
                let economy = compatibility.economy();
                if let Some(projectile) = economy.fireball_projectiles().iter().find(|projectile| {
                    projectile.owner_entity_index == attacker
                        && projectile.source_subspell_index
                            == crate::level1_mission::FIREBALL_PAYLOAD as u16
                        && !projectile_occurrences_before.contains(&(
                            projectile.source_entity_index,
                            economy.slot_generation(projectile.source_entity_index),
                        ))
                }) {
                    projectile_slot = Some(projectile.source_entity_index);
                    saw_projectile = true;
                }
                if let Some(impact) = economy.model17_spawned_children().iter().find(|impact| {
                    impact.source_class == 10
                        && impact.model == 0
                        && impact.parent_entity_id == attacker
                        && impact.subspell_index == crate::level1_mission::FIREBALL_PAYLOAD as u16
                        && !impact_occurrences_before.contains(&(
                            impact.source_entity_index,
                            economy.slot_generation(impact.source_entity_index),
                        ))
                }) {
                    projectile_slot = Some(impact.parent_entity_index);
                    impact_slot = Some(impact.source_entity_index);
                    saw_projectile = true;
                    saw_impact = true;
                }
            }
            for event in session.backend().campaign.events() {
                if let Mc2DispatchEvent::DynamicArena {
                    source_slot, kind, ..
                } = event
                {
                    saw_projectile |= projectile_slot == Some(*source_slot)
                        && matches!(
                            kind,
                            crate::native_world::Level2DynamicArenaKind::FireballProjectile
                        );
                    saw_impact |= impact_slot == Some(*source_slot)
                        && matches!(
                            kind,
                            crate::native_world::Level2DynamicArenaKind::Model17SpawnedChild
                        );
                }
            }
            let receipts = before
                .iter()
                .filter_map(|(slot, life_before)| {
                    let current = observed_level_three_skeleton(session, *slot, observed_actions)?;
                    (current.life
                        == life_before.wrapping_sub(crate::level1_mission::FIREBALL_PAYLOAD)
                        && current.word_26() == attacker)
                        .then_some(SkeletonFireballDamageReceipt {
                            source_slot: *slot,
                            life_before: *life_before,
                            life_after: current.life,
                        })
                })
                .collect::<Vec<_>>();
            if !receipts.is_empty() {
                for (slot, life_before) in &before {
                    let current = observed_level_three_skeleton(session, *slot, observed_actions)
                        .expect("public Fireball keeps every nonterminal Skeleton addressable");
                    let received = receipts.iter().any(|receipt| receipt.source_slot == *slot);
                    assert!(
                        received || current.life == *life_before,
                        "public Fireball changed unrelated Skeleton slot {slot}: {life_before} -> {}",
                        current.life
                    );
                }
                assert!(
                    saw_projectile,
                    "semantic cast did not dispatch its class-9 Fireball"
                );
                assert!(
                    saw_impact,
                    "semantic cast did not dispatch its class-10 impact"
                );
                return receipts;
            }
            step_real_level_three_skeleton_route_for_test(
                session,
                GameCommand::default(),
                observed_actions,
            );
        }
        Vec::new()
    }

    #[test]
    fn campaign_backend_carried_fireball_hits_real_level_three_skeleton_through_public_command() {
        const NEAREST_SKELETON_SLOT: u16 = 248;

        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let definition = Arc::new(load_mc2_campaign(&root, &catalog).unwrap());
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            64,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        session
            .backend_mut()
            .campaign
            .simulation_mut()
            .apply_carried_spell_families(&[0], Some(0))
            .unwrap();
        let skeleton_slots = session
            .backend()
            .campaign
            .simulation()
            .entities()
            .iter()
            .filter(|source| source.active && source.class == 5 && source.model == 9)
            .map(|source| source.index)
            .collect::<Vec<_>>();
        assert_eq!(skeleton_slots.len(), 11);
        assert!(skeleton_slots.contains(&NEAREST_SKELETON_SLOT));
        let mut observed_actions = skeleton_slots
            .iter()
            .map(|source_slot| {
                (
                    *source_slot,
                    SkeletonLifecycleObservation::new(&session, *source_slot),
                )
            })
            .collect::<BTreeMap<_, _>>();

        let receipts = fire_real_player_fireball_at_level_three_skeleton_for_test(
            &mut session,
            NEAREST_SKELETON_SLOT,
            &skeleton_slots,
            &mut observed_actions,
        );
        assert_eq!(
            receipts,
            vec![SkeletonFireballDamageReceipt {
                source_slot: NEAREST_SKELETON_SLOT,
                life_before: 1_000,
                life_after: 750,
            }]
        );
        let player = session.backend().campaign.simulation().state.entity_index;
        let damaged = level_three_skeleton(&session, NEAREST_SKELETON_SLOT).unwrap();
        assert_eq!(
            (damaged.life, damaged.action, damaged.word_26()),
            (750, 74, player)
        );
        assert_eq!(&damaged.record_bytes()[102..104], &[0, 0]);

        let repeated = fire_real_player_fireball_at_level_three_skeleton_for_test(
            &mut session,
            NEAREST_SKELETON_SLOT,
            &skeleton_slots,
            &mut observed_actions,
        );
        assert_eq!(
            repeated,
            vec![SkeletonFireballDamageReceipt {
                source_slot: NEAREST_SKELETON_SLOT,
                life_before: 750,
                life_after: 500,
            }]
        );
        let damaged_again = level_three_skeleton(&session, NEAREST_SKELETON_SLOT).unwrap();
        assert_eq!(
            (
                damaged_again.life,
                damaged_again.action,
                damaged_again.word_26()
            ),
            (500, 74, player)
        );
    }

    pub(crate) fn drive_real_level_three_skeleton_horde_to_guardian_dragons_for_test(
        session: &mut GameSession<Mc2CampaignBackend>,
    ) {
        let compatibility = session.backend().campaign.simulation();
        let original_generations = compatibility
            .entities()
            .iter()
            .filter(|source| source.active && source.class == 5 && source.model == 9)
            .map(|source| {
                (
                    source.index,
                    compatibility.economy().slot_generation(source.index),
                )
            })
            .collect::<BTreeMap<_, _>>();
        let skeleton = |session: &GameSession<Mc2CampaignBackend>, source_slot: u16| {
            if session
                .backend()
                .campaign
                .simulation()
                .economy()
                .slot_generation(source_slot)
                != *original_generations.get(&source_slot)?
            {
                return None;
            }
            session
                .backend()
                .campaign
                .simulation()
                .entities()
                .get(usize::from(source_slot))
                .filter(|source| {
                    source.active
                        && source.index == source_slot
                        && source.class == 5
                        && source.model == 9
                })
                .cloned()
        };
        let skeleton_slots = session
            .backend()
            .campaign
            .simulation()
            .entities()
            .iter()
            .filter(|source| source.active && source.class == 5 && source.model == 9)
            .map(|source| source.index)
            .collect::<Vec<_>>();
        assert_eq!(skeleton_slots.len(), 11);
        assert_eq!(
            &session.backend().campaign.simulation().runtime().objectives[0].stage_selectors[..5],
            &[1, 1, 1, 1, 1]
        );
        assert_eq!(
            session
                .snapshot()
                .value
                .objective_progress
                .current_objective
                .as_ref()
                .map(SemanticId::as_str),
            Some("objective.clear.undead_horde")
        );

        let mut observed_actions = skeleton_slots
            .iter()
            .map(|source_slot| {
                (
                    *source_slot,
                    SkeletonLifecycleObservation::new(session, *source_slot),
                )
            })
            .collect::<BTreeMap<_, _>>();

        for _ in 0..24 {
            if skeleton_slots.iter().all(|source_slot| {
                skeleton(session, *source_slot).is_some_and(|row| row.action == 79)
            }) {
                break;
            }
            step_real_level_three_skeleton_route_for_test(
                session,
                GameCommand::default(),
                &mut observed_actions,
            );
        }
        assert!(skeleton_slots.iter().all(|source_slot| {
            skeleton(session, *source_slot).is_some_and(|row| row.action == 79)
        }));

        let package_fireball_pickups = session
            .backend()
            .campaign
            .simulation()
            .mission()
            .authored_features()
            .iter()
            .filter(|feature| feature.kind == 15 && feature.subtype == 0)
            .map(|feature| feature.index)
            .collect::<Vec<_>>();
        assert!(
            package_fireball_pickups.is_empty(),
            "the qualified Level 3 package unexpectedly contains Fireball pickup rows {package_fireball_pickups:?}"
        );
        // The qualified Level 3 package supplies no Fireball pickup, so this
        // public route consumes the acquired family-0 holder carried across
        // the real campaign transition.

        let (sphere_mana_before, economy_event_start) = {
            let economy = session.backend().campaign.simulation().economy();
            (
                economy
                    .spheres()
                    .iter()
                    .map(|sphere| sphere.mana)
                    .sum::<i32>(),
                economy.events().len(),
            )
        };
        let mut hit_count = 0_usize;
        let mut miss_count = 0_usize;
        for _ in 0..skeleton_slots.len() * 16 {
            let current_slots = skeleton_slots
                .iter()
                .copied()
                .filter(|source_slot| {
                    skeleton(session, *source_slot).is_some_and(|source| source.life >= 0)
                })
                .collect::<Vec<_>>();
            let Some(source_slot) = current_slots.iter().copied().min_by_key(|source_slot| {
                let source = skeleton(session, *source_slot).unwrap();
                let player = session.backend().campaign.simulation().state.position;
                let dx = i64::from(i32::from(
                    source.position.x.wrapping_sub(player.x).cast_signed(),
                ));
                let dy = i64::from(i32::from(
                    source.position.y.wrapping_sub(player.y).cast_signed(),
                ));
                dx * dx + dy * dy
            }) else {
                break;
            };
            let receipts = fire_real_player_fireball_at_level_three_skeleton_for_test(
                session,
                source_slot,
                &current_slots,
                &mut observed_actions,
            );
            if receipts.is_empty() {
                miss_count += 1;
            } else {
                hit_count += receipts.len();
            }
            assert!(receipts.iter().all(|receipt| {
                skeleton_slots.contains(&receipt.source_slot)
                    && receipt.life_after
                        == receipt
                            .life_before
                            .wrapping_sub(crate::level1_mission::FIREBALL_PAYLOAD)
            }));
            observe_real_level_three_skeleton_actions_for_test(session, &mut observed_actions);
        }
        assert!(
            skeleton_slots.iter().all(|source_slot| {
                skeleton(session, *source_slot).is_none_or(|source| source.life < 0)
            }),
            "public Fireballs exhausted the existing per-target cast budget: hits={hit_count}, misses={miss_count}"
        );

        for _ in 0..16 {
            if session.backend().campaign.simulation().runtime().objectives[0].stage_selectors[0]
                == 2
                && skeleton_slots
                    .iter()
                    .all(|source_slot| skeleton(session, *source_slot).is_none())
            {
                break;
            }
            step_real_level_three_skeleton_route_for_test(
                session,
                GameCommand::default(),
                &mut observed_actions,
            );
        }
        assert!(
            skeleton_slots
                .iter()
                .all(|source_slot| skeleton(session, *source_slot).is_none())
        );
        for observation in observed_actions.values() {
            assert!(BTreeSet::from([72, 74, 76, 77, 79]).is_subset(&observation.actions));
        }

        let economy = session.backend().campaign.simulation().economy();
        let death_outputs = observed_actions
            .values()
            .map(|observation| {
                observation
                    .death_output
                    .expect("each original Skeleton occurrence emitted its ordinary death products")
            })
            .collect::<Vec<_>>();
        assert_eq!(death_outputs.len(), skeleton_slots.len());
        assert_eq!(
            death_outputs.iter().map(|output| output.mana).sum::<i32>(),
            500 * i32::try_from(skeleton_slots.len()).unwrap(),
            "all eleven original Skeleton occurrences emit exactly 5,500 mana"
        );
        assert_eq!(
            death_outputs
                .iter()
                .map(|output| output.sphere_event)
                .collect::<BTreeSet<_>>()
                .len(),
            skeleton_slots.len(),
            "each original Skeleton has a distinct production sphere birth"
        );
        let sphere_births = economy.events()[economy_event_start..]
            .iter()
            .filter_map(|event| match event {
                crate::native_world::Level2EconomyEvent::ManaSphereSpawned {
                    source_entity_index,
                    sphere_id,
                    mana,
                } => Some((*source_entity_index, *sphere_id, *mana)),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(economy.events()[economy_event_start..].iter().all(|event| !matches!(event,
            crate::native_world::Level2EconomyEvent::ManaSphereCollected { .. }
                | crate::native_world::Level2EconomyEvent::CastleDefenderCollectedSphere { .. }
        )), "the pre-Castle neutral sphere ledger has no collection sink");
        assert_eq!(
            economy
                .spheres()
                .iter()
                .map(|sphere| sphere.mana)
                .sum::<i32>(),
            sphere_mana_before + sphere_births.iter().map(|(_, _, mana)| *mana).sum::<i32>(),
            "source-authored sphere merges conserve every recorded birth, including original Skeleton outputs: births={sphere_births:?}"
        );
        for output in death_outputs {
            assert!(matches!(economy.events()[output.sphere_event],
                crate::native_world::Level2EconomyEvent::ManaSphereSpawned { sphere_id, mana: 500, .. }
                    if sphere_id == output.sphere_id
            ));
            assert!(economy.events()[output.burst_event + 1..].iter().any(|event| matches!(event,
                crate::native_world::Level2EconomyEvent::DeathBurstExpired { source_entity_index, .. }
                    if *source_entity_index == output.burst_slot
            )), "ordinary following-pass cleanup reclaims every original Skeleton burst occurrence");
        }

        let compatibility = session.backend().campaign.simulation();
        assert_eq!(compatibility.runtime().objectives[0].stage_selectors[0], 2);
        assert_eq!(compatibility.runtime().objectives[0].text_selector, 1);
        assert!(
            compatibility
                .dispatch_events()
                .iter()
                .all(|event| !matches!(
                    event,
                    crate::native_world::Mc2DispatchEvent::AuthoredGroupActivated { group: 1, .. }
                ))
        );
        assert_eq!(
            session
                .snapshot()
                .value
                .objective_progress
                .current_objective
                .as_ref()
                .map(SemanticId::as_str),
            Some("objective.clear.guardian_dragons")
        );
        assert_eq!(
            session.snapshot().value.objective_progress.completed_count,
            1
        );
    }

    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct DragonFireballTarget {
        source_slot: u16,
        generation: u32,
        root_slot: u16,
        life: i32,
        attacker: u16,
        position: crate::Position,
        half_width: i16,
        vertical_offset: i16,
        half_height: i16,
    }

    #[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
    enum DragonDamageAttribution {
        Player,
        Dragon(u16),
    }

    fn level_three_direct_dragon_damage_attribution_for_test(
        prior: DragonFireballTarget,
        current: DragonFireballTarget,
        current_targets: &[DragonFireballTarget],
        player: u16,
        corroborated_player_recipients: &BTreeSet<(u16, u32)>,
    ) -> Option<DragonDamageAttribution> {
        if current.life == prior.life - crate::level1_mission::FIREBALL_PAYLOAD
            && current.attacker == player
            && (current.source_slot != current.root_slot
                || corroborated_player_recipients
                    .contains(&(current.source_slot, current.generation)))
        {
            return Some(DragonDamageAttribution::Player);
        }
        let attacker_is_live_dragon_root = current_targets.iter().any(|target| {
            target.source_slot == current.attacker
                && target.source_slot == target.root_slot
                && target.life >= 0
        });
        (current.life == prior.life - 500 && current.attacker != 0 && attacker_is_live_dragon_root)
            .then_some(DragonDamageAttribution::Dragon(current.attacker))
    }

    fn level_three_dragon_fireball_targets(
        session: &GameSession<Mc2CampaignBackend>,
    ) -> Vec<DragonFireballTarget> {
        level_three_dragon_fireball_targets_from_economy(
            session.backend().campaign.simulation().economy(),
        )
    }

    fn level_three_dragon_fireball_targets_from_economy(
        economy: &crate::native_world::Level2EconomyState,
    ) -> Vec<DragonFireballTarget> {
        let mut targets = economy
            .authored_class5()
            .iter()
            .filter(|root| root.active && root.drawing_enabled && root.life >= 0 && root.model == 0)
            .filter_map(|root| {
                let render = economy
                    .authored_dragons()
                    .iter()
                    .find(|render| render.source_entity_index == root.source_entity_index)?;
                Some(DragonFireballTarget {
                    source_slot: root.source_entity_index,
                    generation: economy.slot_generation(root.source_entity_index),
                    root_slot: root.source_entity_index,
                    life: root.life,
                    attacker: if root.word_0x26 != 0 {
                        root.word_0x26
                    } else {
                        root.word_0x96_150
                    },
                    position: root.position,
                    half_width: render.render_pitch,
                    vertical_offset: render.render_yaw,
                    half_height: render.render_fov,
                })
            })
            .collect::<Vec<_>>();
        targets.extend(economy.authored_dragon_parts().iter().filter_map(|part| {
            (part.active && part.drawing_enabled && part.life >= 0).then_some(
                DragonFireballTarget {
                    source_slot: part.source_entity_index,
                    generation: economy.slot_generation(part.source_entity_index),
                    root_slot: part.entity_id,
                    life: part.life,
                    attacker: part.word_0x26,
                    position: part.position,
                    half_width: part.render_pitch,
                    vertical_offset: part.render_yaw,
                    half_height: part.render_fov,
                },
            )
        }));
        targets.sort_unstable_by_key(|target| target.source_slot);
        targets
    }

    fn level_three_dragon_targets_at_impact(
        targets: &[DragonFireballTarget],
        impact: crate::Position,
    ) -> Vec<DragonFireballTarget> {
        targets
            .iter()
            .copied()
            .filter(|target| {
                crate::level1_mission::source_entities_overlap(
                    impact,
                    48,
                    50,
                    50,
                    target.position,
                    target.half_width,
                    target.vertical_offset,
                    target.half_height,
                )
            })
            .collect()
    }

    fn nearest_level_three_dragon_target_for_test(
        session: &GameSession<Mc2CampaignBackend>,
        desired_root: Option<u16>,
    ) -> Option<DragonFireballTarget> {
        let targets = level_three_dragon_fireball_targets(session);
        let player = session.backend().campaign.simulation().state.position;
        targets
            .iter()
            .copied()
            // Each body retains independent health. The source root only
            // adopts a lower linked-child life; damage across healthier
            // segments is not summed. Aim at the root's current kill carrier.
            .filter(|target| target.source_slot == target.root_slot)
            .filter(|target| desired_root.is_none_or(|root| target.root_slot == root))
            .min_by_key(|target| {
                let dx = i64::from(i32::from(
                    target.position.x.wrapping_sub(player.x).cast_signed(),
                ));
                let dy = i64::from(i32::from(
                    target.position.y.wrapping_sub(player.y).cast_signed(),
                ));
                dx * dx + dy * dy
            })
    }

    #[test]
    fn campaign_backend_guardian_public_targeting_uses_root_health_carrier() {
        let root = level_three_descriptor_fixture_path();
        let catalog = default_catalog().unwrap();
        let definition = Arc::new(load_mc2_campaign(&root, &catalog).unwrap());
        let mut session = GameSession::open(
            &Mc2CampaignAdapter,
            definition,
            65,
            Mc2CampaignInputs::new(&root),
        )
        .unwrap();
        session
            .backend_mut()
            .campaign
            .simulation_mut()
            .activate_authored_group_prerequisite_for_test(1)
            .unwrap();
        let targets = level_three_dragon_fireball_targets(&session);
        assert_eq!(targets.len(), 34);
        let roots = targets
            .iter()
            .filter(|target| target.source_slot == target.root_slot)
            .copied()
            .collect::<Vec<_>>();
        assert_eq!(roots.len(), 2);
        let hash_before = session.backend().campaign.state_hash();
        for root in roots {
            let bodies = targets
                .iter()
                .filter(|target| {
                    target.root_slot == root.source_slot && target.source_slot != root.source_slot
                })
                .collect::<Vec<_>>();
            assert_eq!(bodies.len(), 16);
            assert!(bodies.iter().all(|body| body.life == root.life));
            assert_eq!(
                nearest_level_three_dragon_target_for_test(&session, Some(root.source_slot)),
                Some(root),
                "public aim must concentrate damage in this root's source kill carrier"
            );
            assert_eq!(
                level_three_dragon_launch_gap_for_test(
                    session.backend().campaign.simulation(),
                    Some(root.source_slot),
                )
                .map(|(target, _, _)| target),
                Some(root),
                "ordinary pursuit and hand-launch admission must use the same current root"
            );
            let body_slot = bodies[0].source_slot;
            assert!(
                nearest_level_three_dragon_target_for_test(&session, Some(body_slot)).is_none()
            );
            assert!(
                level_three_dragon_launch_gap_for_test(
                    session.backend().campaign.simulation(),
                    Some(body_slot),
                )
                .is_none(),
                "a body source slot may not substitute for the requested root identity"
            );
        }
        assert_eq!(session.backend().campaign.state_hash(), hash_before);
    }

    #[derive(Debug, Eq, PartialEq)]
    enum DragonFireballCastOutcome {
        AllocationRace,
        Miss,
        Damage(Vec<SkeletonFireballDamageReceipt>),
    }

    fn settle_level_three_dragon_damage_for_test(session: &mut GameSession<Mc2CampaignBackend>) {
        let player = session.backend().campaign.simulation().state.entity_index;
        let mut history = Vec::new();
        for _ in 0..=16 {
            let economy = session.backend().campaign.simulation().economy();
            let pending_roots = economy
                .authored_class5()
                .iter()
                .filter(|root| {
                    root.active
                        && root.model == 0
                        && root.life >= 0
                        && root.pending_word_0x62 == player
                })
                .map(|root| root.source_entity_index)
                .collect::<BTreeSet<_>>();
            let pending_parts = economy
                .authored_dragon_parts()
                .iter()
                .filter(|part| part.active && part.life >= 0 && part.pending_word_0x62 == player)
                .map(|part| part.source_entity_index)
                .collect::<BTreeSet<_>>();
            let unsettled_roots = economy
                .authored_class5()
                .iter()
                .filter(|root| root.active && root.model == 0 && root.life >= 0)
                .filter(|root| {
                    economy.authored_dragon_parts().iter().any(|part| {
                        part.active
                            && part.entity_id == root.source_entity_index
                            && part.life < root.life
                    })
                })
                .map(|root| root.source_entity_index)
                .collect::<BTreeSet<_>>();
            history.push(
                economy
                    .authored_class5()
                    .iter()
                    .filter(|root| root.active && root.model == 0)
                    .map(|root| (root.source_entity_index, root.action, root.life))
                    .collect::<Vec<_>>(),
            );
            if pending_roots.is_empty() && pending_parts.is_empty() && unsettled_roots.is_empty() {
                return;
            }
            session
                .step(guard(session), GameCommand::default())
                .unwrap();
        }
        panic!("Dragon damage did not settle across its 16-part source chain: {history:?}");
    }

    const DRAGON_FIREBALL_TRAVEL_RANGE: u32 = 0x2000;

    fn level_three_source_safe_flight_command(
        state: crate::FlightState,
        desired: i16,
        stop: bool,
    ) -> GameCommand {
        let correction = crate::turn_toward(state.yaw, desired, 127);
        let aligned = correction.unsigned_abs() <= 24;
        let brake = if state.target_speed < 0 {
            LongitudinalControl::Accelerate
        } else if state.target_speed > 0 {
            LongitudinalControl::Decelerate
        } else {
            LongitudinalControl::Coast
        };
        let moving = state.target_speed != 0 || state.actual_speed != 0;
        let (longitudinal, roll_axis) = if stop || !aligned {
            if moving {
                (brake, 0)
            } else {
                (LongitudinalControl::Coast, correction.clamp(-24, 24) as i8)
            }
        } else if state.target_speed < 0 || state.actual_speed < 0 {
            (brake, 0)
        } else {
            (
                LongitudinalControl::Accelerate,
                correction.clamp(-24, 24) as i8,
            )
        };
        GameCommand {
            longitudinal,
            roll_axis,
            ..GameCommand::default()
        }
    }

    fn level_three_dragon_retreat_command(
        session: &GameSession<Mc2CampaignBackend>,
        retreat_heading: i16,
    ) -> GameCommand {
        let state = session.backend().campaign.simulation().state;
        level_three_source_safe_flight_command(state, retreat_heading, false)
    }

    fn level_three_initial_dragon_retreat_heading(
        session: &GameSession<Mc2CampaignBackend>,
    ) -> i16 {
        let state = session.backend().campaign.simulation().state;
        level_three_dragon_fireball_targets(session)
            .into_iter()
            .filter(|target| target.source_slot == target.root_slot)
            .min_by_key(|target| {
                let dx = i32::from(
                    target
                        .position
                        .x
                        .wrapping_sub(state.position.x)
                        .cast_signed(),
                );
                let dy = i32::from(
                    target
                        .position
                        .y
                        .wrapping_sub(state.position.y)
                        .cast_signed(),
                );
                dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy))
            })
            .map(|root| {
                i16::try_from(crate::heading_for_positions(root.position, state.position))
                    .expect("source heading is 11-bit")
            })
            .unwrap_or(state.yaw)
    }

    fn level_three_dragon_survival_snapshot_for_test(
        session: &GameSession<Mc2CampaignBackend>,
        phase: &str,
        public_requests: usize,
    ) -> String {
        let compatibility = session.backend().campaign.simulation();
        let economy = compatibility.economy();
        let player = compatibility.shared_spells().player_entity();
        let raw_player =
            &compatibility.session.state.live.economy.entities[usize::from(player.index)];
        let raw_record = raw_player.record_bytes();
        let player_mailbox = (
            i32::from_le_bytes(raw_record[98..102].try_into().unwrap()),
            u16::from_le_bytes(raw_record[102..104].try_into().unwrap()),
        );
        let distance = |from: crate::Position, to: crate::Position| {
            let dx = i32::from(to.x.wrapping_sub(from.x).cast_signed());
            let dy = i32::from(to.y.wrapping_sub(from.y).cast_signed());
            crate::legacy_sqrt(
                dx.wrapping_mul(dx)
                    .wrapping_add(dy.wrapping_mul(dy))
                    .cast_unsigned(),
            )
        };
        let dragon_slots = economy
            .authored_dragons()
            .iter()
            .map(|dragon| dragon.source_entity_index)
            .collect::<BTreeSet<_>>();
        let hostile_owner_slots = dragon_slots
            .iter()
            .copied()
            .chain(level_three_imported_worm_attackers_for_test(compatibility))
            .collect::<BTreeSet<_>>();
        let roots = economy
            .authored_class5()
            .iter()
            .filter(|root| root.active && root.model == 0)
            .map(|root| {
                (
                    root.source_entity_index,
                    economy.slot_generation(root.source_entity_index),
                    root.action,
                    root.life,
                    root.word_0x96_150,
                    distance(player.position, root.position),
                )
            })
            .collect::<Vec<_>>();
        let hostile_projectiles = economy
            .fireball_projectiles()
            .iter()
            .filter(|projectile| {
                projectile.active
                    && projectile.owner_entity_index != player.index
                    && hostile_owner_slots.contains(&projectile.owner_entity_index)
            })
            .map(|projectile| {
                (
                    projectile.source_entity_index,
                    economy.slot_generation(projectile.source_entity_index),
                    projectile.owner_entity_index,
                    projectile.position,
                    projectile.life,
                )
            })
            .collect::<Vec<_>>();
        let hostile_impacts = economy
            .model17_spawned_children()
            .iter()
            .filter(|impact| {
                impact.active
                    && impact.source_class == 10
                    && impact.model == 0
                    && impact.parent_entity_id != player.index
                    && hostile_owner_slots.contains(&impact.parent_entity_id)
            })
            .map(|impact| {
                (
                    impact.source_entity_index,
                    economy.slot_generation(impact.source_entity_index),
                    impact.parent_entity_id,
                    impact.position,
                    impact.life,
                )
            })
            .collect::<Vec<_>>();
        let castle = economy.castle().map(|castle| {
            (
                castle.source_entity_index,
                castle.position,
                distance(player.position, castle.position),
                economy.player_castle_shift_aabb_overlap(player),
            )
        });
        format!(
            "{phase}: requests={public_requests} player=(life={},mailbox={player_mailbox:?},pos={:?},yaw={},roll={},speed=({},{})) castle={castle:?} roots={roots:?} hostile_projectiles={hostile_projectiles:?} hostile_impacts={hostile_impacts:?}",
            player.life,
            player.position,
            compatibility.state.yaw,
            compatibility.state.roll_accumulator,
            compatibility.state.target_speed,
            compatibility.state.actual_speed,
        )
    }

